 53: export const AuthFrame = ({ children, wide }) => (
 54:   <div className="luxury-auth-page" dir="ltr">
 55:     <div className="auth-card">
 56:       <section className="luxury-left-col" dir="rtl">
 57:         <div className="luxury-top-bar">
 58:           <span className="luxury-brand-btn">
 59:             <svg width="22" height="22" viewBox="0 0 24 24" aria-hidden="true"><polygon points="4,10 10,4 10,13 4,19" fill="#09090b" /><polygon points="11,11 17,5 17,14 11,20" fill="#09090b" /></svg>
 60:             <span className="luxury-brand-tag">SOPHIE · WHOLESALE</span>
 61:           </span>
 62:           <button className="luxury-lang-btn" lang="en">English</button>
 63:         </div>
 64:         <div className="luxury-form-wrap" style={wide ? { maxWidth: 460 } : null}>{children}</div>
 65:       </section>
 66:       <section className="luxury-right-col"><Halftone /></section>
 67:     </div>
 68:   </div>
 69: );
