 71: /* ---------- 4. Application status ---------- */
 72: export const ApplicationStatus = ({ status, onRefresh, onLogout, onEnter }) => {
 73:   const s = APP_STATUS[status];
 74:   const [refreshing, setRefreshing] = useState(false);
 75:   const { state, retry } = React.useContext(DataStateCtx);
 76:   const refresh = () => { setRefreshing(true); setTimeout(() => { setRefreshing(false); onRefresh && onRefresh(); }, 900); };
 77:   const reason = status === 'rejected' ? 'البطاقة الضريبية المرفقة غير واضحة، والسجل التجاري منتهي الصلاحية.'
 78:     : status === 'suspended' ? 'تم إيقاف الحساب مؤقتًا لتجاوز مدة السداد المتفق عليها. تواصل مع إدارة الحسابات.' : null;
 79: 
 80:   return (
 81:     <AuthFrame wide>
 82:       <h1 className="luxury-title">حالة طلب الاعتماد</h1>
 83:       <p className="luxury-sub">نراجع بيانات شركتك ومستنداتها قبل تفعيل أسعار الجملة والشراء الآجل وعروض الأسعار.</p>
 84: 
 85:       {state === 'loading' ? (
 86:         <div className="luxury-auth-fields">{[80, 60, 90, 70].map((w, i) => <div key={i} className="sk" style={{ height: 14, width: w + '%' }} />)}</div>
 87:       ) : state === 'error' ? (
 88:         <div className="luxury-auth-fields">
 89:           <p className="luxury-form-error" role="alert">تعذر تحميل حالة الطلب. حاول مرة أخرى.</p>
 90:           <button className="pill-btn-primary" onClick={retry}>إعادة المحاولة</button>
 91:         </div>
 92:       ) : (
 93:         <div className="luxury-auth-fields">
 94:           <div className="as-status" data-s={status}>
 95:             <div className="as-status-ic"><i className={`fa-solid ${s.icon}`} /></div>
 96:             <div style={{ flex: 1, minWidth: 0 }}>
 97:               <div className="luxury-field-label" style={{ margin: 0, color: '#737373', fontWeight: 400 }}>حالة الحساب</div>
 98:               <div className="as-status-label">{s.label}</div>
 99:             </div>
100:             {status === 'approved' && <div className="as-date"><span>تاريخ الاعتماد</span><b className="num">{ACCOUNT.approved_at}</b></div>}
101:           </div>
102: 
103:           {reason && <p className="luxury-form-error" role="alert"><b>{status === 'rejected' ? 'سبب الرفض: ' : 'سبب الإيقاف: '}</b>{reason}</p>}
104:           {status === 'pending' && <p className="luxury-success">المراجعة عادةً تستغرق من يوم إلى يومي عمل. هيوصلك إشعار بمجرد تغيير الحالة.</p>}
105: 
106:           <div className="as-block">
107:             <div className="as-block-title">بيانات الحساب والشركة</div>
108:             <dl className="as-kv">
109:               <dt>اسم التاجر</dt><dd>{ACCOUNT.name}</dd>
110:               <dt>الموبايل</dt><dd className="num">{ACCOUNT.phone}</dd>
111:               <dt>البريد</dt><dd className="num">{ACCOUNT.email}</dd>
112:               <dt>الشركة</dt><dd>{ACCOUNT.company}</dd>
113:               <dt>الرقم الضريبي</dt><dd className="num">{ACCOUNT.tax_number}</dd>
114:               <dt>السجل التجاري</dt><dd>{ACCOUNT.commercial_register}</dd>
115:             </dl>
116:           </div>
117: 
118:           <div className="as-block">
119:             <div className="as-block-title">المستندات <span className="num" style={{ color: '#a3a3a3' }}>{DOCS.length}</span></div>
120:             <ul className="luxury-file-list as-docs">
121:               {DOCS.map((d) => {
122:                 const [l, v] = DOC_STATUS[status === 'approved' ? 'approved' : d.status];
123:                 const rej = status !== 'approved' && d.status === 'rejected';
124:                 return (
125:                   <li key={d.name} className={rej ? 'is-rej' : ''}>
126:                     <span>
127:                       <i className={`fa-regular ${d.name.endsWith('.pdf') ? 'fa-file-pdf' : 'fa-file-image'}`} />
128:                       <span><b>{d.type}</b><small className="num">{d.name}</small>{rej && d.note && <em>{d.note}</em>}</span>
129:                     </span>
130:                     <span className={`badge ${v}`}>{l}</span>
131:                   </li>
132:                 );
133:               })}
134:             </ul>
135:             {(status === 'rejected' || DOCS.some((d) => d.status === 'rejected')) && status !== 'approved' && (
136:               <p className="luxury-field-hint" style={{ marginBottom: 0 }}><i className="fa-solid fa-circle-info" /> إعادة رفع المستندات غير متاحة من البوابة حاليًا — تواصل مع فريق المبيعات لاستكمالها.</p>
137:             )}
138:           </div>
139: 
140:           {status === 'approved'
141:             ? <button className="pill-btn-primary" onClick={onEnter}>الدخول إلى بوابة الجملة</button>
142:             : <button className="pill-btn-primary" onClick={refresh} disabled={refreshing}>{refreshing ? <><span className="spin" style={{ marginInlineEnd: 10 }} /> جارٍ التحديث…</> : 'تحديث حالة الطلب'}</button>}
143:           <div className="luxury-bottom-switch" style={{ marginTop: 4 }}>
144:             <button className="luxury-switch-link" onClick={onLogout}>تسجيل الخروج</button>
145:           </div>
146:         </div>
147:       )}
148:     </AuthFrame>
149:   );
150: };
