152: /* ---------- 5. Forgot / reset password ---------- */
153: export const ForgotPassword = ({ onBack, onGoReset }) => {
154:   const [login, setLogin] = useState('');
155:   const [sent, setSent] = useState(false);
156:   const [busy, setBusy] = useState(false);
157:   const [err, setErr] = useState('');
158:   const submit = (e) => {
159:     e.preventDefault();
160:     if (!login.trim()) { setErr('أدخل البريد الإلكتروني أو رقم الموبايل.'); return; }
161:     setErr(''); setBusy(true); setTimeout(() => { setBusy(false); setSent(true); }, 900);
162:   };
163:   return (
164:     <AuthFrame>
165:       <h1 className="luxury-title">نسيت كلمة المرور؟</h1>
166:       <p className="luxury-sub">أدخل البريد أو رقم الموبايل المسجل، وهنبعتلك رابط لإعادة تعيين كلمة المرور.</p>
167:       {sent ? (
168:         <div className="luxury-auth-fields">
169:           <p className="luxury-success" role="status"><b>تم إرسال الطلب.</b><br />لو الحساب موجود، هيوصلك رابط إعادة التعيين على <span className="num">{login}</span> خلال دقائق. الرابط صالح لمدة 60 دقيقة.</p>
170:           <button className="pill-btn-primary" onClick={onGoReset}>عندي الرابط — إعادة التعيين</button>
171:           <div className="luxury-bottom-switch"><button className="luxury-switch-link" onClick={() => setSent(false)}>إعادة الإرسال</button><span className="luxury-link-sep">·</span><button className="luxury-switch-link" onClick={onBack}>العودة لتسجيل الدخول</button></div>
172:         </div>
173:       ) : (
174:         <form className="luxury-form" onSubmit={submit} noValidate>
175:           <div>
176:             <label className="luxury-field-label" htmlFor="fp">البريد الإلكتروني أو رقم الموبايل<span className="luxury-req-mark">*</span></label>
177:             <input id="fp" className="pill-input" dir="ltr" value={login} onChange={(e) => setLogin(e.target.value)} placeholder="name@company.com / 01xxxxxxxxx" aria-invalid={!!err} />
178:             {err && <p className="luxury-field-error" role="alert">{err}</p>}
179:           </div>
180:           <button className="pill-btn-primary" disabled={busy}>{busy ? 'جارٍ الإرسال…' : 'إرسال رابط إعادة التعيين'}</button>
181:           <div className="luxury-bottom-switch"><button type="button" className="luxury-switch-link" onClick={onBack}>العودة لتسجيل الدخول</button></div>
182:         </form>
183:       )}
184:     </AuthFrame>
185:   );
186: };
