188: export const ResetPassword = ({ onBack, linkState = 'valid', onForgot }) => {
189:   const [show, setShow] = useState(false);
190:   const [p1, setP1] = useState(''); const [p2, setP2] = useState('');
191:   const [errs, setErrs] = useState({});
192:   const [done, setDone] = useState(false);
193:   const submit = (e) => {
194:     e.preventDefault();
195:     const er = {};
196:     if (p1.length < 8) er.p1 = 'كلمة المرور لازم تكون 8 حروف على الأقل.';
197:     if (p1 !== p2) er.p2 = 'تأكيد كلمة المرور غير مطابق.';
198:     setErrs(er); if (!Object.keys(er).length) setDone(true);
199:   };
200:   const rules = [[p1.length >= 8, '8 حروف على الأقل'], [/[A-Za-z]/.test(p1) && /\d/.test(p1), 'حروف وأرقام'], [p1 && p1 === p2, 'التأكيد مطابق']];
201:   if (linkState !== 'valid') return (
202:     <AuthFrame>
203:       <h1 className="luxury-title">{linkState === 'expired' ? 'انتهت صلاحية الرابط' : 'الرابط غير صالح'}</h1>
204:       <p className="luxury-sub">{linkState === 'expired' ? 'روابط إعادة التعيين صالحة لمدة 60 دقيقة فقط. اطلب رابط جديد.' : 'الرابط ده مستخدم قبل كده أو ناقص. اطلب رابط جديد من صفحة استعادة كلمة المرور.'}</p>
205:       <p className="luxury-form-error" role="alert">لا يمكن إعادة تعيين كلمة المرور بهذا الرابط.</p>
206:       <button className="pill-btn-primary" style={{ marginTop: 22 }} onClick={onForgot}>طلب رابط جديد</button>
207:       <div className="luxury-bottom-switch"><button className="luxury-switch-link" onClick={onBack}>العودة لتسجيل الدخول</button></div>
208:     </AuthFrame>
209:   );
210:   return (
211:     <AuthFrame>
212:       <h1 className="luxury-title">{done ? 'تم تغيير كلمة المرور' : 'إعادة تعيين كلمة المرور'}</h1>
213:       <p className="luxury-sub">{done ? 'تقدر دلوقتي تسجل الدخول بكلمة المرور الجديدة.' : 'اختر كلمة مرور جديدة لحسابك.'}</p>
214:       {done ? (
215:         <div className="luxury-auth-fields">
216:           <p className="luxury-success" role="status"><span className="luxury-verified-badge">تم التحديث بنجاح</span></p>
217:           <button className="pill-btn-primary" onClick={onBack}>تسجيل الدخول</button>
218:         </div>
219:       ) : (
220:         <form className="luxury-form" onSubmit={submit} noValidate>
221:           <div>
222:             <label className="luxury-field-label">البريد الإلكتروني</label>
