 30:       <PageHead en="Dashboard" ar={<>أهلًا {ACCOUNT.name.split(' ')[0]} — {ACCOUNT.company}</>} />
 31:       <Async rows={3} cols={4} empty={<Empty title="لا توجد بيانات بعد" />}>
 32:         <div className="kpis">
