 39:             <span className="kpi-value">{fmt(ACCOUNT.used_credit, 0)}<small>EGP</small></span>
 40:             <div className="kpi-bar"><span style={{ width: pct + '%' }} /></div>
 41:             <span className="kpi-foot"><span className="num">{pct}%</span> من الحد</span>
 42:           </div>
 43:           <div className="kpi">
 44:             <span className="kpi-en">AVAILABLE</span><span className="kpi-label">المتاح للشراء الآجل</span>
 45:             <span className="kpi-value" style={{ color: 'var(--accent)' }}>{fmt(ACCOUNT.available_credit, 0)}<small>EGP</small></span>
 46:           </div>
 47:           <div className="kpi" style={{ cursor: 'pointer' }} onClick={() => go('orders')}>
 48:             <span className="kpi-en">IN PROGRESS</span><span className="kpi-label">طلبات جاري تنفيذها</span>
 49:             <span className="kpi-value">{ACCOUNT.in_progress_orders_count}</span>
 50:             <span className="kpi-foot">عرض الطلبات <i className="fa-solid fa-arrow-left" style={{ fontSize: 10 }} /></span>
 51:           </div>
 52:         </div>
 53: 
 54:         <div className="dash-shortcuts">
 55:           {shortcuts.map(([r, ic, l, en]) => (
