 64:         <div className="dash-tables">
 65:           <Panel title="آخر الفواتير" en="LATEST 5 INVOICES" body={false} action={<button className="btn-link muted" onClick={() => go('invoices')}>عرض الكل</button>}>
 66:             <div className="tbl-wrap"><table className="tbl">
