 76:             </table></div>
 77:           </Panel>
 78:           <Panel title="آخر عروض الأسعار" en="LATEST 5 QUOTATIONS" body={false} action={<button className="btn-link muted" onClick={() => go('quotes')}>عرض الكل</button>}>
 79:             <div className="tbl-wrap"><table className="tbl">
