 81:               <tbody>{QUOTES.slice(0, 5).map((q) => (
 82:                 <tr key={q.id} className="is-click" onClick={() => go('quote', q.id)}>
 83:                   <td><div className="strong num">{q.number}</div><div className="soft small num">{q.created}</div></td>
 84:                   <td><Badge map={QUOTE_STATUS} k={q.status} /></td>
 85:                   <td className="num">{q.valid_until || '—'}</td>
 86:                   <td className="t-end strong num">{q.total != null ? fmt(q.total) : '—'}</td>
 87:                 </tr>))}</tbody>
 88:             </table></div>
 89:           </Panel>
 90:         </div>
 91:       </Async>
 92:     </>
 93:   );
 94: };
