 96: /* ---------- 7. Catalog ---------- */
 97: export const Catalog = () => {
 98:   const { addToCart, toast } = useApp();
 99:   const [q, setQ] = useState('');
100:   const [page, setPage] = useState(1);
101:   const [open, setOpen] = useState(null);
102:   const [exporting, setExporting] = useState(null);
103:   const list = PRODUCTS.filter((p) => !q || [p.name_ar, p.name_en, ...p.variants.map((v) => v.sku)].join(' ').toLowerCase().includes(q.toLowerCase()));
104:   const doExport = (f) => { setExporting(f); setTimeout(() => { setExporting(null); toast(`تم تنزيل قائمة الأسعار ${f.toUpperCase()}`); }, 1100); };
105:   return (
106:     <>
107:       <PageHead en="Price List" ar="كتالوج الجملة بأسعار حسابك وشرائح الكميات">
108:         <button className="btn-pill" onClick={() => doExport('pdf')} disabled={!!exporting}>{exporting === 'pdf' ? <span className="spin" /> : <i className="fa-regular fa-file-pdf" />} تنزيل PDF</button>
109:         <button className="btn-pill" onClick={() => doExport('xlsx')} disabled={!!exporting}>{exporting === 'xlsx' ? <span className="spin" /> : <i className="fa-regular fa-file-excel" />} تنزيل Excel</button>
110:       </PageHead>
111:       <section className="panel">
112:         <div className="toolbar">
113:           <div className="search"><i className="fa-solid fa-magnifying-glass" /><input className="line-input" placeholder="ابحث بالاسم أو SKU…" value={q} onChange={(e) => { setQ(e.target.value); setPage(1); }} /></div>
114:           <span className="soft small"><span className="num">{list.length * 12}</span> منتج · الأسعار شاملة خصم حسابك</span>
115:         </div>
116:         <Async rows={6} cols={6} isEmpty={list.length === 0} empty={<Empty icon="fa-magnifying-glass" title="مفيش نتائج" desc={q ? `مفيش منتج أو SKU يطابق «${q}».` : 'لا توجد منتجات متاحة حاليًا.'} action={q && <button className="btn-pill" onClick={() => setQ('')}>مسح البحث</button>} />}>
117:           <div className="tbl-wrap"><table className="tbl cat-tbl">
118:             <thead><tr><th>المنتج</th><th>المتغيرات</th><th>السعر الأساسي</th><th>سعرك</th><th>شرائح الكميات</th><th>المتاح</th><th></th></tr></thead>
119:             <tbody>{list.map((p) => {
120:               const v = p.variants[0];
121:               const stock = p.variants.reduce((a, x) => a + x.qty, 0);
122:               return (
123:                 <tr key={p.id}>
124:                   <td><div className="prod-cell"><Thumb sm /><div><div className="prod-name">{p.name_ar}</div><div className="prod-en">{p.name_en}</div></div></div></td>
125:                   <td><span className="num strong">{p.variants.length}</span> <span className="soft small">{p.variants.map((x) => x.label).join(' · ')}</span></td>
126:                   <td><span className="strike num">{fmt(p.base)}</span></td>
127:                   <td className="strong num">{p.variants.length > 1 && Math.min(...p.variants.map((x) => x.price)) !== Math.max(...p.variants.map((x) => x.price)) ? 'من ' : ''}{fmt(Math.min(...p.variants.map((x) => x.price)))}</td>
128:                   <td>{v.tiers.map(([m, pr]) => <span key={m} className="tier"><span className="num">{m}+</span> ← <b className="num">{fmt(pr, 0)}</b></span>)}</td>
129:                   <td>{stock === 0 ? <span className="badge danger">نفدت الكمية</span> : <span className={`num ${stock < 50 ? '' : 'strong'}`} style={stock < 50 ? { color: '#b45309', fontWeight: 600 } : null}>{stock}</span>}</td>
130:                   <td className="t-end"><button className="btn-pill is-dark sm" onClick={() => setOpen(p)}>اختيار الكمية</button></td>
131:                 </tr>);
132:             })}</tbody>
133:           </table></div>
134:           <Pager page={page} pages={4} total={96} per={24} onPage={setPage} />
135:         </Async>
136:       </section>
137:       <p className="note mt-16"><i className="fa-solid fa-circle-info" />السعر النهائي لكل بند يتحسب في السلة حسب الكمية والشريحة المطبقة وقت الطلب.</p>
138:       {open && <VariantModal product={open} onClose={() => setOpen(null)} onAdd={(lines) => { addToCart(lines); setOpen(null); }} />}
139:     </>
140:   );
141: };
142: 
143: export const tierPrice = (v, qty) => { let p = v.price; v.tiers.forEach(([m, pr]) => { if (qty >= m) p = pr; }); return p; };
144: 
145: export const VariantModal = ({ product, onClose, onAdd }) => {
146:   const [qty, setQty] = useState(Object.fromEntries(product.variants.map((v) => [v.id, 0])));
147:   const lines = product.variants.filter((v) => qty[v.id] > 0).map((v) => ({ v: { ...v, product }, qty: qty[v.id] }));
148:   const total = lines.reduce((a, l) => a + tierPrice(l.v, l.qty) * l.qty, 0);
149:   const over = product.variants.some((v) => qty[v.id] > v.qty);
150:   return (
151:     <Modal wide title={product.name_ar} onClose={onClose} icon={<Thumb sm />}
152:       foot={<><span className="muted small" style={{ marginInlineEnd: 'auto' }}>تقديري: <Money v={total} strong /></span>
153:         <button className="btn-pill" onClick={onClose}>إلغاء</button>
154:         <button className="btn-pill is-dark" disabled={!lines.length || over} onClick={() => onAdd(lines)}><i className="fa-solid fa-cart-plus" /> إضافة للسلة {lines.length > 0 && <span className="num">({lines.reduce((a, l) => a + l.qty, 0)})</span>}</button></>}>
155:       <p className="prod-en" style={{ textAlign: 'right', marginTop: -10 }}>{product.name_en} · السعر الأساسي <span className="strike">{fmt(product.base)}</span></p>
156:       <div className="tbl-wrap mt-16"><table className="tbl">
157:         <thead><tr><th>المتغير</th><th>SKU / باركود</th><th>سعرك</th><th>الشرائح</th><th>المتاح</th><th>الكمية</th></tr></thead>
158:         <tbody>{product.variants.map((v) => {
159:           const q = qty[v.id]; const bad = q > v.qty;
160:           return (
161:             <tr key={v.id} className={bad ? 'is-error' : ''}>
162:               <td className="strong">{v.label}</td>
163:               <td><div className="sku">{v.sku}</div><div className="sku soft">{v.barcode}</div></td>
164:               <td className="strong num">{fmt(q ? tierPrice(v, q) : v.price)}</td>
165:               <td>{v.tiers.map(([m, pr]) => <span key={m} className="tier" style={q >= m ? { background: 'var(--accent)', color: '#fff', borderColor: 'var(--accent)' } : null}><span className="num">{m}+</span> <b className="num">{fmt(pr, 0)}</b></span>)}</td>
166:               <td className="num">{v.qty === 0 ? <span className="badge danger">نفدت</span> : v.qty}</td>
167:               <td>{v.qty === 0 ? <span className="soft small">غير متاح</span> : <><Qty value={q} onChange={(n) => setQty({ ...qty, [v.id]: n })} />{bad && <p className="f-error">المتاح <span className="num">{v.qty}</span> فقط</p>}</>}</td>
168:             </tr>);
169:         })}</tbody>
170:       </table></div>
171:     </Modal>
172:   );
173: };
