175: /* ---------- 8–9. Quick order + Excel import ---------- */
176: export const QuickOrder = () => {
177:   const { addToCart, go, toast } = useApp();
178:   const [tab, setTab] = useState('manual');
179:   const blank = () => ({ code: '', qty: '' });
180:   const [rows, setRows] = useState([{ code: 'SPH-TT-001-BLK', qty: '24' }, { code: '6224001014011', qty: '40' }, { code: 'SPH-BP-007-GRY-M', qty: '30' }, { code: 'SPH-XX-999', qty: '10' }, { code: 'SPH-TT-001-CRM', qty: '12' }, blank()]);
181:   const [looked, setLooked] = useState(false);
182:   const [busy, setBusy] = useState(false);
183:   const set = (i, k, v) => { const r = [...rows]; r[i] = { ...r[i], [k]: v }; if (i === rows.length - 1 && v) r.push(blank()); setRows(r); setLooked(false); };
184:   const res = rows.map((r) => {
185:     if (!r.code.trim()) return null;
186:     const v = findVariant(r.code); const q = parseInt(r.qty || '0', 10);
187:     if (!v) return { err: 'الصنف غير موجود' };
188:     if (!q) return { v, err: 'أدخل الكمية' };
189:     if (v.qty === 0) return { v, q, err: 'نفدت الكمية' };
190:     if (q > v.qty) return { v, q, warn: `المتاح ${v.qty} فقط` };
191:     const unit = tierPrice(v, q);
192:     return { v, q, unit, total: unit * q, ok: true };
193:   });
194:   const valid = res.filter((x) => x && x.ok);
195:   const known = res.filter((x) => x && x.v && x.unit);
196:   const lookup = () => { setBusy(true); setTimeout(() => { setBusy(false); setLooked(true); }, 700); };
197:   return (
198:     <>
199:       <PageHead en="Quick Order" ar="أدخل الأكواد والكميات مباشرة، أو ارفع ملف Excel">
200:         <Seg value={tab} onChange={setTab} options={[{ value: 'manual', label: 'إدخال مباشر', icon: 'fa-keyboard' }, { value: 'import', label: 'استيراد ملف', icon: 'fa-file-arrow-up' }]} />
201:       </PageHead>
202:       {tab === 'manual' ? (
203:         <div className="grid-2" style={{ gridTemplateColumns: '1fr 320px' }}>
204:           <section className="panel">
205:             <div className="toolbar">
206:               <span className="muted small">الصق من Excel مباشرة: عمود SKU أو باركود، ثم الكمية. حتى <span className="num">500</span> بند.</span>
207:               <button className="btn-link muted" onClick={() => { setRows([blank()]); setLooked(false); }}>مسح الكل</button>
208:             </div>
209:             <div className="tbl-wrap"><table className="tbl qo-tbl">
210:               <thead><tr><th style={{ width: 36 }}>#</th><th style={{ width: 210 }}>SKU أو باركود</th><th style={{ width: 96 }}>الكمية</th><th>الصنف</th><th>سعر الوحدة</th><th className="t-end">الإجمالي</th><th></th></tr></thead>
211:               <tbody>{rows.map((r, i) => {
212:                 const x = looked ? res[i] : null;
213:                 return (
214:                   <tr key={i} className={x && x.err ? 'is-error' : x && x.warn ? 'is-warn' : ''}>
215:                     <td className="soft num">{i + 1}</td>
216:                     <td><input className={`box-input ltr${x && x.err && !x.v ? ' is-invalid' : ''}`} value={r.code} placeholder="SPH-…" onChange={(e) => set(i, 'code', e.target.value)} /></td>
217:                     <td><input className={`box-input ltr${x && x.err === 'أدخل الكمية' ? ' is-invalid' : ''}`} value={r.qty} inputMode="numeric" onChange={(e) => set(i, 'qty', e.target.value.replace(/\D/g, ''))} /></td>
218:                     <td>{!x ? <span className="soft small">{r.code ? 'اضغط «فحص البنود»' : ''}</span> : x.v ? <><div className="strong small">{x.v.product.name_ar} — {x.v.label}</div>{x.err ? <p className="f-error" style={{ margin: 0 }}><i className="fa-solid fa-circle-exclamation" />{x.err}</p> : x.warn ? <p className="f-error" style={{ margin: 0, color: '#b45309' }}><i className="fa-solid fa-triangle-exclamation" />{x.warn}</p> : <span className="small" style={{ color: '#047857' }}><i className="fa-solid fa-check" /> متاح</span>}</> : <p className="f-error" style={{ margin: 0 }}><i className="fa-solid fa-circle-xmark" />{x.err}</p>}</td>
219:                     <td className="num">{x && x.unit ? fmt(x.unit) : '—'}</td>
220:                     <td className="t-end strong num">{x && x.total ? fmt(x.total) : '—'}</td>
221:                     <td>{r.code && <button className="btn-link muted" aria-label="حذف" onClick={() => setRows(rows.filter((_, j) => j !== i))}><i className="fa-solid fa-xmark" /></button>}</td>
222:                   </tr>);
223:               })}</tbody>
224:             </table></div>
225:           </section>
226:           <aside className="panel" style={{ position: 'sticky', top: 100 }}>
227:             <div className="panel-body">
228:               <h2 className="panel-title">ملخص الفحص</h2>
229:               <div className="mt-16">
230:                 <div className="sum-row"><span>إجمالي البنود</span><strong className="num">{rows.filter((r) => r.code).length}</strong></div>
231:                 <div className="sum-row"><span>بنود معروفة</span><strong className="num">{looked ? known.length : '—'}</strong></div>
232:                 <div className="sum-row"><span>بنود صالحة للإضافة</span><strong className="num" style={{ color: 'var(--accent)' }}>{looked ? valid.length : '—'}</strong></div>
233:                 <div className="sum-row"><span>بنود بها أخطاء</span><strong className="num" style={{ color: '#b91c1c' }}>{looked ? res.filter((x) => x && !x.ok).length : '—'}</strong></div>
234:                 <div className="sum-total"><span>قيمة البنود الصالحة</span><span className="num">{looked ? fmt(valid.reduce((a, x) => a + x.total, 0)) : '—'}</span></div>
235:               </div>
236:               <button className="btn-block mt-24" onClick={lookup} disabled={busy}>{busy ? <span className="spin" /> : <i className="fa-solid fa-magnifying-glass" />} فحص البنود</button>
237:               <button className="btn-pill is-dark mt-8" style={{ width: '100%', justifyContent: 'center' }} disabled={!looked || !valid.length} onClick={() => addToCart(valid.map((x) => ({ v: x.v, qty: x.q })))}><i className="fa-solid fa-cart-plus" /> إضافة <span className="num">{valid.length}</span> بند صالح للسلة</button>
238:               <p className="note mt-16"><i className="fa-solid fa-circle-info" />الفحص للمعاينة فقط؛ الأسعار النهائية بتتأكد في السلة.</p>
239:             </div>
240:           </aside>
241:         </div>
242:       ) : <ImportTab />}
243:     </>
244:   );
245: };
