247: const ImportTab = () => {
248:   const { go } = useApp();
249:   const [stage, setStage] = useState('idle'); // idle | invalid | uploading | done
250:   const [file, setFile] = useState(null);
251:   const pick = (bad) => { if (bad) { setFile({ name: 'big-order-oct.xlsx', size: '7.4 MB' }); setStage('invalid'); return; } setFile({ name: 'order-nov-week1.xlsx', size: '38 KB' }); setStage('ready'); };
252:   const upload = () => { setStage('uploading'); setTimeout(() => setStage('done'), 1300); };
253:   const skipped = [['SPH-XX-999', 10, 'الصنف غير موجود'], ['SPH-TT-001-CRM', 12, 'نفدت الكمية'], ['SPH-BP-007-GRY-M', 30, 'الكمية أكبر من المتاح (18)'], ['—', 0, 'صف 14: الكمية غير صالحة']];
254:   return (
255:     <div className="grid-2" style={{ gridTemplateColumns: '1fr 340px' }}>
256:       <section className="panel"><div className="panel-body">
257:         {stage !== 'done' ? (
