267:                 <div className="grow"><b className="num">{file.name}</b> <span className="soft num">· {file.size}</span></div>
268:                 <button className="btn-link muted" onClick={() => { setFile(null); setStage('idle'); }}><i className="fa-solid fa-xmark" /></button>
269:               </div>
270:             )}
271:             {stage === 'invalid' && <p className="f-error"><i className="fa-solid fa-circle-exclamation" />حجم الملف أكبر من 5 ميجابايت. قسّم الملف وحاول تاني.</p>}
272:             <Banner kind="warn" ><b>الاستيراد بيضيف البنود للسلة مباشرة</b> — مش معاينة. البنود اللي فيها مشاكل هتتخطى وهيظهرلك سببها.</Banner>
273:             <div className="row mt-16" style={{ justifyContent: 'space-between' }}>
274:               <button className="btn-link muted" onClick={() => pick(true)}>جرب ملف كبير (حالة خطأ)</button>
275:               <button className="btn-pill is-dark" disabled={stage !== 'ready'} onClick={upload}>{stage === 'uploading' ? <><span className="spin" /> جارٍ الاستيراد…</> : <><i className="fa-solid fa-upload" /> استيراد وإضافة للسلة</>}</button>
276:             </div>
277:           </>
278:         ) : (
279:           <>
280:             <div className="row" style={{ gap: 16 }}>
281:               <div className="modal-icon"><i className="fa-solid fa-check" /></div>
282:               <div><h2 className="panel-title">تم الاستيراد</h2><p className="muted small" style={{ margin: '4px 0 0' }}><span className="num">{file.name}</span></p></div>
283:             </div>
284:             <div className="imp-stats mt-24">
285:               <div><span className="num">38</span><small>بند تمت إضافته</small></div>
286:               <div className="is-warn"><span className="num">4</span><small>بند تم تخطيه</small></div>
287:             </div>
288:             <h3 className="f-label mt-24">البنود المتخطاة وأسبابها</h3>
289:             <table className="tbl"><thead><tr><th>SKU</th><th>الكمية</th><th>السبب</th></tr></thead>
290:               <tbody>{skipped.map(([s, q, r], i) => <tr key={i}><td className="sku">{s}</td><td className="num">{q || '—'}</td><td style={{ color: '#b91c1c' }}>{r}</td></tr>)}</tbody></table>
291:             <div className="row mt-24"><button className="btn-pill is-dark" onClick={() => go('cart')}><i className="fa-solid fa-bag-shopping" /> فتح السلة</button><button className="btn-pill" onClick={() => { setStage('idle'); setFile(null); }}>استيراد ملف آخر</button></div>
292:           </>
293:         )}
294:       </div></section>
295:       <aside className="panel"><div className="panel-body">
296:         <h2 className="panel-title">ترتيب الأعمدة</h2>
297:         <p className="muted small" style={{ lineHeight: 1.8 }}>العمود الأول SKU أو الباركود، والثاني الكمية. صف العناوين اختياري.</p>
298:         <table className="tbl imp-sample ltr"><thead><tr><th>A · sku</th><th>B · qty</th></tr></thead>
299:           <tbody><tr><td className="sku">SPH-TT-001-BLK</td><td className="num">24</td></tr><tr><td className="sku">6224001014011</td><td className="num">40</td></tr><tr><td className="sku">SPH-WL-040-BRG</td><td className="num">120</td></tr></tbody></table>
300:       </div></aside>
301:     </div>
302:   );
