305: /* ---------- 10. Cart ---------- */
306: export const Cart = () => {
307:   const { cart, setCart, go } = useApp();
308:   const [coupon, setCoupon] = useState('');
309:   const [applied, setApplied] = useState(null);
310:   const [cErr, setCErr] = useState('');
311:   const [confirmClear, setConfirmClear] = useState(false);
312:   const lines = cart.map((l) => ({ ...l, unit: tierPrice(l.v, l.qty), total: tierPrice(l.v, l.qty) * l.qty }));
313:   const sub = lines.reduce((a, l) => a + l.total, 0);
314:   const disc = applied ? Math.round(sub * 0.03) : 0;
315:   const upd = (i, q) => setCart(cart.map((l, j) => j === i ? { ...l, qty: q } : l).filter((l) => l.qty > 0));
316:   const apply = () => { if (coupon.trim().toUpperCase() === 'WS3') { setApplied('WS3'); setCErr(''); } else setCErr('الكوبون غير صالح أو غير مقبول لطلبات الجملة.'); };
317:   const changed = lines.find((l) => l.v.sku === 'SPH-BP-007-NVY-L');
318:   const short = lines.find((l) => l.qty > l.v.qty);
319:   if (!cart.length) return (<><PageHead en="Your Bag" ar="سلة المشتريات" /><section className="panel"><Empty icon="fa-bag-shopping" title="السلة فاضية" desc="ضيف منتجات من الكتالوج أو استخدم الطلب السريع." action={<div className="row"><button className="btn-pill is-dark" onClick={() => go('catalog')}>تصفح الكتالوج</button><button className="btn-pill" onClick={() => go('quick')}>طلب سريع</button></div>} /></section></>);
320:   return (
321:     <>
322:       <PageHead en="Your Bag" ar={<>سلة المشتريات · <span className="num">{lines.length}</span> بند</>}>
323:         <button className="btn-pill is-danger" onClick={() => setConfirmClear(true)}><i className="fa-regular fa-trash-can" /> تفريغ السلة</button>
324:       </PageHead>
325:       <div className="stack" style={{ gap: 12, marginBottom: 24 }}>
326:         {changed && <Banner kind="info" icon="fa-tag">تغير سعر <b>{changed.v.product.name_ar}</b> من <span className="num strike">{fmt(910)}</span> إلى <b className="num">{fmt(changed.unit)}</b> منذ إضافته للسلة.</Banner>}
327:         {short && <Banner kind="error">الكمية المطلوبة من <b>{short.v.product.name_ar} — {short.v.label}</b> أكبر من المخزون المتاح (<span className="num">{short.v.qty}</span>). عدّل الكمية للمتابعة.</Banner>}
328:       </div>
329:       <div className="grid-2" style={{ gridTemplateColumns: '1.35fr 1fr', gap: 48 }}>
330:         <section>
331:           {lines.map((l, i) => (
