119: /* ---------- 20. New payment notice ---------- */
120: export const NoticeForm = () => {
121:   const { go } = useApp();
122:   const [f, setF] = useState({ order: '', amount: '', method: 'bank_transfer', bank: '', ref: '', date: '' });
123:   const [file, setFile] = useState(null);
124:   const [errs, setErrs] = useState({});
125:   const [stage, setStage] = useState('form'); // form | confirm | sending | done
126:   const out = ORDERS.filter((o) => o.pay === 'unpaid' && o.status !== 'cancelled');
127:   const set = (k, v) => { setF({ ...f, [k]: v }); setErrs({ ...errs, [k]: null }); };
128:   const validate = () => {
129:     const e = {};
130:     if (!f.amount || Number(f.amount) <= 0) e.amount = 'أدخل مبلغ صحيح أكبر من صفر.';
131:     if (!f.bank.trim()) e.bank = 'اسم البنك مطلوب.';
132:     if (!f.ref.trim()) e.ref = 'رقم المرجع مطلوب.';
133:     if (!f.date) e.date = 'تاريخ التحويل مطلوب.'; else if (f.date > '2026-10-29') e.date = 'تاريخ التحويل لا يمكن أن يكون في المستقبل.';
134:     if (!file) e.file = 'إيصال التحويل مطلوب.'; else if (file.bad) e.file = 'حجم الملف أكبر من 10 ميجابايت.';
135:     setErrs(e); return !Object.keys(e).length;
136:   };
137:   if (stage === 'done') return (
138:     <div className="success-wrap"><div className="order-card">
139:       <div className="modal-icon" style={{ width: 64, height: 64, fontSize: 26 }}><i className="fa-solid fa-paper-plane" /></div>
140:       <h1 className="success-title">NOTICE SENT</h1>
141:       <p className="muted">تم إرسال إشعار السداد للمراجعة</p>
142:       <p className="success-num num">PN-0432</p>
143:       <Banner kind="warn" icon="fa-hourglass-half">رفع الإيصال <b>لا يعني اعتماد السداد</b>. الإدارة هتراجع التحويل وتعتمده، وهيوصلك إشعار.</Banner>
144:       <div className="row mt-24" style={{ justifyContent: 'center' }}><button className="btn-pill is-dark" onClick={() => go('notice', 431)}>عرض الإشعار</button><button className="btn-pill" onClick={() => go('notices')}>كل الإشعارات</button></div>
145:     </div></div>
146:   );
147:   return (
148:     <>
149:       <PageHead en="Payment Notice" crumb={<Crumb items={[{ label: 'إشعارات السداد', go: () => go('notices') }, { label: 'إشعار جديد' }]} />} ar="سجّل تحويل أو شيك أو إيداع تم لحساب الشركة" />
150:       <div className="grid-2" style={{ gridTemplateColumns: '1fr 340px' }}>
151:         <section className="panel"><div className="panel-body">
152:           <div className="fields">
153:             <Field label="طلب مرتبط" opt span>
154:               <select className="line-input" value={f.order} onChange={(e) => { const o = out.find((x) => x.number === e.target.value); setF({ ...f, order: e.target.value, amount: o ? String(o.total) : f.amount }); }}>
155:                 <option value="">بدون — سداد على الحساب</option>{out.map((o) => <option key={o.id} value={o.number}>{o.number} · {fmt(o.total)} EGP</option>)}
156:               </select></Field>
157:             <Field label="المبلغ" req error={errs.amount}><div style={{ position: 'relative' }}><input className={`line-input ltr${errs.amount ? ' is-invalid' : ''}`} style={{ textAlign: 'right', paddingLeft: 40 }} inputMode="decimal" placeholder="0.00" value={f.amount} onChange={(e) => set('amount', e.target.value.replace(/[^\d.]/g, ''))} /><span className="soft small" style={{ position: 'absolute', left: 0, top: 12 }}>EGP</span></div></Field>
158:             <Field label="تاريخ التحويل" req error={errs.date}><input type="date" max="2026-10-29" className={`line-input ltr${errs.date ? ' is-invalid' : ''}`} value={f.date} onChange={(e) => set('date', e.target.value)} /></Field>
159:             <Field label="طريقة السداد" req span>
160:               <div className="chips">{Object.entries(NOTICE_METHOD).map(([k, l]) => <button key={k} type="button" className={`chip${f.method === k ? ' is-on' : ''}`} onClick={() => set('method', k)}><i className={`fa-solid ${{ bank_transfer: 'fa-building-columns', cheque: 'fa-money-check', deposit: 'fa-piggy-bank' }[k]}`} />{l}</button>)}</div></Field>
161:             <Field label="اسم البنك" req error={errs.bank}><input className={`line-input${errs.bank ? ' is-invalid' : ''}`} placeholder="مثال: البنك الأهلي المصري" value={f.bank} onChange={(e) => set('bank', e.target.value)} /></Field>
162:             <Field label={f.method === 'cheque' ? 'رقم الشيك' : 'رقم المرجع'} req error={errs.ref}><input className={`line-input ltr${errs.ref ? ' is-invalid' : ''}`} style={{ textAlign: 'right' }} value={f.ref} onChange={(e) => set('ref', e.target.value)} /></Field>
163:             <Field label="الإيصال" req span error={errs.file}>
164:               {file ? (
165:                 <div className="file-row" style={file.bad ? { borderColor: '#fecaca', background: '#fffafa' } : null}><i className="fa-regular fa-file-pdf" /><div className="grow"><b className="num">{file.name}</b> <span className="soft num">· {file.size}</span></div><button className="btn-link muted" onClick={() => setFile(null)}><i className="fa-solid fa-xmark" /></button></div>
166:               ) : (
167:                 <div className={`drop${errs.file ? ' is-invalid' : ''}`} style={{ minHeight: 120 }} onClick={() => { setFile({ name: 'nbe-transfer-receipt.pdf', size: '412 KB' }); setErrs({ ...errs, file: null }); }}>
168:                   <i className="fa-solid fa-receipt" /><b>ارفع صورة أو PDF للإيصال</b><small>PDF · JPG · JPEG · PNG · WebP — حتى <span className="num">10</span> ميجابايت</small></div>
169:               )}
170:               {!file && <button className="btn-link muted mt-8" style={{ fontSize: 12 }} onClick={() => setFile({ name: 'scan-hq.png', size: '14.2 MB', bad: true })}>جرب ملف كبير (حالة خطأ)</button>}
171:             </Field>
172:           </div>
173:         </div></section>
174:         <aside className="stack" style={{ position: 'sticky', top: 100 }}>
175:           <Panel title="مراجعة">
176:             <div className="sum-row"><span>الطلب</span><strong className="num">{f.order || 'على الحساب'}</strong></div>
177:             <div className="sum-row"><span>الطريقة</span><strong>{NOTICE_METHOD[f.method]}</strong></div>
178:             <div className="sum-total"><span>المبلغ</span><span className="num">{f.amount ? fmt(f.amount) : '—'}</span></div>
179:             <button className="btn-block mt-24" onClick={() => validate() && setStage('confirm')}>إرسال للمراجعة</button>
180:           </Panel>
181:           <p className="note"><i className="fa-solid fa-circle-info" />السداد مش بيتعتمد تلقائيًا؛ الإدارة بتراجع الإيصال مع كشف البنك.</p>
182:         </aside>
183:       </div>
184:       {(stage === 'confirm' || stage === 'sending') && <Modal title="تأكيد إرسال إشعار السداد" onClose={() => setStage('form')} icon={<div className="modal-icon"><i className="fa-solid fa-money-check-dollar" /></div>}
185:         foot={<><button className="btn-pill" onClick={() => setStage('form')}>تعديل</button><button className="btn-pill is-dark" disabled={stage === 'sending'} onClick={() => { setStage('sending'); setTimeout(() => setStage('done'), 900); }}>{stage === 'sending' ? <span className="spin" /> : null} تأكيد الإرسال</button></>}>
186:         <dl className="kv"><dt>المبلغ</dt><dd><Money v={f.amount} strong /></dd><dt>الطريقة</dt><dd>{NOTICE_METHOD[f.method]}</dd><dt>البنك</dt><dd>{f.bank}</dd><dt>المرجع</dt><dd className="sku">{f.ref}</dd><dt>التاريخ</dt><dd className="num">{f.date}</dd><dt>الإيصال</dt><dd className="num">{file?.name}</dd></dl>
187:       </Modal>}
188:     </>
189:   );
190: };
