285:                 <div className="row mt-8" style={{ gap: 16 }}>
286:                   {n.link && <button className="btn-link" onClick={() => { read(n.id); go(n.link[0], n.link[1]); }}>فتح</button>}
287:                   {n.unread && <button className="btn-link muted" onClick={() => read(n.id)}>تحديد كمقروء</button>}
