 40: /* ---------- 13. Orders ---------- */
 41: export const Orders = () => {
 42:   const { go, toast } = useApp();
 43:   const [f, setF] = useState('all');
 44:   const [re, setRe] = useState(null);
 45:   const [cancel, setCancel] = useState(null);
 46:   const [cancelled, setCancelled] = useState([]);
 47:   const groups = { all: () => true, active: (o) => ['pending', 'confirmed', 'processing', 'shipped'].includes(o.status), delivered: (o) => o.status === 'delivered', cancelled: (o) => o.status === 'cancelled' };
 48:   const list = ORDERS.map((o) => cancelled.includes(o.id) ? { ...o, status: 'cancelled', cancellable: false } : o).filter(groups[f]);
 49:   return (
 50:     <>
 51:       <PageHead en="My Orders" ar="كل طلبات حساب الجملة" />
 52:       <section className="panel">
 53:         <div className="toolbar">
 54:           <div className="chips">{[['all', 'الكل'], ['active', 'جاري التنفيذ'], ['delivered', 'تم التسليم'], ['cancelled', 'ملغي']].map(([k, l]) => <button key={k} className={`chip${f === k ? ' is-on' : ''}`} onClick={() => setF(k)}>{l}<span className="num">{ORDERS.filter(groups[k]).length}</span></button>)}</div>
 55:         </div>
 56:         <Async rows={6} cols={6} isEmpty={!list.length} empty={<Empty icon="fa-box-open" title="مفيش طلبات" desc="لما تعمل أول طلب هيظهر هنا." action={<button className="btn-pill is-dark" onClick={() => go('catalog')}>تصفح الكتالوج</button>} />}>
 57:           <div className="tbl-wrap"><table className="tbl">
 58:             <thead><tr><th>رقم الطلب</th><th>التاريخ</th><th>حالة التنفيذ</th><th>طريقة الدفع</th><th>السداد</th><th className="t-end">الإجمالي</th><th></th></tr></thead>
 59:             <tbody>{list.map((o) => (
 60:               <tr key={o.id} className="is-click" onClick={() => go('order', o.id)}>
 61:                 <td className="strong num">{o.number}</td>
 62:                 <td className="num">{o.date}</td>
 63:                 <td><Badge map={ORDER_STATUS} k={o.status} /></td>
 64:                 <td>{PAY_METHOD[o.method]}</td>
 65:                 <td><Badge map={PAY_STATUS} k={o.pay} /></td>
 66:                 <td className="t-end strong num">{fmt(o.total)}</td>
 67:                 <td onClick={(e) => e.stopPropagation()}><div className="row-actions">
 68:                   <button className="btn-link" onClick={() => setRe(o)}>إعادة الطلب</button>
 69:                   {o.cancellable && <button className="btn-link danger" onClick={() => setCancel(o)}>إلغاء</button>}
 70:                   <button className="btn-link muted" onClick={() => go('order', o.id)}>التفاصيل</button>
 71:                 </div></td>
 72:               </tr>))}</tbody>
 73:           </table></div>
 74:           <Pager total={list.length} pages={1} per={15} />
 75:         </Async>
 76:       </section>
 77:       {re && <ReorderModal order={re} onClose={() => setRe(null)} />}
 78:       {cancel && <CancelModal order={cancel} onClose={() => setCancel(null)} onDone={() => { setCancelled([...cancelled, cancel.id]); setCancel(null); toast(`تم إلغاء الطلب ${cancel.number}`); }} />}
 79:     </>
 80:   );
 81: };
