 84: export const OrderDetail = ({ id }) => {
 85:   const { go } = useApp();
 86:   const o = ORDERS.find((x) => x.id === id) || ORDERS[0];
 87:   const [re, setRe] = useState(false);
 88:   const [cancel, setCancel] = useState(false);
 89:   return (
 90:     <>
 91:       <PageHead en={o.number} crumb={<Crumb items={[{ label: 'طلباتي', go: () => go('orders') }, { label: o.number, mono: true }]} />} ar={<>تاريخ الطلب <span className="num">{o.date}</span></>}>
 92:         <Badge map={ORDER_STATUS} k={o.status} lg />
 93:         <button className="btn-pill" onClick={() => setRe(true)}><i className="fa-solid fa-rotate" /> إعادة الطلب</button>
 94:         {o.returnable && <button className="btn-pill" onClick={() => go('returnNew', o.id)}><i className="fa-solid fa-rotate-left" /> طلب إرجاع</button>}
 95:         {o.cancellable && <button className="btn-pill is-danger" onClick={() => setCancel(true)}>إلغاء الطلب</button>}
 96:       </PageHead>
 97:       <Async rows={5} cols={4}>
 98:         <div className="grid-2">
 99:           <div className="stack">
100:             <Panel title="البنود" en="ITEMS" body={false}>
101:               <div className="tbl-wrap"><table className="tbl">
102:                 <thead><tr><th>المنتج</th><th>الكمية</th><th>سعر الوحدة</th><th>الخصم</th><th className="t-end">الإجمالي</th></tr></thead>
103:                 <tbody>{o.items.map((it) => (
104:                   <tr key={it.sku}><td><div className="prod-cell"><Thumb sm /><div><div className="prod-name">{it.name}</div><div className="sku">{it.sku}</div></div></div></td>
105:                     <td className="num">{it.qty}</td><td className="num">{fmt(it.unit)}</td><td className="num" style={{ color: it.discount ? 'var(--teal)' : null }}>{it.discount ? '− ' + fmt(it.discount) : '—'}</td>
106:                     <td className="t-end strong num">{fmt(it.unit * it.qty - it.discount)}</td></tr>))}</tbody>
107:               </table></div>
108:             </Panel>
109:             <div className="grid-2e" style={{ gap: 24 }}>
110:               <Panel title="المستلم والعنوان" en="DELIVERY">
111:                 <dl className="kv"><dt>المستلم</dt><dd>{o.recipient}</dd><dt>التليفون</dt><dd className="num">{o.phone}</dd><dt>المدينة</dt><dd>{o.city}</dd><dt>العنوان</dt><dd>{o.address}</dd></dl>
112:               </Panel>
113:               <Panel title="الدفع" en="PAYMENT">
114:                 <dl className="kv"><dt>الطريقة</dt><dd>{PAY_METHOD[o.method]}</dd><dt>حالة السداد</dt><dd><Badge map={PAY_STATUS} k={o.pay} /></dd></dl>
115:                 {o.pay === 'unpaid' && o.method === 'credit' && <button className="btn-link mt-16" onClick={() => go('noticeNew')}>تسجيل إشعار سداد لهذا الطلب</button>}
116:               </Panel>
117:             </div>
118:           </div>
119:           <div className="stack">
120:             <Panel title="تفصيل المبالغ" en="TOTALS">
121:               <div className="sum-row"><span>المنتجات</span><strong className="num">{fmt(o.subtotal)}</strong></div>
122:               <div className="sum-row is-neg"><span>الخصم</span><strong className="num">{o.discount ? '− ' + fmt(o.discount) : '—'}</strong></div>
123:               <div className="sum-row"><span>الشحن</span><strong className="num">{fmt(o.shipping)}</strong></div>
124:               <div className="sum-row"><span>رسوم التحصيل</span><strong className="num">{fmt(o.cod_fee)}</strong></div>
125:               <div className="sum-row"><span>الضريبة</span><strong className="num">{fmt(o.tax)}</strong></div>
126:               <div className="sum-total"><span>الإجمالي</span><span className="num">{fmt(o.total)}</span></div>
127:             </Panel>
128:             <Panel title="سجل الحالة" en="TRACKING">
129:               <ul className="tl">{o.track.map(([s, t, st], i) => (
130:                 <li key={i} className={st === 'now' ? 'is-now' : st ? 'is-done' : 'is-future'}>
131:                   <div className="tl-title">{ORDER_STATUS[s][0]}</div>{t && <div className="tl-meta num">{t}</div>}</li>))}</ul>
132:               <p className="note"><i className="fa-solid fa-circle-info" />التتبع من خدمة الشحن برقم الطلب ورقم الهاتف.</p>
133:             </Panel>
134:           </div>
135:         </div>
136:       </Async>
137:       {re && <ReorderModal order={o} onClose={() => setRe(false)} />}
138:       {cancel && <CancelModal order={o} onClose={() => setCancel(false)} onDone={() => { setCancel(false); go('orders'); }} />}
139:     </>
140:   );
141: };
