176: /* ---------- 16. Create / edit quote ---------- */
177: export const QuoteForm = ({ id }) => {
178:   const { go, toast } = useApp();
179:   const editing = QUOTES.find((q) => q.id === id);
180:   const init = editing ? editing.items.map((it) => ({ v: ALL_VARIANTS.find((v) => v.sku === it.sku), qty: it.qty, target: String(it.target || '') }))
181:     : [{ v: ALL_VARIANTS[0], qty: 80, target: '950' }, { v: ALL_VARIANTS[5], qty: 50, target: '' }];
182:   const [items, setItems] = useState(init);
183:   const [note, setNote] = useState(editing?.trader_note || '');
184:   const [search, setSearch] = useState('');
185:   const [errs, setErrs] = useState({});
186:   const [confirm, setConfirm] = useState(null);
187:   const matches = search ? ALL_VARIANTS.filter((v) => (v.product.name_ar + v.sku + v.label).toLowerCase().includes(search.toLowerCase())).slice(0, 5) : [];
188:   const upd = (i, k, val) => setItems(items.map((it, j) => j === i ? { ...it, [k]: val } : it));
189:   const validate = () => { const e = {}; items.forEach((it, i) => { if (!it.qty) e[i] = 'الكمية مطلوبة'; }); if (!items.length) e.items = 'أضف بند واحد على الأقل.'; setErrs(e); return !Object.keys(e).length; };
190:   return (
191:     <>
192:       <PageHead en={editing ? editing.number : 'New Quote'} crumb={<Crumb items={[{ label: 'عروض الأسعار', go: () => go('quotes') }, { label: editing ? 'تعديل مسودة' : 'طلب جديد' }]} />} ar={editing ? 'مسودة — يمكنك التعديل قبل الإرسال' : 'اختر المنتجات والكميات، واقترح السعر المستهدف لو حابب'}>
193:         {editing && <button className="btn-pill is-danger" onClick={() => setConfirm('delete')}><i className="fa-regular fa-trash-can" /> حذف المسودة</button>}
194:       </PageHead>
195:       <div className="grid-2" style={{ gridTemplateColumns: '1fr 340px' }}>
196:         <section className="panel">
197:           <div className="toolbar" style={{ position: 'relative' }}>
198:             <div className="search" style={{ flex: 1 }}><i className="fa-solid fa-plus" /><input className="line-input" placeholder="أضف منتج — ابحث بالاسم أو SKU" value={search} onChange={(e) => setSearch(e.target.value)} /></div>
199:             <span className="soft small"><span className="num">{items.length}</span> / <span className="num">100</span> بند</span>
200:             {matches.length > 0 && (
201:               <div className="qf-suggest">{matches.map((v) => (
202:                 <button key={v.id} onClick={() => { setItems([...items, { v, qty: v.tiers[0][0], target: '' }]); setSearch(''); }}>
203:                   <Thumb sm /><span style={{ flex: 1 }}><b>{v.product.name_ar} — {v.label}</b><span className="sku">{v.sku}</span></span><span className="num small">{fmt(v.price)}</span></button>))}</div>
204:             )}
205:           </div>
206:           {items.length === 0 ? <Empty icon="fa-list" title="مفيش بنود" desc="ابحث وأضف المنتجات اللي عايز تسعيرها." /> : (
207:             <div className="tbl-wrap"><table className="tbl">
208:               <thead><tr><th>المتغير</th><th>سعرك الحالي</th><th>الكمية</th><th>السعر المستهدف <span className="f-opt">(اختياري)</span></th><th></th></tr></thead>
209:               <tbody>{items.map((it, i) => (
210:                 <tr key={i} className={errs[i] ? 'is-error' : ''}>
211:                   <td><div className="prod-cell"><Thumb sm /><div><div className="prod-name">{it.v.product.name_ar}</div><div className="soft small">{it.v.label} · <span className="sku">{it.v.sku}</span></div></div></div></td>
212:                   <td className="num">{fmt(it.v.price)}</td>
213:                   <td><Qty value={it.qty} onChange={(n) => upd(i, 'qty', n)} />{errs[i] && <p className="f-error">{errs[i]}</p>}</td>
214:                   <td><input className="box-input ltr" style={{ width: 120 }} placeholder="0.00" value={it.target} onChange={(e) => upd(i, 'target', e.target.value.replace(/[^\d.]/g, ''))} /></td>
215:                   <td><button className="btn-link muted" onClick={() => setItems(items.filter((_, j) => j !== i))} aria-label="حذف"><i className="fa-solid fa-xmark" /></button></td>
216:                 </tr>))}</tbody>
217:             </table></div>
218:           )}
219:           {errs.items && <p className="f-error" style={{ padding: '0 24px 16px' }}>{errs.items}</p>}
220:         </section>
221:         <aside className="stack" style={{ position: 'sticky', top: 100 }}>
222:           <Panel title="ملاحظات للإدارة">
223:             <Field label="ملاحظات التاجر" opt counter={<span className="f-counter" style={{ color: note.length > 2000 ? '#b91c1c' : null }}>{note.length}/2000</span>} error={note.length > 2000 ? 'الحد الأقصى 2000 حرف.' : null}>
224:               <textarea className="line-input" rows="5" value={note} placeholder="مواعيد التسليم، تغليف خاص، شروط الدفع…" onChange={(e) => setNote(e.target.value)} />
225:             </Field>
226:             <div className="divider" />
227:             <div className="sum-row"><span>عدد البنود</span><strong className="num">{items.length}</strong></div>
228:             <div className="sum-row"><span>إجمالي الكميات</span><strong className="num">{items.reduce((a, it) => a + it.qty, 0)}</strong></div>
229:             <button className="btn-block mt-24" onClick={() => validate() && setConfirm('submit')}><i className="fa-solid fa-paper-plane" /> إرسال للإدارة للتسعير</button>
230:             <button className="btn-pill mt-8" style={{ width: '100%', justifyContent: 'center' }} onClick={() => { toast('تم حفظ المسودة'); go('quotes'); }}><i className="fa-regular fa-floppy-disk" /> حفظ كمسودة</button>
231:           </Panel>
232:           <p className="note"><i className="fa-solid fa-circle-info" />بعد الإرسال مش هتقدر تعدّل الطلب. الإدارة هترد بالأسعار وتاريخ صلاحية العرض.</p>
233:         </aside>
234:       </div>
235:       {confirm === 'submit' && <Modal title="إرسال طلب التسعير؟" onClose={() => setConfirm(null)} icon={<div className="modal-icon"><i className="fa-solid fa-paper-plane" /></div>}
236:         foot={<><button className="btn-pill" onClick={() => setConfirm(null)}>رجوع</button><button className="btn-pill is-dark" onClick={() => { toast('تم إرسال الطلب للإدارة'); go('quote', 30); }}>إرسال</button></>}>
237:         <p className="muted">هيتم إرسال <span className="num">{items.length}</span> بند للإدارة. الحالة هتتغير إلى «مطلوب تسعيره».</p></Modal>}
238:       {confirm === 'delete' && <Modal title="حذف المسودة؟" onClose={() => setConfirm(null)} icon={<div className="modal-icon is-err"><i className="fa-solid fa-trash-can" /></div>}
239:         foot={<><button className="btn-pill" onClick={() => setConfirm(null)}>رجوع</button><button className="btn-pill is-danger" onClick={() => { toast('تم حذف المسودة'); go('quotes'); }}>حذف</button></>}>
240:         <p className="muted">الإجراء ده نهائي.</p></Modal>}
241:     </>
242:   );
243: };
