245: /* ---------- 17. Quote detail ---------- */
246: export const QuoteDetail = ({ id }) => {
247:   const { go, toast } = useApp();
248:   const q0 = QUOTES.find((x) => x.id === id) || QUOTES[0];
249:   const [status, setStatus] = useState(q0.status);
250:   const [confirm, setConfirm] = useState(null);
251:   const q = { ...q0, status };
252:   return (
253:     <>
254:       <PageHead en={q.number} crumb={<Crumb items={[{ label: 'عروض الأسعار', go: () => go('quotes') }, { label: q.number, mono: true }]} />} ar={<>أُنشئ في <span className="num">{q.created}</span>{q.valid_until && <> · صالح حتى <span className="num">{q.valid_until}</span></>}</>}>
255:         <Badge map={QUOTE_STATUS} k={q.status} lg />
256:       </PageHead>
257:       {q.status === 'priced' && <div className="mb-24"><Banner kind="info" icon="fa-clock" action={<div className="row"><button className="btn-pill is-danger sm" onClick={() => setConfirm('reject')}>رفض</button><button className="btn-pill is-dark sm" onClick={() => setConfirm('accept')}>قبول العرض</button></div>}><b>الإدارة سعّرت العرض.</b> راجع الأسعار وقرر قبل <span className="num">{q.valid_until}</span> — بعدها العرض بينتهي تلقائيًا.</Banner></div>}
258:       {q.status === 'requested' && <div className="mb-24"><Banner kind="warn" icon="fa-hourglass-half">الطلب عند الإدارة للتسعير. هيوصلك إشعار لما يتم الرد.</Banner></div>}
259:       {q.status === 'expired' && <div className="mb-24"><Banner kind="error" icon="fa-calendar-xmark">انتهت صلاحية العرض ولم يعد قابلًا للقبول. تقدر تطلب عرض جديد.</Banner></div>}
260:       {q.status === 'converted' && <div className="mb-24"><Banner kind="ok" action={<button className="btn-pill sm" onClick={() => go('order', 7)}>فتح الطلب <span className="num">{q.converted_order_id}</span></button>}>تم تحويل العرض لطلب.</Banner></div>}
261:       {q.status === 'accepted' && <div className="mb-24"><Banner kind="ok">تم قبول العرض. الإدارة هتحوله لطلب وهيظهر في طلباتك.</Banner></div>}
262:       <div className="grid-2">
263:         <Panel title="البنود" en="LINE ITEMS" body={false}>
264:           <div className="tbl-wrap"><table className="tbl">
265:             <thead><tr><th>المنتج</th><th>الكمية</th><th>السعر المطلوب</th><th>السعر المعروض</th><th className="t-end">إجمالي البند</th></tr></thead>
266:             <tbody>{q.items.map((it) => (
267:               <tr key={it.sku}><td><div className="prod-cell"><Thumb sm /><div><div className="prod-name">{it.name}</div><div className="sku">{it.sku}</div></div></div></td>
268:                 <td className="num">{it.qty}</td><td className="num muted">{it.target ? fmt(it.target) : '—'}</td>
269:                 <td className="num strong">{it.offered ? fmt(it.offered) : <span className="soft">في الانتظار</span>}</td>
270:                 <td className="t-end strong num">{it.offered ? fmt(it.offered * it.qty) : '—'}</td></tr>))}</tbody>
271:           </table></div>
272:         </Panel>
273:         <div className="stack">
274:           <Panel title="الإجماليات" en="TOTALS">
275:             <div className="sum-row"><span>الإجمالي قبل الخصم</span><strong className="num">{q.total != null ? fmt(q.subtotal) : '—'}</strong></div>
276:             <div className="sum-row is-neg"><span>الخصم</span><strong className="num">{q.discount ? '− ' + fmt(q.discount) : '—'}</strong></div>
277:             <div className="sum-row"><span>الضريبة</span><strong className="num">{q.total != null ? fmt(q.tax) : '—'}</strong></div>
278:             <div className="sum-total"><span>الإجمالي النهائي</span><span className="num">{q.total != null ? fmt(q.total) : '—'}</span></div>
279:           </Panel>
280:           <Panel title="الملاحظات" en="NOTES">
281:             <div className="note-bubble"><span>ملاحظات التاجر</span><p>{q.trader_note || <span className="soft">—</span>}</p></div>
282:             <div className="note-bubble is-admin"><span>رد الإدارة</span><p>{q.admin_note || <span className="soft">لم يتم الرد بعد</span>}</p></div>
283:           </Panel>
284:         </div>
285:       </div>
286:       {confirm && <Modal title={confirm === 'accept' ? 'قبول عرض السعر؟' : 'رفض عرض السعر؟'} onClose={() => setConfirm(null)} icon={<div className={`modal-icon${confirm === 'reject' ? ' is-err' : ''}`}><i className={`fa-solid ${confirm === 'accept' ? 'fa-check' : 'fa-xmark'}`} /></div>}
287:         foot={<><button className="btn-pill" onClick={() => setConfirm(null)}>رجوع</button><button className={`btn-pill ${confirm === 'accept' ? 'is-dark' : 'is-danger'}`} onClick={() => { setStatus(confirm === 'accept' ? 'accepted' : 'rejected'); toast(confirm === 'accept' ? 'تم قبول العرض' : 'تم رفض العرض'); setConfirm(null); }}>{confirm === 'accept' ? 'قبول' : 'رفض'}</button></>}>
288:         <p className="muted" style={{ lineHeight: 1.9 }}>{confirm === 'accept' ? <>بقبولك العرض بإجمالي <b className="num" style={{ color: 'var(--ink)' }}>{fmt(q.total)} EGP</b> الإدارة هتحوله لطلب.</> : 'الإجراء نهائي، ولن يكون العرض قابلًا للقبول بعد الرفض.'}</p></Modal>}
289:     </>
290:   );
291: };
