293: /* ---------- 22. Returns ---------- */
294: export const Returns = () => {
295:   const { go } = useApp();
296:   return (
297:     <>
298:       <PageHead en="Returns" ar="طلبات الإرجاع والاسترداد"><button className="btn-pill is-dark" onClick={() => go('returnNew')}><i className="fa-solid fa-plus" /> طلب إرجاع</button></PageHead>
299:       <section className="panel">
300:         <Async rows={4} cols={5} empty={<Empty icon="fa-rotate-left" title="مفيش مرتجعات" desc="تقدر تطلب إرجاع لأي طلب مؤهل بعد التسليم." />}>
301:           <div className="tbl-wrap"><table className="tbl">
302:             <thead><tr><th>رقم المرتجع</th><th>الطلب</th><th>الحالة</th><th>مبلغ الاسترداد</th><th>التاريخ</th><th></th></tr></thead>
303:             <tbody>{RETURNS.map((r) => (
304:               <tr key={r.id} className="is-click" onClick={() => go('return', r.id)}>
305:                 <td className="strong num">{r.number}</td><td className="num">{r.order}</td><td><Badge map={RETURN_STATUS} k={r.status} /></td>
306:                 <td className="strong num">{fmt(r.refund)}</td><td className="num">{r.date}</td><td className="t-end"><button className="btn-link muted">التفاصيل</button></td></tr>))}</tbody>
307:           </table></div>
308:         </Async>
309:       </section>
310:     </>
311:   );
312: };
