314: export const ReturnForm = ({ orderId }) => {
315:   const { go, toast } = useApp();
316:   const eligible = ORDERS.filter((o) => o.returnable);
317:   const [oid, setOid] = useState(orderId || eligible[0].id);
318:   const o = ORDERS.find((x) => x.id === oid);
319:   const [sel, setSel] = useState({});
320:   const [reason, setReason] = useState('');
321:   const [method, setMethod] = useState('wallet');
322:   const [errs, setErrs] = useState({});
323:   const toggle = (sku) => setSel({ ...sel, [sku]: sel[sku] ? undefined : { qty: 1, reason: '', photos: 0 } });
324:   const set = (sku, k, v) => setSel({ ...sel, [sku]: { ...sel[sku], [k]: v } });
325:   const chosen = Object.entries(sel).filter(([, v]) => v);
326:   const totalPhotos = chosen.reduce((a, [, v]) => a + v.photos, 0);
327:   const submit = () => {
328:     const e = {};
329:     if (!chosen.length) e.items = 'اختر بند واحد على الأقل.';
330:     if (!reason.trim()) e.reason = 'السبب العام مطلوب.';
331:     chosen.forEach(([s, v]) => { if (!v.reason.trim()) e[s] = 'سبب البند مطلوب.'; });
332:     setErrs(e); if (!Object.keys(e).length) { toast('تم تقديم طلب الإرجاع'); go('return', 95); }
333:   };
334:   return (
335:     <>
336:       <PageHead en="New Return" crumb={<Crumb items={[{ label: 'المرتجعات', go: () => go('returns') }, { label: 'طلب جديد' }]} />} ar="اختر الطلب والبنود، ووضح السبب" />
337:       <div className="grid-2" style={{ gridTemplateColumns: '1fr 340px' }}>
338:         <div className="stack">
339:           <Panel title="الطلب المؤهل" en="ORDER">
340:             <div className="addr-picks">{eligible.map((x) => (
341:               <button key={x.id} className={`addr-pick${oid === x.id ? ' is-on' : ''}`} onClick={() => { setOid(x.id); setSel({}); }}><b className="num">{x.number}</b><span>تم التسليم · <span className="num">{x.date}</span> · <span className="num">{fmt(x.total)}</span> EGP</span></button>))}</div>
342:             <p className="note mt-16"><i className="fa-solid fa-circle-info" />الطلبات المؤهلة بس هي اللي بتظهر هنا (تم تسليمها وضمن مدة الإرجاع).</p>
343:           </Panel>
344:           <Panel title="البنود المرتجعة" en="ITEMS">
345:             {errs.items && <p className="f-error" style={{ marginTop: 0 }}>{errs.items}</p>}
346:             {o.items.map((it) => {
347:               const s = sel[it.sku];
348:               return (
349:                 <div key={it.sku} className={`ret-item${s ? ' is-on' : ''}`}>
350:                   <label className="row" style={{ cursor: 'pointer' }}>
351:                     <input type="checkbox" checked={!!s} onChange={() => toggle(it.sku)} style={{ accentColor: '#111', width: 16, height: 16 }} />
352:                     <Thumb sm /><div style={{ flex: 1 }}><div className="prod-name">{it.name}</div><div className="soft small"><span className="sku">{it.sku}</span> · تم شراء <span className="num">{it.qty}</span> · <span className="num">{fmt(it.unit)}</span></div></div>
353:                   </label>
354:                   {s && (
355:                     <div className="fields mt-16" style={{ paddingInlineStart: 42 }}>
356:                       <Field label="الكمية المرتجعة" req hint={`حتى ${it.qty}`}><Qty value={s.qty} min={1} onChange={(n) => set(it.sku, 'qty', Math.min(n, it.qty))} /></Field>
357:                       <Field label="سبب البند" req error={errs[it.sku]}><input className={`line-input${errs[it.sku] ? ' is-invalid' : ''}`} value={s.reason} placeholder="مثال: عيب في السحّاب" onChange={(e) => set(it.sku, 'reason', e.target.value)} /></Field>
358:                       <Field label="صور" opt span hint="حتى 5 صور للبند · 5 ميجابايت للصورة · JPG / PNG / WebP">
359:                         <div className="row wrap">
360:                           {Array.from({ length: s.photos }).map((_, k) => <span key={k} className="photo-chip"><i className="fa-regular fa-image" /></span>)}
361:                           {s.photos < 5 && totalPhotos < 10 && <button className="drop sm" style={{ minHeight: 52, width: 52, padding: 0, justifyContent: 'center' }} onClick={() => set(it.sku, 'photos', s.photos + 1)} aria-label="إضافة صورة"><i className="fa-solid fa-plus" /></button>}
362:                         </div>
363:                       </Field>
364:                     </div>
365:                   )}
366:                 </div>);
367:             })}
368:           </Panel>
369:         </div>
370:         <aside className="stack" style={{ position: 'sticky', top: 100 }}>
371:           <Panel title="السبب والاسترداد">
372:             <Field label="السبب العام" req error={errs.reason}><textarea className={`line-input${errs.reason ? ' is-invalid' : ''}`} rows="3" value={reason} onChange={(e) => setReason(e.target.value)} /></Field>
373:             <div className="f-label mt-24">طريقة الاسترداد</div>
374:             <div className="radio-list">{Object.entries(REFUND_METHOD).map(([k, l]) => <label key={k} className="radio-row"><span className="radio-left"><input type="radio" checked={method === k} onChange={() => setMethod(k)} /><span className="radio-title">{l}</span></span></label>)}</div>
375:             <div className="sum-row mt-16"><span>صور مرفقة</span><strong className="num" style={{ color: totalPhotos > 10 ? '#b91c1c' : null }}>{totalPhotos} / 10</strong></div>
376:             <button className="btn-block mt-24" onClick={submit}>تقديم طلب الإرجاع</button>
377:           </Panel>
378:           <p className="note"><i className="fa-solid fa-circle-info" />إجمالي حجم الصور حتى 25 ميجابايت. مبلغ الاسترداد النهائي بيتحدد بعد فحص المرتجع.</p>
379:         </aside>
380:       </div>
381:     </>
382:   );
383: };
