385: export const ReturnDetail = ({ id }) => {
386:   const { go } = useApp();
387:   const r = RETURNS.find((x) => x.id === id) || RETURNS[0];
388:   const steps = [['requested', r.date], ['approved', r.approved_at], ['received', r.received_at], ['refunded', r.refunded_at]];
389:   return (
390:     <>
391:       <PageHead en={r.number} crumb={<Crumb items={[{ label: 'المرتجعات', go: () => go('returns') }, { label: r.number, mono: true }]} />} ar={<>على الطلب <button className="btn-link" onClick={() => go('order', 6)}><span className="num">{r.order}</span></button></>}>
392:         <Badge map={RETURN_STATUS} k={r.status} lg />
393:       </PageHead>
394:       <div className="grid-2">
395:         <div className="stack">
396:           <Panel title="البنود" en="ITEMS" body={false}>
397:             <table className="tbl"><thead><tr><th>المنتج</th><th>الكمية</th><th>السبب</th><th>صور</th></tr></thead>
398:               <tbody>{r.items.map((it) => <tr key={it.sku}><td><div className="prod-cell"><Thumb sm /><div><div className="prod-name">{it.name}</div><div className="sku">{it.sku}</div></div></div></td><td className="num">{it.qty}</td><td>{it.reason}</td><td><div className="row" style={{ gap: 6 }}>{Array.from({ length: it.photos }).map((_, k) => <span key={k} className="photo-chip" style={{ width: 36, height: 36 }}><i className="fa-regular fa-image" /></span>)}</div></td></tr>)}</tbody></table>
399:           </Panel>
400:           <Panel title="السبب العام"><p style={{ margin: 0 }}>{r.reason}</p></Panel>
401:         </div>
402:         <div className="stack">
403:           <Panel title="الاسترداد" en="REFUND">
404:             <dl className="kv"><dt>المبلغ</dt><dd><Money v={r.refund} strong /></dd><dt>الطريقة</dt><dd>{REFUND_METHOD[r.method]}</dd><dt>المرجع</dt><dd className="sku">{r.ref || '—'}</dd></dl>
405:           </Panel>
406:           <Panel title="المراحل" en="TIMELINE">
407:             <ul className="tl">{steps.map(([s, d], i) => <li key={s} className={d ? (steps[i + 1] && steps[i + 1][1] ? 'is-done' : 'is-now') : 'is-future'}><div className="tl-title">{RETURN_STATUS[s][0]}</div>{d && <div className="tl-meta num">{d}</div>}</li>)}</ul>
408:           </Panel>
409:         </div>
410:       </div>
411:     </>
412:   );
413: };  1: /* Sophie — Wholesale Portal. Built on the storefront's sophie.css / luxuryAuth.css vocabulary. */
  2: :root {
  3:   --ink: #111111;
  4:   --ink-2: #1e293b;
  5:   --body: #334155;
  6:   --muted: #64748b;
  7:   --soft: #94a3b8;
  8:   --line: #cbd5e1;
  9:   --line-2: #e5e7eb;
 10:   --bg: #f3f5f7;
 11:   --accent: #4f7d88;
 12:   --accent-soft: #dfe5e9;
 13:   --teal: #159a8c;
 14:   --info-bg: #f0f9fa; --info-line: #cce3e8; --info-ink: #2c545e;
 15:   --err-bg: #fef2f2; --err-line: #fecaca; --err-ink: #991b1b;
 16:   --ease: cubic-bezier(0.22, 1, 0.36, 1);
 17: }
 18: * { box-sizing: border-box; }
 19: html, body { margin: 0; }
 20: body {
 21:   font-family: 'Poppins', 'Cairo', sans-serif;
 22:   background: var(--bg);
 23:   color: var(--ink);
 24:   -webkit-font-smoothing: antialiased;
 25: }
 26: button, input, select, textarea { font-family: inherit; }
 27: .num { font-family: 'Poppins', sans-serif; font-variant-numeric: tabular-nums; direction: ltr; unicode-bidi: isolate; }
 28: .ltr { direction: ltr; unicode-bidi: isolate; }
 29: .osw { font-family: 'Oswald', sans-serif; text-transform: uppercase; letter-spacing: .06em; }
 30: 
 31: /* ============ HEADER (SophieHeader) ============ */
 32: .wp-header {
 33:   position: sticky; top: 0; z-index: 100;
 34:   height: 76px; display: flex; align-items: center; justify-content: space-between;
 35:   padding: 0 40px; background: rgba(255,255,255,.94); backdrop-filter: blur(10px);
 36:   border-bottom: 1px solid rgba(0,0,0,.05);
 37: }
 38: .wp-logo { display: flex; align-items: center; gap: 8px; font-family: 'Poppins', sans-serif; font-size: 22px; font-weight: 700; letter-spacing: -.5px; color: #000; text-decoration: none; cursor: pointer; background: none; border: 0; padding: 0; }
 39: .wp-logo-tag { font-family: 'Oswald', sans-serif; font-size: 11px; font-weight: 500; letter-spacing: 1px; color: var(--accent); text-transform: uppercase; border: 1px solid var(--accent-soft); border-radius: 999px; padding: 3px 10px; margin-inline-start: 6px; }
 40: .wp-head-right { display: flex; align-items: center; gap: 22px; }
 41: .wp-credit-chip { display: flex; align-items: center; gap: 10px; font-size: 12px; color: var(--muted); padding: 7px 14px; border: 1px solid var(--line-2); border-radius: 999px; background: #fff; }
 42: .wp-credit-chip strong { color: var(--ink); font-weight: 600; }
 43: .wp-icon-btn { position: relative; background: none; border: 0; padding: 4px; cursor: pointer; color: var(--ink); font-size: 16px; transition: color .2s; }
 44: .wp-icon-btn:hover { color: var(--accent); }
 45: .wp-count { position: absolute; top: -6px; inset-inline-end: -9px; min-width: 17px; height: 17px; padding: 0 4px; border-radius: 999px; background: #000; color: #fff; font: 600 10px 'Poppins', sans-serif; display: inline-flex; align-items: center; justify-content: center; }
 46: .wp-avatar { width: 36px; height: 36px; border-radius: 50%; background: var(--accent-soft); color: var(--info-ink); display: inline-flex; align-items: center; justify-content: center; font: 600 12px 'Poppins', sans-serif; border: 1px solid #fff; box-shadow: 0 0 0 1px var(--line-2); cursor: pointer; }
 47: 
 48: /* ============ LAYOUT ============ */
 49: .wp-layout { display: grid; grid-template-columns: 248px minmax(0, 1fr); min-height: calc(100vh - 76px); }
 50: .wp-side { position: sticky; top: 76px; align-self: start; height: calc(100vh - 76px); overflow-y: auto; padding: 34px 28px 40px 18px; border-inline-end: 1px solid var(--line-2); background: #fff; }
 51: .wp-side-tag { font-family: 'Oswald', sans-serif; font-size: 11px; font-weight: 500; letter-spacing: 1px; color: var(--accent); text-transform: uppercase; margin-bottom: 18px; direction: ltr; text-align: right; }
 52: .wp-side-group { margin-bottom: 22px; }
 53: .wp-side-group-title { font-family: 'Oswald', sans-serif; font-size: 11px; letter-spacing: .1em; color: var(--soft); text-transform: uppercase; margin: 0 0 6px; }
 54: .wp-side-link { display: flex; align-items: center; justify-content: space-between; gap: 10px; width: 100%; padding: 8px 0; background: none; border: 0; cursor: pointer; font-family: 'Cairo', sans-serif; font-size: 14px; color: #475569; text-align: start; transition: color .2s; }
 55: .wp-side-link:hover { color: var(--accent); }
 56: .wp-side-link.is-active { color: var(--ink); font-weight: 700; }
 57: .wp-side-link.is-active .wp-side-dot { opacity: 1; }
 58: .wp-side-dot { width: 6px; height: 6px; border-radius: 50%; background: var(--accent); opacity: 0; }
 59: .wp-side-badge { font: 600 10px 'Poppins', sans-serif; background: #111; color: #fff; border-radius: 999px; padding: 2px 7px; }
 60: .wp-side-foot { margin-top: 30px; padding-top: 20px; border-top: 1px solid var(--line-2); }
 61: .wp-main { padding: 42px 48px 90px; min-width: 0; }
 62: .wp-wrap { max-width: 1180px; margin: 0 auto; }
 63: 
 64: /* ============ PAGE HEAD (checkout-giant-title) ============ */
 65: .wp-page-top { display: flex; align-items: flex-end; justify-content: space-between; gap: 20px; flex-wrap: wrap; margin-bottom: 34px; }
 66: .wp-giant { font-family: 'Oswald', sans-serif; font-size: 60px; font-weight: 700; letter-spacing: 1.5px; text-transform: uppercase; color: var(--ink); line-height: 1; margin: 0; direction: ltr; text-align: right; }
 67: .wp-page-ar { font-family: 'Cairo', sans-serif; font-size: 15px; color: var(--muted); margin: 10px 0 0; }
 68: .wp-crumb { font-family: 'Cairo', sans-serif; font-size: 13px; color: var(--soft); margin-bottom: 12px; display: flex; gap: 8px; align-items: center; }
 69: .wp-crumb button { background: none; border: 0; padding: 0; color: var(--muted); cursor: pointer; font: inherit; text-decoration: underline; text-underline-offset: 4px; }
 70: .wp-actions { display: flex; gap: 10px; flex-wrap: wrap; align-items: center; }
 71: 
 72: /* ============ BUTTONS ============ */
 73: .btn-pill { display: inline-flex; align-items: center; gap: 8px; border: 1px solid var(--line); background: #fff; padding: 9px 18px; border-radius: 999px; font: 500 12.5px 'Cairo', sans-serif; color: var(--body); cursor: pointer; transition: all .2s ease; text-decoration: none; white-space: nowrap; }
 74: .btn-pill:hover { background: var(--ink); color: #fff; border-color: var(--ink); }
 75: .btn-pill.is-dark { background: var(--ink); color: #fff; border-color: var(--ink); }
 76: .btn-pill.is-dark:hover { background: #2c2c2c; }
 77: .btn-pill.is-danger { color: #b91c1c; border-color: #fecaca; }
 78: .btn-pill.is-danger:hover { background: #b91c1c; color: #fff; border-color: #b91c1c; }
 79: .btn-pill:disabled { opacity: .45; cursor: not-allowed; background: #fff; color: var(--body); border-color: var(--line); }
 80: .btn-pill.sm { padding: 6px 12px; font-size: 12px; }
 81: .btn-block { width: 100%; background: #1a1a1a; color: #fff; border: 0; padding: 16px 24px; font: 500 13px 'Oswald', 'Cairo', sans-serif; letter-spacing: 1px; text-transform: uppercase; cursor: pointer; transition: background-color .2s, transform .15s; display: inline-flex; align-items: center; justify-content: center; gap: 10px; }
 82: .btn-block:hover { background: var(--teal); transform: translateY(-1px); }
 83: .btn-block:disabled { opacity: .5; cursor: not-allowed; transform: none; background: #1a1a1a; }
 84: .btn-soft { background: var(--accent-soft); color: var(--body); border: 0; padding: 11px 16px; font: 500 12px 'Cairo', sans-serif; cursor: pointer; transition: background-color .2s, color .2s; white-space: nowrap; }
 85: .btn-soft:hover { background: var(--ink); color: #fff; }
 86: .btn-link { background: none; border: 0; padding: 0; color: var(--ink); font: 600 13px 'Cairo', sans-serif; text-decoration: underline; text-underline-offset: 4px; cursor: pointer; }
 87: .btn-link:hover { color: var(--accent); }
 88: .btn-link.muted { color: var(--muted); font-weight: 500; }
 89: .btn-link.danger { color: #b91c1c; }
 90: 
 91: /* ============ PANELS ============ */
 92: .panel { background: #fff; border: 1px solid var(--line-2); border-radius: 4px; }
 93: .panel-head { display: flex; align-items: baseline; justify-content: space-between; gap: 16px; padding: 20px 24px 0; }
 94: .panel-title { font-family: 'Cairo', sans-serif; font-size: 17px; font-weight: 700; color: var(--ink); margin: 0; }
 95: .panel-en { font-family: 'Oswald', sans-serif; font-size: 11px; letter-spacing: .1em; color: var(--soft); text-transform: uppercase; }
 96: .panel-body { padding: 18px 24px 24px; }
 97: .grid-2 { display: grid; grid-template-columns: 1.4fr 1fr; gap: 28px; align-items: start; }
 98: .grid-2e { display: grid; grid-template-columns: 1fr 1fr; gap: 28px; align-items: start; }
 99: .stack { display: flex; flex-direction: column; gap: 24px; }
100: 
101: /* KPI tiles */
102: .kpis { display: grid; grid-template-columns: repeat(4, minmax(0,1fr)); gap: 16px; margin-bottom: 28px; }
103: .kpi { background: #fff; border: 1px solid var(--line-2); border-radius: 4px; padding: 20px 22px 22px; display: flex; flex-direction: column; gap: 10px; min-width: 0; }
104: .kpi.is-ink { background: var(--ink); color: #fff; border-color: var(--ink); }
105: .kpi-label { font-family: 'Cairo', sans-serif; font-size: 13px; color: var(--muted); }
106: .kpi.is-ink .kpi-label { color: #a3a3a3; }
107: .kpi-en { font-family: 'Oswald', sans-serif; font-size: 10px; letter-spacing: .12em; color: var(--soft); text-transform: uppercase; direction: ltr; }
108: .kpi-value { font-family: 'Poppins', sans-serif; font-size: 26px; font-weight: 600; letter-spacing: -.5px; direction: ltr; text-align: right; }
109: .kpi-value small { font-size: 12px; font-weight: 500; color: var(--soft); margin-inline-start: 4px; }
110: .kpi-bar { height: 4px; background: var(--accent-soft); border-radius: 4px; overflow: hidden; }
111: .kpi-bar > span { display: block; height: 100%; background: var(--accent); }
112: .kpi-foot { font-size: 12px; color: var(--muted); }
113: 
114: /* ============ TABLES ============ */
115: .tbl-wrap { overflow-x: auto; }
116: .tbl { width: 100%; border-collapse: collapse; font-size: 13px; }
117: .tbl th { font-family: 'Cairo', sans-serif; font-weight: 600; font-size: 12px; color: var(--soft); text-align: start; padding: 12px 12px; border-bottom: 1px solid var(--line); white-space: nowrap; }
118: .tbl td { padding: 14px 12px; border-bottom: 1px solid var(--line-2); color: var(--body); vertical-align: middle; }
119: .tbl tr:last-child td { border-bottom: 0; }
120: .tbl td.strong, .tbl .strong { color: var(--ink); font-weight: 600; }
121: .tbl tr.is-click { cursor: pointer; transition: background .15s; }
122: .tbl tr.is-click:hover td { background: #fafbfc; }
123: .tbl tr.is-error td { background: #fffafa; }
124: .tbl tr.is-warn td { background: #fffdf5; }
125: .tbl .t-end { text-align: end; }
126: .tbl tfoot td { border-top: 1px solid var(--line); border-bottom: 0; font-weight: 600; color: var(--ink); }
127: .row-actions { display: flex; gap: 14px; justify-content: flex-end; align-items: center; white-space: nowrap; }
128: 
129: /* ============ BADGES (@alfarid/ui Badge) ============ */
130: .badge { display: inline-flex; align-items: center; gap: 6px; border-radius: 999px; border: 1px solid; padding: 2px 10px; font: 500 12px 'Cairo', sans-serif; white-space: nowrap; line-height: 1.7; }
131: .badge::before { content: ''; width: 6px; height: 6px; border-radius: 50%; background: currentColor; opacity: .8; }
132: .badge.default { background: #f4f4f5; color: #3f3f46; border-color: #e4e4e7; }
133: .badge.success { background: #ecfdf5; color: #047857; border-color: #a7f3d0; }
134: .badge.warning { background: #fffbeb; color: #b45309; border-color: #fde68a; }
135: .badge.danger { background: #fff1f2; color: #be123c; border-color: #fecdd3; }
136: .badge.info { background: #f0f9ff; color: #0369a1; border-color: #bae6fd; }
137: .badge.accent { background: var(--info-bg); color: var(--info-ink); border-color: var(--info-line); }
138: .badge.lg { font-size: 14px; padding: 5px 14px; }
139: 
140: /* ============ FORMS (line inputs) ============ */
141: .fields { display: grid; grid-template-columns: 1fr 1fr; column-gap: 28px; row-gap: 22px; }
142: .fields .span-2 { grid-column: 1 / -1; }
143: .f-label { display: block; font: 600 12.5px 'Cairo', sans-serif; color: var(--ink-2); margin-bottom: 4px; }
144: .f-req { color: var(--accent); margin-inline-start: 4px; }
145: .f-opt { color: var(--soft); font-weight: 400; margin-inline-start: 6px; font-size: 11.5px; }
146: .line-input { width: 100%; background: transparent; border: 0; border-bottom: 1px solid var(--line); padding: 10px 0; font: 13.5px 'Cairo', 'Poppins', sans-serif; color: var(--ink); outline: none; transition: border-color .2s; border-radius: 0; }
147: .line-input::placeholder { color: var(--soft); }
148: .line-input:focus { border-bottom-color: var(--teal); }
149: .line-input.is-invalid { border-bottom-color: #dc2626; }
150: select.line-input { appearance: none; background-image: linear-gradient(45deg, transparent 50%, var(--muted) 50%), linear-gradient(135deg, var(--muted) 50%, transparent 50%); background-position: 8px 55%, 13px 55%; background-size: 5px 5px; background-repeat: no-repeat; padding-inline-end: 0; padding-inline-start: 0; cursor: pointer; }
151: textarea.line-input { resize: vertical; min-height: 84px; line-height: 1.8; }
152: .f-error { margin: 6px 0 0; color: #b91c1c; font-size: 12px; display: flex; gap: 6px; align-items: center; }
153: .f-hint { margin: 6px 0 0; color: var(--soft); font-size: 11.5px; line-height: 1.7; }
154: .f-counter { font-family: 'Poppins', sans-serif; font-size: 11px; color: var(--soft); }
155: .box-input { width: 100%; border: 1px solid var(--line); background: #fff; border-radius: 3px; padding: 8px 10px; font: 13px 'Poppins', 'Cairo', sans-serif; color: var(--ink); outline: none; }
156: .box-input:focus { border-color: var(--teal); }
157: .box-input.is-invalid { border-color: #dc2626; background: #fffafa; }
158: 
159: .radio-list { display: flex; flex-direction: column; }
160: .radio-row { border-bottom: 1px solid var(--line); padding: 14px 0; display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; cursor: pointer; }
161: .radio-row.is-disabled { cursor: not-allowed; opacity: .55; }
162: .radio-left { display: flex; gap: 10px; align-items: flex-start; }
163: .radio-left input { accent-color: var(--ink); margin-top: 5px; }
164: .radio-title { font-size: 13.5px; font-weight: 600; color: var(--ink); display: block; }
165: .radio-desc { font-size: 12px; color: var(--soft); display: block; margin-top: 2px; }
166: .radio-price { font-size: 13px; font-weight: 600; color: var(--ink); white-space: nowrap; }
167: .check-row { display: flex; align-items: flex-start; gap: 10px; font-size: 12.5px; color: var(--muted); cursor: pointer; line-height: 1.7; }
168: .check-row input { accent-color: var(--ink); width: 15px; height: 15px; margin-top: 4px; }
169: 
170: .seg { display: inline-flex; background: #f4f6f8; border: 1px solid #e9ecef; border-radius: 30px; padding: 4px; gap: 4px; }
171: .seg button { padding: 7px 16px; border-radius: 20px; border: 0; background: transparent; color: #777; cursor: pointer; font: 500 12.5px 'Cairo', sans-serif; display: inline-flex; gap: 6px; align-items: center; transition: all .25s; }
172: .seg button.is-on { background: #000; color: #fff; box-shadow: 0 2px 8px rgba(0,0,0,.15); }
173: .seg button .seg-n { font: 600 10px 'Poppins', sans-serif; opacity: .7; }
174: 
175: .chips { display: flex; gap: 8px; flex-wrap: wrap; }
176: .chip { border: 1px solid var(--line); background: #fff; border-radius: 999px; padding: 6px 14px; font: 500 12.5px 'Cairo', sans-serif; color: var(--body); cursor: pointer; transition: all .2s; display: inline-flex; gap: 6px; align-items: center; }
177: .chip:hover { border-color: var(--ink); }
178: .chip.is-on { background: var(--ink); color: #fff; border-color: var(--ink); }
179: .chip .num { font-size: 11px; opacity: .65; }
180: 
181: .toolbar { display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap; padding: 18px 24px; border-bottom: 1px solid var(--line-2); }
182: .search { position: relative; min-width: 300px; }
183: .search i { position: absolute; inset-inline-start: 0; top: 50%; transform: translateY(-50%); color: var(--soft); font-size: 13px; }
184: .search .line-input { padding-inline-start: 24px; }
185: 
186: /* qty stepper */
187: .qty { display: inline-flex; align-items: center; border: 1px solid var(--line); border-radius: 999px; background: #fff; height: 32px; }
188: .qty button { width: 30px; height: 30px; border: 0; background: none; cursor: pointer; color: var(--ink); font-size: 11px; border-radius: 50%; }
189: .qty button:hover { background: var(--ink); color: #fff; }
190: .qty input { width: 48px; border: 0; text-align: center; font: 600 13px 'Poppins', sans-serif; outline: none; background: transparent; }
191: 
192: /* banners (checkout-banner) */
193: .banner { display: flex; align-items: flex-start; gap: 12px; border-radius: 4px; padding: 12px 16px; font-size: 13px; line-height: 1.8; border: 1px solid; }
194: .banner i { margin-top: 5px; }
195: .banner.is-error { background: var(--err-bg); color: var(--err-ink); border-color: var(--err-line); }
196: .banner.is-info { background: var(--info-bg); color: var(--info-ink); border-color: var(--info-line); }
197: .banner.is-warn { background: #fffbeb; color: #92400e; border-color: #fde68a; }
198: .banner.is-ok { background: #ecfdf5; color: #065f46; border-color: #a7f3d0; }
199: .banner .banner-body { flex: 1; }
200: .banner strong { font-weight: 700; }
201: 
202: /* summary rows (bag-totals-row) */
203: .sum-row { display: flex; align-items: center; justify-content: space-between; padding: 11px 0; border-bottom: 1px solid var(--line); font-size: 13px; color: var(--body); gap: 12px; }
204: .sum-row strong { color: var(--ink); font-weight: 600; }
205: .sum-row.is-neg strong { color: var(--teal); }
206: .sum-total { display: flex; align-items: baseline; justify-content: space-between; padding-top: 18px; font-size: 16px; font-weight: 700; color: var(--ink); }
207: .sum-total .num { font-size: 24px; font-weight: 700; }
208: .kv { display: grid; grid-template-columns: 130px 1fr; row-gap: 12px; column-gap: 16px; font-size: 13px; }
209: .kv dt { color: var(--soft); }
210: .kv dd { margin: 0; color: var(--ink); font-weight: 600; min-width: 0; overflow-wrap: anywhere; }
211: 
212: /* thumbs */
213: .thumb { width: 64px; height: 72px; background: #e4e9ed; display: flex; align-items: center; justify-content: center; border-radius: 2px; color: #a9b6bf; font-size: 22px; flex-shrink: 0; }
214: .thumb.sm { width: 44px; height: 50px; font-size: 16px; }
215: .prod-cell { display: flex; gap: 14px; align-items: center; min-width: 0; }
216: .prod-name { font-weight: 600; color: var(--ink); font-size: 13.5px; }
217: .prod-en { font-family: 'Poppins', sans-serif; font-size: 11.5px; color: var(--soft); direction: ltr; text-align: right; }
218: .sku { font-family: 'JetBrains Mono', monospace; font-size: 11.5px; color: var(--muted); direction: ltr; unicode-bidi: isolate; }
219: .strike { text-decoration: line-through; color: var(--soft); font-weight: 400; }
220: .tier { display: inline-flex; gap: 4px; align-items: baseline; border: 1px solid var(--info-line); background: var(--info-bg); color: var(--info-ink); border-radius: 3px; padding: 2px 7px; font-size: 11.5px; margin: 2px 0 2px 4px; white-space: nowrap; }
221: 
222: /* pager */
223: .pager { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 14px 24px; border-top: 1px solid var(--line-2); font-size: 12.5px; color: var(--muted); }
224: .pager-btns { display: flex; gap: 4px; }
225: .pager-btns button { min-width: 32px; height: 32px; border-radius: 50%; border: 1px solid transparent; background: none; cursor: pointer; font: 500 12px 'Poppins', sans-serif; color: var(--body); }
226: .pager-btns button:hover { border-color: var(--line); }
227: .pager-btns button.is-on { background: var(--ink); color: #fff; }
228: .pager-btns button:disabled { opacity: .35; cursor: default; }
229: 
230: /* timeline */
231: .tl { list-style: none; margin: 0; padding: 0; }
232: .tl li { position: relative; padding: 0 26px 22px 0; }
233: .tl li::before { content: ''; position: absolute; right: 5px; top: 8px; bottom: -4px; width: 1px; background: var(--line); }
234: .tl li:last-child::before { display: none; }
235: .tl li::after { content: ''; position: absolute; right: 0; top: 4px; width: 11px; height: 11px; border-radius: 50%; background: #fff; border: 1px solid var(--line); }
236: .tl li.is-done::after { background: var(--accent); border-color: var(--accent); }
237: .tl li.is-now::after { background: #fff; border: 3px solid var(--accent); }
238: .tl-title { font-weight: 600; font-size: 13.5px; color: var(--ink); }
239: .tl li.is-future .tl-title { color: var(--soft); font-weight: 500; }
240: .tl-meta { font-size: 12px; color: var(--soft); margin-top: 2px; }
241: 
242: /* drop zone (luxury-file-picker) */
243: .drop { position: relative; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 8px; min-height: 150px; border: 1px dashed #a3a3a3; border-radius: 12px; background: #fafafa; color: #262626; font-size: 14px; text-align: center; padding: 24px; cursor: pointer; transition: border-color .2s, background .2s; }
244: .drop:hover { border-color: var(--ink); background: #fff; }
245: .drop i { font-size: 26px; color: var(--accent); }
246: .drop small { color: var(--muted); font-size: 12px; }
247: .drop.sm { min-height: 64px; flex-direction: row; padding: 12px; font-size: 13px; }
248: .drop.sm i { font-size: 16px; }
249: .drop.is-invalid { border-color: #dc2626; background: #fffafa; }
250: .file-row { display: flex; align-items: center; gap: 12px; padding: 10px 14px; border: 1px solid var(--line-2); border-radius: 10px; background: #fff; font-size: 12.5px; }
251: .file-row i.fa-file-pdf, .file-row i.fa-file-image, .file-row i.fa-file-excel { color: var(--accent); font-size: 18px; }
252: .file-row .grow { flex: 1; min-width: 0; overflow-wrap: anywhere; }
253: .photo-chip { width: 52px; height: 52px; border-radius: 6px; background: #e4e9ed; display: inline-flex; align-items: center; justify-content: center; color: #9aa8b2; font-size: 15px; position: relative; }
254: 
255: /* states */
256: .state { display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center; padding: 70px 24px; gap: 10px; }
257: .state-icon { width: 64px; height: 64px; border-radius: 50%; display: inline-flex; align-items: center; justify-content: center; font-size: 24px; background: #f1f5f9; color: var(--soft); margin-bottom: 6px; }
258: .state-icon.is-err { background: var(--err-bg); color: #dc2626; }
259: .state-title { font-family: 'Cairo', sans-serif; font-size: 18px; font-weight: 700; margin: 0; }
260: .state-desc { font-size: 13px; color: var(--muted); max-width: 380px; line-height: 1.8; margin: 0 0 8px; }
261: .sk { background: linear-gradient(90deg,#f0f1f3 25%,#e6e8eb 37%,#f0f1f3 63%); background-size: 400% 100%; animation: skShimmer 1.2s ease infinite; border-radius: 3px; }
262: @keyframes skShimmer { 0% { background-position: 100% 50%; } 100% { background-position: 0 50%; } }
263: .spin { width: 14px; height: 14px; border: 2px solid currentColor; border-top-color: transparent; border-radius: 50%; display: inline-block; animation: spin .7s linear infinite; }
264: @keyframes spin { to { transform: rotate(360deg); } }
265: 
266: /* modal (order-modal) */
267: .modal-bg { position: fixed; inset: 0; background: rgba(15,23,42,.55); backdrop-filter: blur(4px); display: flex; align-items: center; justify-content: center; z-index: 500; padding: 20px; animation: fadeIn .2s ease; }
268: @keyframes fadeIn { from { opacity: 0; } }
269: .modal { background: #fff; width: 100%; max-width: 560px; border-radius: 16px; box-shadow: 0 25px 60px rgba(0,0,0,.22); max-height: calc(100vh - 40px); display: flex; flex-direction: column; animation: popIn .3s var(--ease); }
270: .modal.wide { max-width: 820px; }
271: @keyframes popIn { from { transform: translateY(12px); opacity: 0; } }
272: .modal-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; padding: 26px 30px 0; }
273: .modal-title { font-family: 'Cairo', sans-serif; font-size: 20px; font-weight: 700; margin: 0; }
274: .modal-x { width: 36px; height: 36px; border-radius: 50%; border: 1px solid var(--line-2); background: #fff; cursor: pointer; color: var(--muted); flex-shrink: 0; }
275: .modal-x:hover { background: var(--ink); color: #fff; }
276: .modal-body { padding: 20px 30px; overflow-y: auto; }
277: .modal-foot { padding: 0 30px 26px; display: flex; gap: 10px; justify-content: flex-end; flex-wrap: wrap; }
278: .modal-icon { width: 56px; height: 56px; border-radius: 50%; background: #e6f6f4; color: var(--teal); font-size: 22px; display: inline-flex; align-items: center; justify-content: center; }
279: .modal-icon.is-warn { background: #fffbeb; color: #b45309; }
280: .modal-icon.is-err { background: var(--err-bg); color: #dc2626; }
281: 
282: /* toast */
283: .toast { position: fixed; bottom: 26px; left: 50%; transform: translateX(-50%); background: #0f172a; color: #fff; padding: 12px 20px; border-radius: 999px; font-size: 13px; display: flex; align-items: center; gap: 12px; box-shadow: 0 12px 30px rgba(0,0,0,.22); z-index: 999; animation: toastIn .3s var(--ease); }
284: .toast i { color: var(--teal); }
285: .toast button { background: var(--teal); color: #fff; border: 0; border-radius: 999px; padding: 4px 12px; font: 600 11.5px 'Cairo', sans-serif; cursor: pointer; }
286: @keyframes toastIn { from { transform: translate(-50%, 15px); opacity: 0; } }
287: 
288: /* steps */
289: .steps { display: flex; gap: 18px; list-style: none; margin: 0 0 26px; padding: 0; font-family: 'Cairo', sans-serif; font-size: 13px; }
290: .step { display: flex; align-items: center; gap: 8px; color: var(--soft); }
291: .step-dot { width: 26px; height: 26px; border-radius: 50%; border: 1px solid var(--line); display: inline-flex; align-items: center; justify-content: center; font: 12px 'Poppins', sans-serif; }
292: .step.is-now { color: #111827; font-weight: 600; }
293: .step.is-now .step-dot { border-color: var(--accent); color: var(--accent); }
294: .step.is-done { color: var(--accent); }
295: .step.is-done .step-dot { background: var(--accent); border-color: var(--accent); color: #fff; }
296: 
297: /* notifications */
298: .notif { display: grid; grid-template-columns: 40px 1fr auto; gap: 16px; padding: 18px 24px; border-bottom: 1px solid var(--line-2); align-items: start; }
299: .notif.is-unread { background: #fbfcfd; }
300: .notif-ic { width: 40px; height: 40px; border-radius: 50%; background: #f1f5f9; color: var(--muted); display: inline-flex; align-items: center; justify-content: center; position: relative; }
301: .notif.is-unread .notif-ic { background: var(--info-bg); color: var(--accent); }
