 45: /* Loading / empty / error */
 46: export const SkeletonRows = ({ rows = 5, cols = 5 }) => (
 47:   <div style={{ padding: '18px 24px' }} aria-busy="true" aria-label="جارٍ التحميل">
 48:     {Array.from({ length: rows }).map((_, r) => (
 49:       <div key={r} style={{ display: 'grid', gridTemplateColumns: `repeat(${cols}, 1fr)`, gap: 18, padding: '14px 0', borderBottom: '1px solid var(--line-2)' }}>
 50:         {Array.from({ length: cols }).map((_, c) => <div key={c} className="sk" style={{ height: 12, width: `${55 + ((r * 7 + c * 13) % 40)}%` }} />)}
 51:       </div>
 52:     ))}
 53:   </div>
 54: );
 55: export const Empty = ({ icon = 'fa-inbox', title, desc, action }) => (
 56:   <div className="state">
 57:     <div className="state-icon"><i className={`fa-solid ${icon}`} /></div>
 58:     <p className="state-title">{title}</p>
 59:     {desc && <p className="state-desc">{desc}</p>}
 60:     {action}
 61:   </div>
