 63: export const ErrorState = ({ onRetry, title = 'تعذر تحميل البيانات', desc = 'حصلت مشكلة في الاتصال بالخادم. تأكد من الاتصال وحاول مرة أخرى.' }) => (
 64:   <div className="state" role="alert">
 65:     <div className="state-icon is-err"><i className="fa-solid fa-triangle-exclamation" /></div>
 66:     <p className="state-title">{title}</p>
 67:     <p className="state-desc">{desc}</p>
 68:     <button className="btn-pill is-dark" onClick={onRetry}><i className="fa-solid fa-rotate-right" /> إعادة المحاولة</button>
 69:   </div>
 70: );
