 72: /* Async wrapper — global "data state" tweak drives it */
 73: export const DataStateCtx = React.createContext({ state: 'ready', retry: () => {} });
 74: export const Async = ({ children, empty, rows, cols, isEmpty }) => {
 75:   const { state, retry } = React.useContext(DataStateCtx);
 76:   if (state === 'loading') return <SkeletonRows rows={rows} cols={cols} />;
 77:   if (state === 'error') return <ErrorState onRetry={retry} />;
 78:   if (state === 'empty' || isEmpty) return empty || <Empty title="لا توجد بيانات" />;
 79:   return children;
 80: };
