 82: export const Pager = ({ page = 1, pages = 3, total, per = 15, onPage = () => {} }) => (
 83:   <div className="pager">
 84:     <span>عرض <span className="num">{(page - 1) * per + 1}–{Math.min(page * per, total)}</span> من <span className="num">{total}</span></span>
 85:     <div className="pager-btns">
 86:       <button disabled={page === 1} onClick={() => onPage(page - 1)} aria-label="السابق"><i className="fa-solid fa-chevron-right" /></button>
 87:       {Array.from({ length: pages }).map((_, i) => <button key={i} className={page === i + 1 ? 'is-on' : ''} onClick={() => onPage(i + 1)}>{i + 1}</button>)}
 88:       <button disabled={page === pages} onClick={() => onPage(page + 1)} aria-label="التالي"><i className="fa-solid fa-chevron-left" /></button>
 89:     </div>
 90:   </div>
 91: );
