105: export const Modal = ({ title, onClose, children, foot, wide, icon }) => {
106:   useEffect(() => {
107:     const k = (e) => e.key === 'Escape' && onClose();
108:     window.addEventListener('keydown', k);
109:     return () => window.removeEventListener('keydown', k);
110:   }, [onClose]);
111:   return (
112:     <div className="modal-bg" onMouseDown={(e) => e.target === e.currentTarget && onClose()}>
113:       <div className={`modal${wide ? ' wide' : ''}`} role="dialog" aria-modal="true">
114:         <div className="modal-head">
115:           <div className="row" style={{ gap: 14 }}>
116:             {icon}
117:             <h2 className="modal-title">{title}</h2>
118:           </div>
119:           <button className="modal-x" onClick={onClose} aria-label="إغلاق"><i className="fa-solid fa-xmark" /></button>
120:         </div>
121:         <div className="modal-body">{children}</div>
122:         {foot && <div className="modal-foot">{foot}</div>}
123:       </div>
124:     </div>
125:   );
126: };
