 60:       { id: 'quick', label: 'طلب سريع', icon: 'fa-bolt' },
 61:       { id: 'cart', label: 'سلة المشتريات', icon: 'fa-bag-shopping', badge: 'cart' },
 62:       { id: 'orders', label: 'الطلبات', icon: 'fa-box' },
 63:       { id: 'quotes', label: 'عروض الأسعار', icon: 'fa-file-signature' },
 64:       { id: 'returns', label: 'المرتجعات', icon: 'fa-rotate-left' },
 65:     ],
 66:   },
 67:   {
 68:     title: 'المالية والحساب',
 69:     items: [
 70:       { id: 'invoices', label: 'الفواتير', icon: 'fa-file-lines' },
 71:       { id: 'statement', label: 'كشف الحساب', icon: 'fa-file-invoice-dollar' },
 72:       { id: 'notices', label: 'إشعارات السداد', icon: 'fa-money-check-dollar' },
 73:       { id: 'wallet', label: 'المحفظة', icon: 'fa-wallet' },
 74:     ],
 75:   },
 76:   {
 77:     title: 'الإعدادات',
 78:     items: [
 79:       { id: 'account', label: 'بيانات الحساب', icon: 'fa-building' },
 80:       { id: 'notifications', label: 'الإشعارات', icon: 'fa-bell', badge: 'notifs' },
 81:       { id: 'status', label: 'حالة الحساب', icon: 'fa-shield-halved' },
 82:     ],
 83:   },
 84: ];
 85: 
 86: export function WholesalePortal({
 87:   initialScreen = 'dashboard',
 88:   initialId = null,
 89:   onLogout,
 90:   brandName = 'SOPHIE',
 91: }) {
 92:   const [route, setRoute] = useState({ screen: initialScreen, id: initialId });
 93:   const [cart, setCart] = useState([
 94:     {
 95:       ...ALL_VARIANTS[0],
 96:       product: PRODUCTS[0],
 97:       qty: 6,
 98:     },
 99:     {
100:       ...ALL_VARIANTS[3],
101:       product: PRODUCTS[1],
102:       qty: 4,
103:     },
104:   ]);
105:   const [notifs, setNotifs] = useState(NOTIFS);
106:   const [orders, setOrders] = useState(ORDERS);
107:   const [lastOrder, setLastOrder] = useState(ORDERS[0]);
108:   const [toasts, setToasts] = useState([]);
109: 
110:   const toast = useCallback((msg) => {
111:     const id = Date.now() + Math.random();
112:     setToasts((prev) => [...prev, { id, msg }]);
113:     setTimeout(() => {
114:       setToasts((prev) => prev.filter((t) => t.id !== id));
115:     }, 3500);
116:   }, []);
117: 
118:   const go = useCallback((screen, id = null) => {
119:     setRoute({ screen, id });
120:     if (typeof window !== 'undefined') {
121:       window.scrollTo({ top: 0, behavior: 'smooth' });
122:     }
123:   }, []);
124: 
125:   const addToCart = useCallback((variant, qty = 1) => {
126:     setCart((prev) => {
127:       const existing = prev.find((item) => item.sku === variant.sku);
128:       if (existing) {
129:         return prev.map((item) =>
130:           item.sku === variant.sku ? { ...item, qty: item.qty + qty } : item
131:         );
132:       }
133:       const prod = PRODUCTS.find((p) => p.id === variant.productId) || PRODUCTS[0];
134:       return [...prev, { ...variant, product: prod, qty }];
135:     });
136:     toast('تمت الإضافة إلى سلة المشتريات بنجاح');
137:   }, [toast]);
138: 
139:   const placeOrder = useCallback((payload) => {
140:     const newId = orders.length + 1;
141:     const newOrder = {
142:       id: newId,
143:       number: `ORD-2026-0${140 + newId}`,
144:       date: new Date().toISOString().split('T')[0],
145:       status: 'pending',
146:       pay: payload.payment_method === 'credit' ? 'unpaid' : 'paid',
147:       method: payload.payment_method || 'credit',
148:       subtotal: payload.subtotal || 25000,
149:       discount: payload.discount || 0,
150:       tax: payload.tax || 3500,
151:       shipping: payload.shipping || 0,
152:       total: payload.total || 28500,
153:       items: cart.map((it) => ({
154:         name: it.product?.name_ar || it.name || 'حقيبة',
155:         sku: it.sku,
156:         qty: it.qty,
157:         price: it.price || 1500,
158:         color: it.color || 'أسود',
159:       })),
160:       history: [
161:         ['pending', 'الآن', 'تم استلام الطلب وبانتظار المراجعة والتأكيد'],
162:       ],
163:       po: payload.po_number || null,
164:       address: payload.shipping_address || 'المخزن الرئيسي',
165:       notes: payload.notes || null,
166:     };
167:     setOrders((prev) => [newOrder, ...prev]);
168:     setLastOrder(newOrder);
169:     setCart([]);
170:     toast(`تم تسجيل الطلب ${newOrder.number} بنجاح`);
171:     return newOrder;
172:   }, [cart, orders.length, toast]);
173: 
174:   const logout = useCallback(() => {
175:     if (onLogout) onLogout();
176:     else toast('تم تسجيل الخروج');
177:   }, [onLogout, toast]);
178: 
179:   const unreadNotifsCount = useMemo(() => notifs.filter((n) => n.unread).length, [notifs]);
180:   const cartTotalQty = useMemo(() => cart.reduce((sum, it) => sum + (it.qty || 0), 0), [cart]);
181: 
182:   const contextValue = useMemo(() => ({
183:     go,
184:     route,
185:     cart,
186:     setCart,
187:     addToCart,
188:     placeOrder,
189:     lastOrder,
190:     notifs,
191:     setNotifs,
192:     orders,
193:     setOrders,
194:     toast,
195:     account: ACCOUNT,
196:     logout,
197:   }), [go, route, cart, placeOrder, lastOrder, notifs, orders, toast, logout]);
198: 
199:   // Screen router
200:   const renderScreen = () => {
201:     const { screen, id } = route;
202:     switch (screen) {
203:       case 'dashboard':
204:         return <Dashboard />;
205:       case 'catalog':
206:         return <Catalog />;
207:       case 'quick':
208:         return <QuickOrder />;
209:       case 'cart':
210:         return <Cart />;
211:       case 'checkout':
212:         return <Checkout />;
213:       case 'success':
214:       case 'orderSuccess':
215:         return <OrderSuccess />;
216:       case 'orders':
217:         return <Orders />;
218:       case 'order':
219:         return <OrderDetail id={id} />;
220:       case 'quotes':
221:         return <Quotes />;
222:       case 'quoteNew':
223:         return <QuoteForm />;
224:       case 'quoteEdit':
225:         return <QuoteForm id={id} />;
226:       case 'quote':
227:         return <QuoteDetail id={id} />;
228:       case 'returns':
229:         return <Returns />;
230:       case 'returnNew':
231:         return <ReturnForm orderId={id} />;
232:       case 'return':
233:         return <ReturnDetail id={id} />;
234:       case 'invoices':
235:         return <Invoices />;
236:       case 'statement':
237:         return <Statement />;
238:       case 'notices':
239:         return <Notices />;
240:       case 'noticeNew':
241:         return <NoticeForm />;
242:       case 'notice':
243:         return <NoticeDetail id={id} />;
244:       case 'wallet':
245:         return <Wallet />;
246:       case 'notifications':
247:         return <Notifications />;
248:       case 'account':
249:         return <Account />;
250:       case 'status':
251:         return <ApplicationStatus onBack={() => go('dashboard')} onEnter={() => go('dashboard')} />;
252:       case 'forgot':
253:         return <ForgotPassword onBack={() => go('dashboard')} onGoReset={() => go('reset')} />;
254:       case 'reset':
255:         return <ResetPassword onBack={() => go('dashboard')} onForgot={() => go('forgot')} />;
256:       default:
257:         return <Dashboard />;
258:     }
259:   };
260: 
261:   const isAuthScreen = ['status', 'forgot', 'reset'].includes(route.screen);
262: 
263:   return (
264:     <AppCtx.Provider value={contextValue}>
265:       <div className="wholesale-portal-app" dir="rtl">
266:         {/* Sticky Header */}
267:         <header className="wp-header">
268:           <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
269:             <button className="wp-logo" onClick={() => go('dashboard')}>
270:               <span>{brandName}</span>
271:               <span className="wp-logo-tag">WHOLESALE</span>
272:             </button>
273:           </div>
274: 
275:           <div className="wp-head-right">
276:             <div className="wp-credit-chip" title="الحد الائتماني والمتاح">
277:               <span>الرصيد المتاح:</span>
278:               <strong className="num">{fmt(ACCOUNT.available_credit, 0)} EGP</strong>
279:             </div>
280: 
281:             <button
282:               className="wp-icon-btn"
283:               onClick={() => go('notifications')}
284:               title="الإشعارات"
285:             >
286:               <i className="fa-regular fa-bell" />
287:               {unreadNotifsCount > 0 && <span className="wp-count">{unreadNotifsCount}</span>}
288:             </button>
289: 
290:             <button
291:               className="wp-icon-btn"
292:               onClick={() => go('cart')}
293:               title="سلة المشتريات"
294:             >
295:               <i className="fa-solid fa-bag-shopping" />
296:               {cartTotalQty > 0 && <span className="wp-count">{cartTotalQty}</span>}
297:             </button>
298: 
299:             <button
300:               className="wp-avatar"
301:               onClick={() => go('account')}
302:               title="الملف التجاري"
303:             >
304:               {ACCOUNT.name.split(' ').map((s) => s[0]).slice(0, 2).join('')}
305:             </button>
306:           </div>
307:         </header>
308: 
309:         {/* Auth full page or standard layout */}
310:         {isAuthScreen ? (
311:           <div className="wp-main" style={{ padding: 0 }}>
312:             {renderScreen()}
313:           </div>
314:         ) : (
315:           <div className="wp-layout">
316:             {/* Sidebar */}
317:             <aside className="wp-side">
318:               <div className="wp-side-tag">B2B PORTAL</div>
319: 
320:               {NAV_GROUPS.map((group) => (
321:                 <div key={group.title} className="wp-side-group">
322:                   <div className="wp-side-group-title">{group.title}</div>
323:                   {group.items.map((item) => {
324:                     const isActive =
325:                       route.screen === item.id ||
326:                       (item.id === 'orders' && route.screen === 'order') ||
327:                       (item.id === 'quotes' && ['quote', 'quoteNew', 'quoteEdit'].includes(route.screen)) ||
328:                       (item.id === 'returns' && ['return', 'returnNew'].includes(route.screen)) ||
329:                       (item.id === 'notices' && ['notice', 'noticeNew'].includes(route.screen));
330:                     const badgeVal =
331:                       item.badge === 'cart' && cartTotalQty > 0
332:                         ? cartTotalQty
333:                         : item.badge === 'notifs' && unreadNotifsCount > 0
334:                         ? unreadNotifsCount
335:                         : null;
336: 
337:                     return (
338:                       <button
339:                         key={item.id}
340:                         className={`wp-side-link ${isActive ? 'is-active' : ''}`}
341:                         onClick={() => go(item.id)}
342:                       >
343:                         <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
344:                           <span className="wp-side-dot" />
345:                           <i
346:                             className={`fa-solid ${item.icon}`}
347:                             style={{ width: 18, textAlign: 'center', fontSize: 13 }}
348:                           />
349:                           <span>{item.label}</span>
350:                         </div>
351:                         {badgeVal && <span className="wp-side-badge num">{badgeVal}</span>}
352:                       </button>
353:                     );
354:                   })}
355:                 </div>
356:               ))}
357: 
358:               <div className="wp-side-foot">
359:                 <button
360:                   className="wp-side-link"
361:                   onClick={logout}
362:                   style={{ color: '#be123c' }}
363:                 >
364:                   <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
365:                     <i
366:                       className="fa-solid fa-arrow-right-from-bracket"
367:                       style={{ width: 18, textAlign: 'center' }}
368:                     />
369:                     <span>تسجيل الخروج</span>
370:                   </div>
371:                 </button>
372:               </div>
373:             </aside>
374: 
375:             {/* Main Content Area */}
376:             <main className="wp-main">
377:               <div className="wp-wrap">
378:                 {renderScreen()}
379:               </div>
380:             </main>
381:           </div>
382:         )}
383: 
384:         {/* Floating Toasts */}
385:         {toasts.length > 0 && (
386:           <div
387:             style={{
388:               position: 'fixed',
389:               bottom: 24,
390:               left: '50%',
391:               transform: 'translateX(-50%)',
392:               zIndex: 9999,
393:               display: 'flex',
394:               flexDirection: 'column',
395:               gap: 8,
396:             }}
397:           >
398:             {toasts.map((t) => (
399:               <div
400:                 key={t.id}
401:                 className="toast"
402:                 style={{ position: 'relative', bottom: 'auto', left: 'auto', transform: 'none' }}
403:               >
404:                 <i className="fa-solid fa-circle-check" />
405:                 <span>{t.msg}</span>
406:               </div>
407:             ))}
408:           </div>
409:         )}
410:       </div>
411:     </AppCtx.Provider>
412:   );
413: }
414: 
