210: /* All authentication forms share the same frame and Birkin artwork. */
211: .luxury-auth-fields { display: flex; flex-direction: column; gap: 20px; min-width: 0; border: 0; margin: 0; padding: 0; }
212: .luxury-auth-fields:disabled { opacity: .7; }
213: .luxury-switch-link { border: 0; padding: 0; background: transparent; cursor: pointer; }
214: .luxury-switch-link:disabled, .luxury-inline-action:disabled { cursor: wait; opacity: .6; }
215: .luxury-field-hint { margin: 8px 0 12px; color: #666; font-size: 12px; line-height: 1.8; }
216: .luxury-inline-action { display: inline-block; border: 0; background: transparent; padding: 8px 0; color: #262626; font-family: var(--auth-sans); font-size: 12px; text-decoration: underline; text-underline-offset: 4px; cursor: pointer; }
217: .luxury-phone-verification { display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: end; gap: 12px; margin-top: 10px; }
218: .luxury-secondary-button { min-height: 44px; padding: 10px 16px; border: 1px solid #d4d4d4; border-radius: 999px; background: #fff; color: #262626; font-family: var(--auth-sans); font-size: 13px; cursor: pointer; }
219: .luxury-secondary-button:hover { background: #fafafa; border-color: #737373; }
220: .luxury-secondary-button:disabled { cursor: wait; opacity: .6; }
