293: .as-block-title { white-space: nowrap; }  1: /* Screens 4–5 — share the luxury-auth split frame (luxuryAuth.css). */
  2: 
  3: const Halftone = () => {
  4:   const ref = useRef(null);
  5:   useEffect(() => {
  6:     const W = 560, H = 640, c = ref.current, ctx = c.getContext('2d');
  7:     const off = document.createElement('canvas'); off.width = W; off.height = H;
  8:     const o = off.getContext('2d');
  9:     // Stand-in silhouette (real build uses BIRKIN_IMG_DATA)
 10:     o.fillStyle = '#fff'; o.fillRect(0, 0, W, H);
 11:     const g = o.createRadialGradient(250, 360, 40, 280, 400, 260);
 12:     g.addColorStop(0, '#222'); g.addColorStop(1, '#bbb');
 13:     o.fillStyle = g;
 14:     o.beginPath(); o.moveTo(110, 270); o.lineTo(450, 270); o.lineTo(490, 520); o.quadraticCurveTo(490, 540, 470, 540); o.lineTo(90, 540); o.quadraticCurveTo(70, 540, 70, 520); o.closePath(); o.fill();
 15:     o.lineWidth = 26; o.strokeStyle = '#444'; o.beginPath(); o.moveTo(190, 275); o.bezierCurveTo(190, 150, 370, 150, 370, 275); o.stroke();
 16:     o.fillStyle = '#eee'; o.fillRect(250, 330, 60, 34);
 17:     const px = o.getImageData(0, 0, W, H).data;
 18:     let mouse = { x: -999, y: -999 };
 19:     const draw = () => {
 20:       ctx.fillStyle = '#fff'; ctx.fillRect(0, 0, W, H); ctx.fillStyle = '#09090b';
 21:       const s = 7, h = s / 2;
 22:       for (let y = h; y < H; y += s) for (let x = h; x < W; x += s) {
 23:         const i = ((y | 0) * W + (x | 0)) * 4, dark = 1 - px[i] / 255;
 24:         if (dark < 0.06) continue;
 25:         const dx = x - mouse.x, dy = y - mouse.y, d = Math.hypot(dx, dy);
 26:         let X = x, Y = y, k = 1;
 27:         if (d < 110) { const f = 1 - d / 110; X += dx / (d + 1) * f * 2.2; Y += dy / (d + 1) * f * 2.2; k = 1 + f * .16; }
 28:         const r = Math.pow(dark, .92) * s * .68 * k; if (r < .45) continue;
 29:         ctx.beginPath(); ctx.moveTo(X, Y - r); ctx.lineTo(X + r, Y); ctx.lineTo(X, Y + r); ctx.lineTo(X - r, Y); ctx.fill();
 30:       }
 31:     };
 32:     draw();
 33:     const mv = (e) => { const b = c.getBoundingClientRect(); mouse = { x: (e.clientX - b.left) / b.width * W, y: (e.clientY - b.top) / b.height * H }; requestAnimationFrame(draw); };
 34:     const lv = () => { mouse = { x: -999, y: -999 }; requestAnimationFrame(draw); };
 35:     c.addEventListener('pointermove', mv); c.addEventListener('pointerleave', lv);
 36:     return () => { c.removeEventListener('pointermove', mv); c.removeEventListener('pointerleave', lv); };
 37:   }, []);
 38:   return <canvas ref={ref} width="560" height="640" aria-hidden="true" />;
 39: };
