 59: /* ---------- 4. Application status ---------- */
 60: const ApplicationStatus = ({ status, onRefresh, onLogout, onEnter }) => {
 61:   const s = APP_STATUS[status];
 62:   const [refreshing, setRefreshing] = useState(false);
 63:   const { state, retry } = React.useContext(DataStateCtx);
 64:   const refresh = () => { setRefreshing(true); setTimeout(() => { setRefreshing(false); onRefresh && onRefresh(); }, 900); };
 65:   const reason = status === 'rejected' ? 'البطاقة الضريبية المرفقة غير واضحة، والسجل التجاري منتهي الصلاحية.'
 66:     : status === 'suspended' ? 'تم إيقاف الحساب مؤقتًا لتجاوز مدة السداد المتفق عليها. تواصل مع إدارة الحسابات.' : null;
 67: 
 68:   return (
 69:     <AuthFrame wide>
 70:       <h1 className="luxury-title">حالة طلب الاعتماد</h1>
 71:       <p className="luxury-sub">نراجع بيانات شركتك ومستنداتها قبل تفعيل أسعار الجملة والشراء الآجل وعروض الأسعار.</p>
 72: 
 73:       {state === 'loading' ? (
 74:         <div className="luxury-auth-fields">{[80, 60, 90, 70].map((w, i) => <div key={i} className="sk" style={{ height: 14, width: w + '%' }} />)}</div>
 75:       ) : state === 'error' ? (
 76:         <div className="luxury-auth-fields">
 77:           <p className="luxury-form-error" role="alert">تعذر تحميل حالة الطلب. حاول مرة أخرى.</p>
 78:           <button className="pill-btn-primary" onClick={retry}>إعادة المحاولة</button>
 79:         </div>
 80:       ) : (
 81:         <div className="luxury-auth-fields">
 82:           <div className="as-status" data-s={status}>
 83:             <div className="as-status-ic"><i className={`fa-solid ${s.icon}`} /></div>
 84:             <div style={{ flex: 1, minWidth: 0 }}>
 85:               <div className="luxury-field-label" style={{ margin: 0, color: '#737373', fontWeight: 400 }}>حالة الحساب</div>
 86:               <div className="as-status-label">{s.label}</div>
 87:             </div>
 88:             {status === 'approved' && <div className="as-date"><span>تاريخ الاعتماد</span><b className="num">{ACCOUNT.approved_at}</b></div>}
 89:           </div>
 90: 
 91:           {reason && <p className="luxury-form-error" role="alert"><b>{status === 'rejected' ? 'سبب الرفض: ' : 'سبب الإيقاف: '}</b>{reason}</p>}
 92:           {status === 'pending' && <p className="luxury-success">المراجعة عادةً تستغرق من يوم إلى يومي عمل. هيوصلك إشعار بمجرد تغيير الحالة.</p>}
 93: 
 94:           <div className="as-block">
 95:             <div className="as-block-title">بيانات الحساب والشركة</div>
 96:             <dl className="as-kv">
 97:               <dt>اسم التاجر</dt><dd>{ACCOUNT.name}</dd>
 98:               <dt>الموبايل</dt><dd className="num">{ACCOUNT.phone}</dd>
 99:               <dt>البريد</dt><dd className="num">{ACCOUNT.email}</dd>
100:               <dt>الشركة</dt><dd>{ACCOUNT.company}</dd>
101:               <dt>الرقم الضريبي</dt><dd className="num">{ACCOUNT.tax_number}</dd>
102:               <dt>السجل التجاري</dt><dd>{ACCOUNT.commercial_register}</dd>
103:             </dl>
104:           </div>
105: 
106:           <div className="as-block">
107:             <div className="as-block-title">المستندات <span className="num" style={{ color: '#a3a3a3' }}>{DOCS.length}</span></div>
108:             <ul className="luxury-file-list as-docs">
109:               {DOCS.map((d) => {
110:                 const [l, v] = DOC_STATUS[status === 'approved' ? 'approved' : d.status];
111:                 const rej = status !== 'approved' && d.status === 'rejected';
112:                 return (
113:                   <li key={d.name} className={rej ? 'is-rej' : ''}>
114:                     <span>
115:                       <i className={`fa-regular ${d.name.endsWith('.pdf') ? 'fa-file-pdf' : 'fa-file-image'}`} />
116:                       <span><b>{d.type}</b><small className="num">{d.name}</small>{rej && d.note && <em>{d.note}</em>}</span>
117:                     </span>
118:                     <span className={`badge ${v}`}>{l}</span>
119:                   </li>
120:                 );
121:               })}
122:             </ul>
123:             {(status === 'rejected' || DOCS.some((d) => d.status === 'rejected')) && status !== 'approved' && (
124:               <p className="luxury-field-hint" style={{ marginBottom: 0 }}><i className="fa-solid fa-circle-info" /> إعادة رفع المستندات غير متاحة من البوابة حاليًا — تواصل مع فريق المبيعات لاستكمالها.</p>
125:             )}
126:           </div>
127: 
128:           {status === 'approved'
129:             ? <button className="pill-btn-primary" onClick={onEnter}>الدخول إلى بوابة الجملة</button>
130:             : <button className="pill-btn-primary" onClick={refresh} disabled={refreshing}>{refreshing ? <><span className="spin" style={{ marginInlineEnd: 10 }} /> جارٍ التحديث…</> : 'تحديث حالة الطلب'}</button>}
131:           <div className="luxury-bottom-switch" style={{ marginTop: 4 }}>
132:             <button className="luxury-switch-link" onClick={onLogout}>تسجيل الخروج</button>
133:           </div>
134:         </div>
135:       )}
136:     </AuthFrame>
137:   );
138: };
