140: /* ---------- 5. Forgot / reset password ---------- */
141: const ForgotPassword = ({ onBack, onGoReset }) => {
142:   const [login, setLogin] = useState('');
143:   const [sent, setSent] = useState(false);
144:   const [busy, setBusy] = useState(false);
145:   const [err, setErr] = useState('');
146:   const submit = (e) => {
147:     e.preventDefault();
148:     if (!login.trim()) { setErr('أدخل البريد الإلكتروني أو رقم الموبايل.'); return; }
149:     setErr(''); setBusy(true); setTimeout(() => { setBusy(false); setSent(true); }, 900);
150:   };
151:   return (
152:     <AuthFrame>
153:       <h1 className="luxury-title">نسيت كلمة المرور؟</h1>
154:       <p className="luxury-sub">أدخل البريد أو رقم الموبايل المسجل، وهنبعتلك رابط لإعادة تعيين كلمة المرور.</p>
155:       {sent ? (
156:         <div className="luxury-auth-fields">
157:           <p className="luxury-success" role="status"><b>تم إرسال الطلب.</b><br />لو الحساب موجود، هيوصلك رابط إعادة التعيين على <span className="num">{login}</span> خلال دقائق. الرابط صالح لمدة 60 دقيقة.</p>
158:           <button className="pill-btn-primary" onClick={onGoReset}>عندي الرابط — إعادة التعيين</button>
159:           <div className="luxury-bottom-switch"><button className="luxury-switch-link" onClick={() => setSent(false)}>إعادة الإرسال</button><span className="luxury-link-sep">·</span><button className="luxury-switch-link" onClick={onBack}>العودة لتسجيل الدخول</button></div>
160:         </div>
161:       ) : (
162:         <form className="luxury-form" onSubmit={submit} noValidate>
163:           <div>
164:             <label className="luxury-field-label" htmlFor="fp">البريد الإلكتروني أو رقم الموبايل<span className="luxury-req-mark">*</span></label>
165:             <input id="fp" className="pill-input" dir="ltr" value={login} onChange={(e) => setLogin(e.target.value)} placeholder="name@company.com / 01xxxxxxxxx" aria-invalid={!!err} />
166:             {err && <p className="luxury-field-error" role="alert">{err}</p>}
167:           </div>
168:           <button className="pill-btn-primary" disabled={busy}>{busy ? 'جارٍ الإرسال…' : 'إرسال رابط إعادة التعيين'}</button>
169:           <div className="luxury-bottom-switch"><button type="button" className="luxury-switch-link" onClick={onBack}>العودة لتسجيل الدخول</button></div>
170:         </form>
171:       )}
172:     </AuthFrame>
173:   );
174: };
