176: const ResetPassword = ({ onBack, linkState = 'valid', onForgot }) => {
177:   const [show, setShow] = useState(false);
178:   const [p1, setP1] = useState(''); const [p2, setP2] = useState('');
179:   const [errs, setErrs] = useState({});
180:   const [done, setDone] = useState(false);
181:   const submit = (e) => {
182:     e.preventDefault();
183:     const er = {};
184:     if (p1.length < 8) er.p1 = 'كلمة المرور لازم تكون 8 حروف على الأقل.';
185:     if (p1 !== p2) er.p2 = 'تأكيد كلمة المرور غير مطابق.';
186:     setErrs(er); if (!Object.keys(er).length) setDone(true);
187:   };
188:   const rules = [[p1.length >= 8, '8 حروف على الأقل'], [/[A-Za-z]/.test(p1) && /\d/.test(p1), 'حروف وأرقام'], [p1 && p1 === p2, 'التأكيد مطابق']];
189:   if (linkState !== 'valid') return (
190:     <AuthFrame>
191:       <h1 className="luxury-title">{linkState === 'expired' ? 'انتهت صلاحية الرابط' : 'الرابط غير صالح'}</h1>
192:       <p className="luxury-sub">{linkState === 'expired' ? 'روابط إعادة التعيين صالحة لمدة 60 دقيقة فقط. اطلب رابط جديد.' : 'الرابط ده مستخدم قبل كده أو ناقص. اطلب رابط جديد من صفحة استعادة كلمة المرور.'}</p>
193:       <p className="luxury-form-error" role="alert">لا يمكن إعادة تعيين كلمة المرور بهذا الرابط.</p>
194:       <button className="pill-btn-primary" style={{ marginTop: 22 }} onClick={onForgot}>طلب رابط جديد</button>
195:       <div className="luxury-bottom-switch"><button className="luxury-switch-link" onClick={onBack}>العودة لتسجيل الدخول</button></div>
196:     </AuthFrame>
197:   );
198:   return (
199:     <AuthFrame>
200:       <h1 className="luxury-title">{done ? 'تم تغيير كلمة المرور' : 'إعادة تعيين كلمة المرور'}</h1>
201:       <p className="luxury-sub">{done ? 'تقدر دلوقتي تسجل الدخول بكلمة المرور الجديدة.' : 'اختر كلمة مرور جديدة لحسابك.'}</p>
202:       {done ? (
203:         <div className="luxury-auth-fields">
204:           <p className="luxury-success" role="status"><span className="luxury-verified-badge">تم التحديث بنجاح</span></p>
205:           <button className="pill-btn-primary" onClick={onBack}>تسجيل الدخول</button>
206:         </div>
207:       ) : (
208:         <form className="luxury-form" onSubmit={submit} noValidate>
209:           <div>
210:             <label className="luxury-field-label">البريد الإلكتروني</label>
211:             <input className="pill-input" dir="ltr" value={ACCOUNT.email} readOnly style={{ background: '#fafafa', color: '#737373' }} />
212:           </div>
213:           {[['p1', 'كلمة المرور الجديدة', p1, setP1], ['p2', 'تأكيد كلمة المرور', p2, setP2]].map(([k, l, v, set]) => (
214:             <div key={k}>
215:               <label className="luxury-field-label">{l}<span className="luxury-req-mark">*</span></label>
216:               <div className="luxury-pwd-wrap">
217:                 <input className="pill-input" style={{ paddingLeft: 52 }} type={show ? 'text' : 'password'} value={v} onChange={(e) => set(e.target.value)} aria-invalid={!!errs[k]} />
218:                 <button type="button" className="luxury-eye-btn" style={{ right: 'auto', left: 8 }} onClick={() => setShow(!show)} aria-label="إظهار كلمة المرور"><i className={`fa-regular ${show ? 'fa-eye-slash' : 'fa-eye'}`} /></button>
219:               </div>
220:               {errs[k] && <p className="luxury-field-error" role="alert">{errs[k]}</p>}
221:             </div>
222:           ))}
223:           <ul className="as-rules">{rules.map(([ok, l]) => <li key={l} className={ok ? 'ok' : ''}><i className={`fa-solid ${ok ? 'fa-check' : 'fa-circle'}`} />{l}</li>)}</ul>
224:           <button className="pill-btn-primary">حفظ كلمة المرور</button>
225:           <div className="luxury-bottom-switch"><button type="button" className="luxury-switch-link" onClick={onBack}>العودة لتسجيل الدخول</button></div>
226:         </form>
227:       )}
228:     </AuthFrame>
229:   );
230: };
