115:                   <td>{v.tiers.map(([m, pr]) => <span key={m} className="tier"><span className="num">{m}+</span> ← <b className="num">{fmt(pr, 0)}</b></span>)}</td>
116:                   <td>{stock === 0 ? <span className="badge danger">نفدت الكمية</span> : <span className={`num ${stock < 50 ? '' : 'strong'}`} style={stock < 50 ? { color: '#b45309', fontWeight: 600 } : null}>{stock}</span>}</td>
117:                   <td className="t-end"><button className="btn-pill is-dark sm" onClick={() => setOpen(p)}>اختيار الكمية</button></td>
