130: const tierPrice = (v, qty) => { let p = v.price; v.tiers.forEach(([m, pr]) => { if (qty >= m) p = pr; }); return p; };
131: 
132: const VariantModal = ({ product, onClose, onAdd }) => {
133:   const [qty, setQty] = useState(Object.fromEntries(product.variants.map((v) => [v.id, 0])));
134:   const lines = product.variants.filter((v) => qty[v.id] > 0).map((v) => ({ v: { ...v, product }, qty: qty[v.id] }));
135:   const total = lines.reduce((a, l) => a + tierPrice(l.v, l.qty) * l.qty, 0);
136:   const over = product.variants.some((v) => qty[v.id] > v.qty);
137:   return (
138:     <Modal wide title={product.name_ar} onClose={onClose} icon={<Thumb sm />}
139:       foot={<><span className="muted small" style={{ marginInlineEnd: 'auto' }}>تقديري: <Money v={total} strong /></span>
140:         <button className="btn-pill" onClick={onClose}>إلغاء</button>
141:         <button className="btn-pill is-dark" disabled={!lines.length || over} onClick={() => onAdd(lines)}><i className="fa-solid fa-cart-plus" /> إضافة للسلة {lines.length > 0 && <span className="num">({lines.reduce((a, l) => a + l.qty, 0)})</span>}</button></>}>
142:       <p className="prod-en" style={{ textAlign: 'right', marginTop: -10 }}>{product.name_en} · السعر الأساسي <span className="strike">{fmt(product.base)}</span></p>
143:       <div className="tbl-wrap mt-16"><table className="tbl">
144:         <thead><tr><th>المتغير</th><th>SKU / باركود</th><th>سعرك</th><th>الشرائح</th><th>المتاح</th><th>الكمية</th></tr></thead>
145:         <tbody>{product.variants.map((v) => {
146:           const q = qty[v.id]; const bad = q > v.qty;
147:           return (
148:             <tr key={v.id} className={bad ? 'is-error' : ''}>
149:               <td className="strong">{v.label}</td>
150:               <td><div className="sku">{v.sku}</div><div className="sku soft">{v.barcode}</div></td>
151:               <td className="strong num">{fmt(q ? tierPrice(v, q) : v.price)}</td>
152:               <td>{v.tiers.map(([m, pr]) => <span key={m} className="tier" style={q >= m ? { background: 'var(--accent)', color: '#fff', borderColor: 'var(--accent)' } : null}><span className="num">{m}+</span> <b className="num">{fmt(pr, 0)}</b></span>)}</td>
153:               <td className="num">{v.qty === 0 ? <span className="badge danger">نفدت</span> : v.qty}</td>
154:               <td>{v.qty === 0 ? <span className="soft small">غير متاح</span> : <><Qty value={q} onChange={(n) => setQty({ ...qty, [v.id]: n })} />{bad && <p className="f-error">المتاح <span className="num">{v.qty}</span> فقط</p>}</>}</td>
155:             </tr>);
156:         })}</tbody>
157:       </table></div>
158:     </Modal>
159:   );
160: };
