162: /* ---------- 8–9. Quick order + Excel import ---------- */
163: const QuickOrder = () => {
164:   const { addToCart, go, toast } = useApp();
165:   const [tab, setTab] = useState('manual');
166:   const blank = () => ({ code: '', qty: '' });
167:   const [rows, setRows] = useState([{ code: 'SPH-TT-001-BLK', qty: '24' }, { code: '6224001014011', qty: '40' }, { code: 'SPH-BP-007-GRY-M', qty: '30' }, { code: 'SPH-XX-999', qty: '10' }, { code: 'SPH-TT-001-CRM', qty: '12' }, blank()]);
168:   const [looked, setLooked] = useState(false);
169:   const [busy, setBusy] = useState(false);
170:   const set = (i, k, v) => { const r = [...rows]; r[i] = { ...r[i], [k]: v }; if (i === rows.length - 1 && v) r.push(blank()); setRows(r); setLooked(false); };
171:   const res = rows.map((r) => {
172:     if (!r.code.trim()) return null;
173:     const v = findVariant(r.code); const q = parseInt(r.qty || '0', 10);
174:     if (!v) return { err: 'الصنف غير موجود' };
175:     if (!q) return { v, err: 'أدخل الكمية' };
176:     if (v.qty === 0) return { v, q, err: 'نفدت الكمية' };
177:     if (q > v.qty) return { v, q, warn: `المتاح ${v.qty} فقط` };
178:     const unit = tierPrice(v, q);
179:     return { v, q, unit, total: unit * q, ok: true };
180:   });
181:   const valid = res.filter((x) => x && x.ok);
182:   const known = res.filter((x) => x && x.v && x.unit);
183:   const lookup = () => { setBusy(true); setTimeout(() => { setBusy(false); setLooked(true); }, 700); };
184:   return (
185:     <>
186:       <PageHead en="Quick Order" ar="أدخل الأكواد والكميات مباشرة، أو ارفع ملف Excel">
187:         <Seg value={tab} onChange={setTab} options={[{ value: 'manual', label: 'إدخال مباشر', icon: 'fa-keyboard' }, { value: 'import', label: 'استيراد ملف', icon: 'fa-file-arrow-up' }]} />
188:       </PageHead>
189:       {tab === 'manual' ? (
190:         <div className="grid-2" style={{ gridTemplateColumns: '1fr 320px' }}>
191:           <section className="panel">
192:             <div className="toolbar">
193:               <span className="muted small">الصق من Excel مباشرة: عمود SKU أو باركود، ثم الكمية. حتى <span className="num">500</span> بند.</span>
194:               <button className="btn-link muted" onClick={() => { setRows([blank()]); setLooked(false); }}>مسح الكل</button>
195:             </div>
196:             <div className="tbl-wrap"><table className="tbl qo-tbl">
197:               <thead><tr><th style={{ width: 36 }}>#</th><th style={{ width: 210 }}>SKU أو باركود</th><th style={{ width: 96 }}>الكمية</th><th>الصنف</th><th>سعر الوحدة</th><th className="t-end">الإجمالي</th><th></th></tr></thead>
198:               <tbody>{rows.map((r, i) => {
199:                 const x = looked ? res[i] : null;
200:                 return (
201:                   <tr key={i} className={x && x.err ? 'is-error' : x && x.warn ? 'is-warn' : ''}>
202:                     <td className="soft num">{i + 1}</td>
203:                     <td><input className={`box-input ltr${x && x.err && !x.v ? ' is-invalid' : ''}`} value={r.code} placeholder="SPH-…" onChange={(e) => set(i, 'code', e.target.value)} /></td>
204:                     <td><input className={`box-input ltr${x && x.err === 'أدخل الكمية' ? ' is-invalid' : ''}`} value={r.qty} inputMode="numeric" onChange={(e) => set(i, 'qty', e.target.value.replace(/\D/g, ''))} /></td>
205:                     <td>{!x ? <span className="soft small">{r.code ? 'اضغط «فحص البنود»' : ''}</span> : x.v ? <><div className="strong small">{x.v.product.name_ar} — {x.v.label}</div>{x.err ? <p className="f-error" style={{ margin: 0 }}><i className="fa-solid fa-circle-exclamation" />{x.err}</p> : x.warn ? <p className="f-error" style={{ margin: 0, color: '#b45309' }}><i className="fa-solid fa-triangle-exclamation" />{x.warn}</p> : <span className="small" style={{ color: '#047857' }}><i className="fa-solid fa-check" /> متاح</span>}</> : <p className="f-error" style={{ margin: 0 }}><i className="fa-solid fa-circle-xmark" />{x.err}</p>}</td>
206:                     <td className="num">{x && x.unit ? fmt(x.unit) : '—'}</td>
207:                     <td className="t-end strong num">{x && x.total ? fmt(x.total) : '—'}</td>
208:                     <td>{r.code && <button className="btn-link muted" aria-label="حذف" onClick={() => setRows(rows.filter((_, j) => j !== i))}><i className="fa-solid fa-xmark" /></button>}</td>
209:                   </tr>);
210:               })}</tbody>
211:             </table></div>
212:           </section>
213:           <aside className="panel" style={{ position: 'sticky', top: 100 }}>
214:             <div className="panel-body">
215:               <h2 className="panel-title">ملخص الفحص</h2>
216:               <div className="mt-16">
217:                 <div className="sum-row"><span>إجمالي البنود</span><strong className="num">{rows.filter((r) => r.code).length}</strong></div>
218:                 <div className="sum-row"><span>بنود معروفة</span><strong className="num">{looked ? known.length : '—'}</strong></div>
219:                 <div className="sum-row"><span>بنود صالحة للإضافة</span><strong className="num" style={{ color: 'var(--accent)' }}>{looked ? valid.length : '—'}</strong></div>
220:                 <div className="sum-row"><span>بنود بها أخطاء</span><strong className="num" style={{ color: '#b91c1c' }}>{looked ? res.filter((x) => x && !x.ok).length : '—'}</strong></div>
221:                 <div className="sum-total"><span>قيمة البنود الصالحة</span><span className="num">{looked ? fmt(valid.reduce((a, x) => a + x.total, 0)) : '—'}</span></div>
222:               </div>
223:               <button className="btn-block mt-24" onClick={lookup} disabled={busy}>{busy ? <span className="spin" /> : <i className="fa-solid fa-magnifying-glass" />} فحص البنود</button>
224:               <button className="btn-pill is-dark mt-8" style={{ width: '100%', justifyContent: 'center' }} disabled={!looked || !valid.length} onClick={() => addToCart(valid.map((x) => ({ v: x.v, qty: x.q })))}><i className="fa-solid fa-cart-plus" /> إضافة <span className="num">{valid.length}</span> بند صالح للسلة</button>
225:               <p className="note mt-16"><i className="fa-solid fa-circle-info" />الفحص للمعاينة فقط؛ الأسعار النهائية بتتأكد في السلة.</p>
226:             </div>
227:           </aside>
228:         </div>
229:       ) : <ImportTab />}
230:     </>
231:   );
232: };
