234: const ImportTab = () => {
235:   const { go } = useApp();
236:   const [stage, setStage] = useState('idle'); // idle | invalid | uploading | done
237:   const [file, setFile] = useState(null);
238:   const pick = (bad) => { if (bad) { setFile({ name: 'big-order-oct.xlsx', size: '7.4 MB' }); setStage('invalid'); return; } setFile({ name: 'order-nov-week1.xlsx', size: '38 KB' }); setStage('ready'); };
239:   const upload = () => { setStage('uploading'); setTimeout(() => setStage('done'), 1300); };
240:   const skipped = [['SPH-XX-999', 10, 'الصنف غير موجود'], ['SPH-TT-001-CRM', 12, 'نفدت الكمية'], ['SPH-BP-007-GRY-M', 30, 'الكمية أكبر من المتاح (18)'], ['—', 0, 'صف 14: الكمية غير صالحة']];
241:   return (
242:     <div className="grid-2" style={{ gridTemplateColumns: '1fr 340px' }}>
243:       <section className="panel"><div className="panel-body">
244:         {stage !== 'done' ? (
245:           <>
246:             <div className={`drop${stage === 'invalid' ? ' is-invalid' : ''}`} onClick={() => pick(false)}>
247:               <i className="fa-solid fa-file-arrow-up" />
248:               <b>اسحب الملف هنا أو اضغط للاختيار</b>
249:               <small>XLSX · XLS · CSV · TXT — حتى <span className="num">5</span> ميجابايت</small>
250:             </div>
251:             {file && (
252:               <div className="file-row mt-16">
253:                 <i className="fa-regular fa-file-excel" />
254:                 <div className="grow"><b className="num">{file.name}</b> <span className="soft num">· {file.size}</span></div>
255:                 <button className="btn-link muted" onClick={() => { setFile(null); setStage('idle'); }}><i className="fa-solid fa-xmark" /></button>
256:               </div>
257:             )}
258:             {stage === 'invalid' && <p className="f-error"><i className="fa-solid fa-circle-exclamation" />حجم الملف أكبر من 5 ميجابايت. قسّم الملف وحاول تاني.</p>}
259:             <Banner kind="warn" ><b>الاستيراد بيضيف البنود للسلة مباشرة</b> — مش معاينة. البنود اللي فيها مشاكل هتتخطى وهيظهرلك سببها.</Banner>
260:             <div className="row mt-16" style={{ justifyContent: 'space-between' }}>
261:               <button className="btn-link muted" onClick={() => pick(true)}>جرب ملف كبير (حالة خطأ)</button>
262:               <button className="btn-pill is-dark" disabled={stage !== 'ready'} onClick={upload}>{stage === 'uploading' ? <><span className="spin" /> جارٍ الاستيراد…</> : <><i className="fa-solid fa-upload" /> استيراد وإضافة للسلة</>}</button>
263:             </div>
264:           </>
265:         ) : (
266:           <>
267:             <div className="row" style={{ gap: 16 }}>
268:               <div className="modal-icon"><i className="fa-solid fa-check" /></div>
269:               <div><h2 className="panel-title">تم الاستيراد</h2><p className="muted small" style={{ margin: '4px 0 0' }}><span className="num">{file.name}</span></p></div>
270:             </div>
271:             <div className="imp-stats mt-24">
272:               <div><span className="num">38</span><small>بند تمت إضافته</small></div>
273:               <div className="is-warn"><span className="num">4</span><small>بند تم تخطيه</small></div>
274:             </div>
275:             <h3 className="f-label mt-24">البنود المتخطاة وأسبابها</h3>
276:             <table className="tbl"><thead><tr><th>SKU</th><th>الكمية</th><th>السبب</th></tr></thead>
277:               <tbody>{skipped.map(([s, q, r], i) => <tr key={i}><td className="sku">{s}</td><td className="num">{q || '—'}</td><td style={{ color: '#b91c1c' }}>{r}</td></tr>)}</tbody></table>
278:             <div className="row mt-24"><button className="btn-pill is-dark" onClick={() => go('cart')}><i className="fa-solid fa-bag-shopping" /> فتح السلة</button><button className="btn-pill" onClick={() => { setStage('idle'); setFile(null); }}>استيراد ملف آخر</button></div>
279:           </>
280:         )}
281:       </div></section>
282:       <aside className="panel"><div className="panel-body">
283:         <h2 className="panel-title">ترتيب الأعمدة</h2>
284:         <p className="muted small" style={{ lineHeight: 1.8 }}>العمود الأول SKU أو الباركود، والثاني الكمية. صف العناوين اختياري.</p>
285:         <table className="tbl imp-sample ltr"><thead><tr><th>A · sku</th><th>B · qty</th></tr></thead>
286:           <tbody><tr><td className="sku">SPH-TT-001-BLK</td><td className="num">24</td></tr><tr><td className="sku">6224001014011</td><td className="num">40</td></tr><tr><td className="sku">SPH-WL-040-BRG</td><td className="num">120</td></tr></tbody></table>
287:       </div></aside>
288:     </div>
289:   );
290: };
