292: /* ---------- 10. Cart ---------- */
293: const Cart = () => {
294:   const { cart, setCart, go } = useApp();
295:   const [coupon, setCoupon] = useState('');
296:   const [applied, setApplied] = useState(null);
297:   const [cErr, setCErr] = useState('');
298:   const [confirmClear, setConfirmClear] = useState(false);
299:   const lines = cart.map((l) => ({ ...l, unit: tierPrice(l.v, l.qty), total: tierPrice(l.v, l.qty) * l.qty }));
300:   const sub = lines.reduce((a, l) => a + l.total, 0);
301:   const disc = applied ? Math.round(sub * 0.03) : 0;
302:   const upd = (i, q) => setCart(cart.map((l, j) => j === i ? { ...l, qty: q } : l).filter((l) => l.qty > 0));
303:   const apply = () => { if (coupon.trim().toUpperCase() === 'WS3') { setApplied('WS3'); setCErr(''); } else setCErr('الكوبون غير صالح أو غير مقبول لطلبات الجملة.'); };
304:   const changed = lines.find((l) => l.v.sku === 'SPH-BP-007-NVY-L');
305:   const short = lines.find((l) => l.qty > l.v.qty);
306:   if (!cart.length) return (<><PageHead en="Your Bag" ar="سلة المشتريات" /><section className="panel"><Empty icon="fa-bag-shopping" title="السلة فاضية" desc="ضيف منتجات من الكتالوج أو استخدم الطلب السريع." action={<div className="row"><button className="btn-pill is-dark" onClick={() => go('catalog')}>تصفح الكتالوج</button><button className="btn-pill" onClick={() => go('quick')}>طلب سريع</button></div>} /></section></>);
307:   return (
308:     <>
309:       <PageHead en="Your Bag" ar={<>سلة المشتريات · <span className="num">{lines.length}</span> بند</>}>
310:         <button className="btn-pill is-danger" onClick={() => setConfirmClear(true)}><i className="fa-regular fa-trash-can" /> تفريغ السلة</button>
311:       </PageHead>
312:       <div className="stack" style={{ gap: 12, marginBottom: 24 }}>
313:         {changed && <Banner kind="info" icon="fa-tag">تغير سعر <b>{changed.v.product.name_ar}</b> من <span className="num strike">{fmt(910)}</span> إلى <b className="num">{fmt(changed.unit)}</b> منذ إضافته للسلة.</Banner>}
314:         {short && <Banner kind="error">الكمية المطلوبة من <b>{short.v.product.name_ar} — {short.v.label}</b> أكبر من المخزون المتاح (<span className="num">{short.v.qty}</span>). عدّل الكمية للمتابعة.</Banner>}
315:       </div>
316:       <div className="grid-2" style={{ gridTemplateColumns: '1.35fr 1fr', gap: 48 }}>
317:         <section>
318:           {lines.map((l, i) => (
319:             <div key={l.v.id} className={`cart-row${l.qty > l.v.qty ? ' is-bad' : ''}`}>
320:               <Thumb />
321:               <div className="cart-info">
322:                 <div className="prod-name">{l.v.product.name_ar}</div>
323:                 <div className="cart-meta"><span>المتغير</span><b>{l.v.label}</b><span>SKU</span><b className="sku">{l.v.sku}</b><span>سعر الوحدة</span><b className="num">{fmt(l.unit)}{l.unit < l.v.price && <span className="tier" style={{ marginInlineStart: 8 }}>شريحة كمية</span>}</b></div>
324:                 <div className="row mt-8"><Qty value={l.qty} onChange={(q) => upd(i, q)} />{l.qty > l.v.qty && <span className="f-error" style={{ margin: 0 }}>المتاح <span className="num">{l.v.qty}</span></span>}</div>
325:               </div>
326:               <div className="cart-right">
327:                 <span className="strong num">{fmt(l.total)}</span>
328:                 <button className="btn-link muted" onClick={() => upd(i, 0)}>حذف</button>
329:               </div>
330:             </div>
331:           ))}
332:         </section>
333:         <aside style={{ position: 'sticky', top: 100, alignSelf: 'start' }}>
334:           <h2 className="checkout-heading">ملخص الطلب</h2>
335:           <div className="promo">
336:             {applied ? (
337:               <span className="promo-chip">كوبون <b className="num">{applied}</b> مطبق<button onClick={() => setApplied(null)} aria-label="إزالة">✕</button></span>
338:             ) : (<>
339:               <div style={{ flex: 1 }}><input className={`line-input ltr${cErr ? ' is-invalid' : ''}`} placeholder="كود الخصم" value={coupon} onChange={(e) => { setCoupon(e.target.value); setCErr(''); }} />{cErr && <p className="f-error">{cErr}</p>}</div>
340:               <button className="btn-soft" onClick={apply}>تطبيق</button></>)}
341:           </div>
342:           <div className="sum-row"><span>قيمة المنتجات</span><strong className="num">{fmt(sub)}</strong></div>
343:           <div className="sum-row is-neg"><span>الخصم</span><strong className="num">{disc ? '− ' + fmt(disc) : '—'}</strong></div>
344:           <div className="sum-row"><span>الشحن والضريبة</span><span className="soft small">تُحسب في الخطوة التالية</span></div>
345:           <div className="sum-total"><span>الإجمالي المبدئي</span><span className="num">{fmt(sub - disc)}</span></div>
346:           <button className="btn-block mt-24" disabled={!!short} onClick={() => go('checkout')}>متابعة لإتمام الطلب <i className="fa-solid fa-arrow-left" /></button>
347:           <button className="btn-link muted mt-16" onClick={() => go('catalog')}><i className="fa-solid fa-arrow-right" /> كمّل التسوق</button>
348:         </aside>
349:       </div>
350:       {confirmClear && <Modal title="تفريغ السلة؟" onClose={() => setConfirmClear(false)} icon={<div className="modal-icon is-warn"><i className="fa-solid fa-trash-can" /></div>}
351:         foot={<><button className="btn-pill" onClick={() => setConfirmClear(false)}>إلغاء</button><button className="btn-pill is-danger" onClick={() => { setCart([]); setConfirmClear(false); }}>تفريغ</button></>}>
352:         <p className="muted">هيتم حذف كل البنود (<span className="num">{lines.length}</span>) من السلة. الإجراء ده مش ممكن التراجع عنه.</p></Modal>}
353:     </>
354:   );
355: };
