357: /* ---------- 11. Checkout ---------- */
358: const Checkout = () => {
359:   const { cart, go, placeOrder } = useApp();
360:   const [addr, setAddr] = useState(1);
361:   const [f, setF] = useState({ name: ACCOUNT.name, phone: '01004821190', email: '', city: 'القاهرة', address: '14 ش التحرير، الدقي، الجيزة', notes: '' });
362:   const [pay, setPay] = useState('credit');
363:   const [ship, setShip] = useState('standard');
364:   const [errs, setErrs] = useState({});
365:   const [step, setStep] = useState('form'); // form | changed | submitting
366:   const lines = cart.map((l) => ({ ...l, total: tierPrice(l.v, l.qty) * l.qty }));
367:   const sub = lines.reduce((a, l) => a + l.total, 0) || 46200;
368:   const shipping = ship === 'express' ? 650 : 350;
369:   const codFee = pay === 'cod' ? 150 : 0;
370:   const total = sub + shipping + codFee;
371:   const overCredit = pay === 'credit' && total > ACCOUNT.available_credit;
372:   const pickAddr = (a) => { setAddr(a.id); setF({ ...f, city: a.city, address: a.address }); };
373:   const submit = () => {
374:     const e = {};
375:     if (!f.name.trim()) e.name = 'اسم المستلم مطلوب.';
376:     if (!/^01\d{9}$/.test(f.phone)) e.phone = 'رقم موبايل مصري غير صحيح (11 رقم يبدأ بـ 01).';
377:     if (!f.city) e.city = 'اختر المدينة.';
378:     if (!f.address.trim()) e.address = 'العنوان التفصيلي مطلوب.';
379:     setErrs(e); if (Object.keys(e).length) return;
380:     if (step === 'form') { setStep('changed'); return; }
381:     setStep('submitting'); setTimeout(() => placeOrder({ total: total + 120, pay }), 1000);
382:   };
383:   const inp = (k, props = {}) => <input className={`line-input${errs[k] ? ' is-invalid' : ''}`} value={f[k]} onChange={(e) => { setF({ ...f, [k]: e.target.value }); setErrs({ ...errs, [k]: null }); }} {...props} />;
384:   return (
385:     <>
386:       <PageHead en="Checkout" crumb={<Crumb items={[{ label: 'السلة', go: () => go('cart') }, { label: 'إتمام الطلب' }]} />}>
387:         <button className="btn-pill" onClick={() => go('cart')}><i className="fa-solid fa-arrow-right" /> العودة للسلة</button>
388:       </PageHead>
389:       <ol className="steps"><li className="step is-done"><span className="step-dot">✓</span>السلة</li><li className="step is-now"><span className="step-dot">2</span>الشحن والدفع</li><li className="step"><span className="step-dot">3</span>التأكيد</li></ol>
390:       {step === 'changed' && <div className="mb-24"><Banner kind="warn" icon="fa-arrows-rotate"><b>تغير الإجمالي قبل التأكيد.</b> تمت إعادة حساب رسوم الشحن من <span className="num">{fmt(shipping)}</span> إلى <span className="num">{fmt(shipping + 120)}</span> حسب الوزن الفعلي. الإجمالي الجديد <b className="num">{fmt(total + 120)} EGP</b> — راجعه واضغط تأكيد.</Banner></div>}
391:       <div className="grid-2" style={{ gridTemplateColumns: '1.22fr .95fr', gap: 64 }}>
392:         <div>
393:           <fieldset className="ck-block" disabled={step === 'submitting'}>
394:             <h2 className="checkout-heading">عنوان التسليم</h2>
395:             <div className="addr-picks">
396:               {ADDRESSES.map((a) => (
397:                 <button key={a.id} type="button" className={`addr-pick${addr === a.id ? ' is-on' : ''}`} onClick={() => pickAddr(a)}>
398:                   <b>{a.label}{a.default && <span className="badge accent" style={{ marginInlineStart: 8 }}>افتراضي</span>}</b>
399:                   <span>{a.city} — {a.address}</span>
400:                 </button>
401:               ))}
402:               <button type="button" className={`addr-pick${addr === 0 ? ' is-on' : ''}`} onClick={() => { setAddr(0); setF({ ...f, city: '', address: '' }); }}><b>عنوان آخر</b><span>إدخال يدوي لهذا الطلب</span></button>
403:             </div>
404:             <div className="fields mt-24">
405:               <Field label="اسم المستلم" req error={errs.name}>{inp('name')}</Field>
406:               <Field label="تليفون المستلم" req error={errs.phone}>{inp('phone', { dir: 'ltr', inputMode: 'tel', style: { textAlign: 'right' } })}</Field>
407:               <Field label="بريد المستلم" opt error={errs.email}>{inp('email', { dir: 'ltr', placeholder: 'name@company.com', style: { textAlign: 'right' } })}</Field>
408:               <Field label="المدينة" req error={errs.city}>
409:                 <select className={`line-input${errs.city ? ' is-invalid' : ''}`} value={f.city} onChange={(e) => { setF({ ...f, city: e.target.value }); setErrs({ ...errs, city: null }); }}>
410:                   <option value="">اختر المدينة</option>{['القاهرة', 'الجيزة', 'الإسكندرية', 'المنصورة', 'طنطا', 'أسيوط'].map((c) => <option key={c}>{c}</option>)}
411:                 </select></Field>
412:               <Field label="العنوان التفصيلي" req span error={errs.address}>{inp('address', { placeholder: 'الشارع، رقم المبنى، علامة مميزة' })}</Field>
413:               <Field label="ملاحظات الشحن" opt span><textarea className="line-input" rows="2" value={f.notes} placeholder="مواعيد الاستلام، رقم بديل…" onChange={(e) => setF({ ...f, notes: e.target.value })} /></Field>
414:             </div>
415:           </fieldset>
416:           <fieldset className="ck-block" disabled={step === 'submitting'}>
417:             <h2 className="checkout-heading">خيارات الشحن</h2>
418:             <div className="radio-list">
419:               {[['standard', 'شحن قياسي', '3–5 أيام عمل', 350], ['express', 'شحن سريع', '1–2 يوم عمل · القاهرة والجيزة', 650]].map(([k, t, d, p]) => (
420:                 <label key={k} className="radio-row"><span className="radio-left"><input type="radio" checked={ship === k} onChange={() => setShip(k)} /><span><span className="radio-title">{t}</span><span className="radio-desc">{d}</span></span></span><span className="radio-price num">{fmt(p)}</span></label>))}
421:             </div>
422:           </fieldset>
423:           <fieldset className="ck-block" disabled={step === 'submitting'}>
424:             <h2 className="checkout-heading">طريقة الدفع</h2>
425:             <div className="radio-list">
426:               <label className="radio-row"><span className="radio-left"><input type="radio" checked={pay === 'credit'} onChange={() => setPay('credit')} /><span><span className="radio-title">آجل على الحساب</span><span className="radio-desc">المتاح حاليًا <span className="num">{fmt(ACCOUNT.available_credit)}</span> EGP · متاح لحسابك حسب سياسة الائتمان</span></span></span><span className="badge accent">مسموح لحسابك</span></label>
427:               <label className="radio-row"><span className="radio-left"><input type="radio" checked={pay === 'cod'} onChange={() => setPay('cod')} /><span><span className="radio-title">الدفع عند الاستلام</span><span className="radio-desc">رسوم تحصيل <span className="num">150.00</span> EGP</span></span></span><span className="radio-price num">+150.00</span></label>
428:               <label className="radio-row"><span className="radio-left"><input type="radio" checked={pay === 'bank_transfer'} onChange={() => setPay('bank_transfer')} /><span><span className="radio-title">تحويل بنكي مقدم</span><span className="radio-desc">سجّل إشعار السداد بعد التحويل</span></span></span></label>
429:               <label className="radio-row is-disabled"><span className="radio-left"><input type="radio" disabled /><span><span className="radio-title">المحفظة</span><span className="radio-desc">الرصيد <span className="num">{fmt(ACCOUNT.wallet)}</span> غير كافٍ لهذا الطلب</span></span></span></label>
430:             </div>
431:             {overCredit && <div className="mt-16"><Banner kind="error">الإجمالي أكبر من المتاح للشراء الآجل. قلل الكمية أو اختر طريقة دفع أخرى.</Banner></div>}
432:           </fieldset>
433:         </div>
434:         <aside style={{ position: 'sticky', top: 100, alignSelf: 'start' }}>
435:           <h2 className="checkout-heading">ملخص الطلب</h2>
436:           <div className="ck-items">
437:             {(lines.length ? lines : [{ v: ALL_VARIANTS[0], qty: 30, total: 31200 }, { v: ALL_VARIANTS[10], qty: 60, total: 15300 }]).map((l) => (
438:               <div key={l.v.id} className="ck-item"><Thumb sm /><div style={{ flex: 1, minWidth: 0 }}><div className="strong small">{l.v.product.name_ar}</div><div className="soft small">{l.v.label} · <span className="num">×{l.qty}</span></div></div><span className="num strong small">{fmt(l.total)}</span></div>))}
439:           </div>
440:           <div className="sum-row"><span>قيمة المنتجات</span><strong className="num">{fmt(sub)}</strong></div>
441:           <div className="sum-row is-neg"><span>الخصم</span><strong className="num">—</strong></div>
442:           <div className="sum-row"><span>الشحن</span><strong className="num">{fmt(shipping + (step !== 'form' ? 120 : 0))}</strong></div>
443:           <div className="sum-row"><span>الضريبة</span><strong className="num">0.00</strong></div>
444:           {codFee > 0 && <div className="sum-row"><span>رسوم التحصيل</span><strong className="num">{fmt(codFee)}</strong></div>}
445:           <div className="sum-total"><span>الإجمالي النهائي</span><span className="num">{fmt(total + (step !== 'form' ? 120 : 0))}</span></div>
446:           <button className="btn-block mt-24" disabled={overCredit || step === 'submitting'} onClick={submit}>{step === 'submitting' ? <><span className="spin" /> جاري إتمام الطلب…</> : step === 'changed' ? 'تأكيد الإجمالي الجديد وإتمام الطلب' : 'إتمام الطلب'}</button>
447:           <p className="note mt-16"><i className="fa-solid fa-lock" />الأسعار والإجمالي النهائي بيتحسبوا من الخادم لحظة التأكيد.</p>
448:         </aside>
449:       </div>
450:     </>
451:   );
452: };
