466:         <div className="row" style={{ justifyContent: 'center', gap: 8, marginBottom: 24 }}><Badge map={ORDER_STATUS} k="pending" /><Badge map={PAY_STATUS} k={pay === 'cod' ? 'pending' : 'unpaid'} /></div>
467:         <div style={{ textAlign: 'start' }}>
