469:           <div className="sum-row"><span>طريقة الدفع</span><strong>{PAY_METHOD[pay]}</strong></div>
470:           <div className="sum-row"><span>عنوان التسليم</span><strong style={{ textAlign: 'left' }}>القاهرة — {o.address.split('—')[0]}</strong></div>
471:           <div className="sum-total"><span>الإجمالي</span><span className="num">{fmt(lastOrder?.total || o.total)}</span></div>
472:         </div>
473:         <div className="row mt-24" style={{ justifyContent: 'center' }}>
474:           <button className="btn-pill is-dark" onClick={() => go('order', 9)}>فتح الطلب</button>
475:           <button className="btn-pill" onClick={() => go('catalog')}>الرجوع للكتالوج</button>
476:         </div>
477:       </div>
478:     </div>
479:   );
480: };
