  9:   const list = ORDERS.filter((o) => o.status !== 'cancelled').filter((o) => f === 'all' || (f === 'paid' ? o.pay === 'paid' : o.pay !== 'paid'));
 10:   const pdf = (o) => { setDl(o.id); setTimeout(() => { setDl(null); toast(`تم تنزيل الفاتورة ${o.number}.pdf`); }, 900); };
 11:   return (
 12:     <>
 13:       <PageHead en="Invoices" ar="رقم الفاتورة هو نفس رقم الطلب" />
 14:       <section className="panel">
 15:         <div className="toolbar"><Seg value={f} onChange={setF} options={[{ value: 'all', label: 'الكل' }, { value: 'unpaid', label: 'غير مدفوع', n: ORDERS.filter((o) => o.pay !== 'paid' && o.status !== 'cancelled').length }, { value: 'paid', label: 'مدفوع' }]} />
 16:           <span className="soft small">غير مدفوع: <Money v={ORDERS.filter((o) => o.pay !== 'paid' && o.status !== 'cancelled').reduce((a, o) => a + o.total, 0)} strong /></span></div>
 17:         <Async rows={5} cols={7} isEmpty={!list.length} empty={<Empty icon="fa-file-invoice" title="لا توجد فواتير" />}>
 18:           <div className="tbl-wrap"><table className="tbl">
 19:             <thead><tr><th>رقم الفاتورة</th><th>التاريخ</th><th>حالة الطلب</th><th>الدفع</th><th>السداد</th><th>قبل الخصم</th><th>الخصم</th><th>الشحن</th><th>الضريبة</th><th className="t-end">الإجمالي</th><th></th></tr></thead>
 20:             <tbody>{list.map((o) => (
 21:               <tr key={o.id} className="is-click" onClick={() => setOpen(o)}>
 22:                 <td className="strong num">{o.number}</td><td className="num">{o.date}</td><td><Badge map={ORDER_STATUS} k={o.status} /></td><td>{PAY_METHOD[o.method]}</td><td><Badge map={PAY_STATUS} k={o.pay} /></td>
 23:                 <td className="num">{fmt(o.subtotal)}</td><td className="num" style={{ color: o.discount ? 'var(--teal)' : null }}>{o.discount ? fmt(o.discount) : '—'}</td><td className="num">{fmt(o.shipping)}</td><td className="num">{fmt(o.tax)}</td>
 24:                 <td className="t-end strong num">{fmt(o.total)}</td>
 25:                 <td onClick={(e) => e.stopPropagation()}><div className="row-actions"><button className="btn-pill sm" onClick={() => pdf(o)} disabled={dl === o.id}>{dl === o.id ? <span className="spin" /> : <i className="fa-regular fa-file-pdf" />} PDF</button></div></td>
 26:               </tr>))}</tbody>
 27:           </table></div>
 28:           <Pager total={list.length} pages={1} />
 29:         </Async>
 30:       </section>
 31:       {open && (
 32:         <Modal wide title={<>فاتورة <span className="num">{open.number}</span></>} onClose={() => setOpen(null)}
 33:           foot={<><button className="btn-pill" onClick={() => go('order', open.id)}>فتح الطلب المرتبط</button><button className="btn-pill is-dark" onClick={() => pdf(open)}><i className="fa-regular fa-file-pdf" /> تنزيل PDF</button></>}>
 34:           <div className="inv-head">
 35:             <div><div className="wp-logo" style={{ fontSize: 20 }}>SOPHIE</div><div className="soft small">فاتورة ضريبية مبسطة</div></div>
 36:             <dl className="kv" style={{ gridTemplateColumns: '90px auto' }}><dt>التاريخ</dt><dd className="num">{open.date}</dd><dt>العميل</dt><dd>{ACCOUNT.company}</dd><dt>السداد</dt><dd><Badge map={PAY_STATUS} k={open.pay} /></dd></dl>
 37:           </div>
 38:           <table className="tbl mt-16"><thead><tr><th>المنتج</th><th>الكمية</th><th>السعر</th><th className="t-end">الإجمالي</th></tr></thead>
 39:             <tbody>{open.items.map((it) => <tr key={it.sku}><td><div className="strong">{it.name}</div><div className="sku">{it.sku}</div></td><td className="num">{it.qty}</td><td className="num">{fmt(it.unit)}</td><td className="t-end num strong">{fmt(it.unit * it.qty)}</td></tr>)}</tbody></table>
 40:           <div style={{ maxWidth: 320, marginInlineStart: 'auto' }} className="mt-16">
 41:             <div className="sum-row"><span>المنتجات قبل الخصم</span><strong className="num">{fmt(open.subtotal)}</strong></div>
 42:             <div className="sum-row is-neg"><span>الخصم</span><strong className="num">{open.discount ? '− ' + fmt(open.discount) : '—'}</strong></div>
 43:             <div className="sum-row"><span>الشحن</span><strong className="num">{fmt(open.shipping)}</strong></div>
 44:             <div className="sum-row"><span>الضريبة</span><strong className="num">{fmt(open.tax)}</strong></div>
 45:             <div className="sum-total"><span>الإجمالي</span><span className="num">{fmt(open.total)}</span></div>
 46:           </div>
 47:         </Modal>
 48:       )}
 49:     </>
 50:   );
 51: };
