 53: /* ---------- 19. Statement ---------- */
 54: const Statement = () => {
 55:   const { go } = useApp();
 56:   const [from, setFrom] = useState('2026-10-01');
 57:   const [to, setTo] = useState('2026-10-28');
 58:   const bad = from > to;
 59:   const out = ORDERS.filter((o) => o.pay === 'unpaid' && o.status !== 'cancelled');
 60:   return (
 61:     <>
 62:       <PageHead en="Statement" ar="كشف الحساب والمديونية">
 63:         <button className="btn-pill is-dark" onClick={() => go('noticeNew')}><i className="fa-solid fa-money-check-dollar" /> تسجيل إشعار سداد</button>
 64:       </PageHead>
 65:       <div className="kpis" style={{ gridTemplateColumns: 'repeat(4, minmax(0,1fr))' }}>
 66:         <div className="kpi is-ink"><span className="kpi-en">CURRENT DEBT</span><span className="kpi-label">المديونية الحالية</span><span className="kpi-value">{fmt(ACCOUNT.used_credit)}<small>EGP</small></span></div>
 67:         <div className="kpi"><span className="kpi-en">CREDIT LIMIT</span><span className="kpi-label">حد الائتمان</span><span className="kpi-value">{fmt(ACCOUNT.credit_limit)}<small>EGP</small></span></div>
 68:         <div className="kpi"><span className="kpi-en">OPENING</span><span className="kpi-label">رصيد أول المدة</span><span className="kpi-value">{fmt(STATEMENT.opening)}<small>EGP</small></span></div>
 69:         <div className="kpi"><span className="kpi-en">CLOSING</span><span className="kpi-label">رصيد آخر المدة</span><span className="kpi-value">{fmt(STATEMENT.closing)}<small>EGP</small></span></div>
 70:       </div>
 71:       <div className="grid-2" style={{ gridTemplateColumns: '1fr 320px' }}>
 72:         <section className="panel">
 73:           <div className="toolbar">
 74:             <div className="row" style={{ gap: 20 }}>
 75:               <Field label="من تاريخ"><input type="date" className={`line-input ltr${bad ? ' is-invalid' : ''}`} value={from} onChange={(e) => setFrom(e.target.value)} /></Field>
 76:               <Field label="إلى تاريخ"><input type="date" className={`line-input ltr${bad ? ' is-invalid' : ''}`} value={to} onChange={(e) => setTo(e.target.value)} /></Field>
 77:             </div>
 78:             <div className="chips">{['هذا الشهر', 'آخر 3 شهور', 'هذه السنة'].map((l, i) => <button key={l} className={`chip${i === 0 ? ' is-on' : ''}`}>{l}</button>)}</div>
 79:           </div>
 80:           {bad ? <div style={{ padding: 24 }}><Banner kind="error">تاريخ البداية لازم يكون قبل تاريخ النهاية.</Banner></div> : (
 81:             <Async rows={8} cols={6} empty={<Empty icon="fa-receipt" title="لا توجد حركات في هذه الفترة" desc="جرب فترة زمنية أخرى." />}>
 82:               <div className="tbl-wrap"><table className="tbl">
 83:                 <thead><tr><th>التاريخ</th><th>المرجع</th><th>البيان</th><th className="t-end">مدين</th><th className="t-end">دائن</th><th className="t-end">الرصيد</th></tr></thead>
 84:                 <tbody>{STATEMENT.rows.map((r, i) => (
 85:                   <tr key={i} style={r.opening ? { background: '#fafbfc' } : null}>
 86:                     <td className="num">{r.date}</td><td className="sku">{r.ref}</td><td className={r.opening ? 'strong' : ''}>{r.desc}</td>
 87:                     <td className="t-end num">{r.debit ? fmt(r.debit) : ''}</td><td className="t-end num" style={{ color: 'var(--teal)' }}>{r.credit ? fmt(r.credit) : ''}</td>
 88:                     <td className="t-end num strong">{fmt(r.bal)}</td></tr>))}</tbody>
 89:                 <tfoot><tr><td colSpan="3">رصيد آخر المدة</td><td className="t-end num">{fmt(STATEMENT.rows.reduce((a, r) => a + r.debit, 0))}</td><td className="t-end num">{fmt(STATEMENT.rows.reduce((a, r) => a + r.credit, 0))}</td><td className="t-end num">{fmt(STATEMENT.closing)}</td></tr></tfoot>
 90:               </table></div>
 91:             </Async>
 92:           )}
 93:         </section>
 94:         <aside className="stack" style={{ position: 'sticky', top: 100 }}>
 95:           <Panel title="مستحقات مفتوحة" en="OUTSTANDING" body={false}>
 96:             {out.map((o) => <div key={o.id} className="out-row" onClick={() => go('order', o.id)}><div><b className="num">{o.number}</b><span className="num">{o.date}</span></div><span className="num strong">{fmt(o.total)}</span></div>)}
 97:             <div className="panel-body" style={{ paddingTop: 12 }}><div className="sum-total" style={{ paddingTop: 0 }}><span>الإجمالي</span><span className="num" style={{ fontSize: 18 }}>{fmt(out.reduce((a, o) => a + o.total, 0))}</span></div></div>
 98:           </Panel>
 99:           <p className="note"><i className="fa-solid fa-circle-info" />المديونية والائتمان منفصلين تمامًا عن رصيد المحفظة.</p>
100:         </aside>
101:       </div>
102:     </>
103:   );
104: };
