106: /* ---------- 20. New payment notice ---------- */
107: const NoticeForm = () => {
108:   const { go } = useApp();
109:   const [f, setF] = useState({ order: '', amount: '', method: 'bank_transfer', bank: '', ref: '', date: '' });
110:   const [file, setFile] = useState(null);
111:   const [errs, setErrs] = useState({});
112:   const [stage, setStage] = useState('form'); // form | confirm | sending | done
113:   const out = ORDERS.filter((o) => o.pay === 'unpaid' && o.status !== 'cancelled');
114:   const set = (k, v) => { setF({ ...f, [k]: v }); setErrs({ ...errs, [k]: null }); };
115:   const validate = () => {
116:     const e = {};
117:     if (!f.amount || Number(f.amount) <= 0) e.amount = 'أدخل مبلغ صحيح أكبر من صفر.';
118:     if (!f.bank.trim()) e.bank = 'اسم البنك مطلوب.';
119:     if (!f.ref.trim()) e.ref = 'رقم المرجع مطلوب.';
120:     if (!f.date) e.date = 'تاريخ التحويل مطلوب.'; else if (f.date > '2026-10-29') e.date = 'تاريخ التحويل لا يمكن أن يكون في المستقبل.';
121:     if (!file) e.file = 'إيصال التحويل مطلوب.'; else if (file.bad) e.file = 'حجم الملف أكبر من 10 ميجابايت.';
122:     setErrs(e); return !Object.keys(e).length;
123:   };
124:   if (stage === 'done') return (
125:     <div className="success-wrap"><div className="order-card">
126:       <div className="modal-icon" style={{ width: 64, height: 64, fontSize: 26 }}><i className="fa-solid fa-paper-plane" /></div>
127:       <h1 className="success-title">NOTICE SENT</h1>
128:       <p className="muted">تم إرسال إشعار السداد للمراجعة</p>
129:       <p className="success-num num">PN-0432</p>
130:       <Banner kind="warn" icon="fa-hourglass-half">رفع الإيصال <b>لا يعني اعتماد السداد</b>. الإدارة هتراجع التحويل وتعتمده، وهيوصلك إشعار.</Banner>
131:       <div className="row mt-24" style={{ justifyContent: 'center' }}><button className="btn-pill is-dark" onClick={() => go('notice', 431)}>عرض الإشعار</button><button className="btn-pill" onClick={() => go('notices')}>كل الإشعارات</button></div>
132:     </div></div>
133:   );
134:   return (
135:     <>
136:       <PageHead en="Payment Notice" crumb={<Crumb items={[{ label: 'إشعارات السداد', go: () => go('notices') }, { label: 'إشعار جديد' }]} />} ar="سجّل تحويل أو شيك أو إيداع تم لحساب الشركة" />
137:       <div className="grid-2" style={{ gridTemplateColumns: '1fr 340px' }}>
138:         <section className="panel"><div className="panel-body">
139:           <div className="fields">
140:             <Field label="طلب مرتبط" opt span>
141:               <select className="line-input" value={f.order} onChange={(e) => { const o = out.find((x) => x.number === e.target.value); setF({ ...f, order: e.target.value, amount: o ? String(o.total) : f.amount }); }}>
142:                 <option value="">بدون — سداد على الحساب</option>{out.map((o) => <option key={o.id} value={o.number}>{o.number} · {fmt(o.total)} EGP</option>)}
143:               </select></Field>
144:             <Field label="المبلغ" req error={errs.amount}><div style={{ position: 'relative' }}><input className={`line-input ltr${errs.amount ? ' is-invalid' : ''}`} style={{ textAlign: 'right', paddingLeft: 40 }} inputMode="decimal" placeholder="0.00" value={f.amount} onChange={(e) => set('amount', e.target.value.replace(/[^\d.]/g, ''))} /><span className="soft small" style={{ position: 'absolute', left: 0, top: 12 }}>EGP</span></div></Field>
145:             <Field label="تاريخ التحويل" req error={errs.date}><input type="date" max="2026-10-29" className={`line-input ltr${errs.date ? ' is-invalid' : ''}`} value={f.date} onChange={(e) => set('date', e.target.value)} /></Field>
146:             <Field label="طريقة السداد" req span>
147:               <div className="chips">{Object.entries(NOTICE_METHOD).map(([k, l]) => <button key={k} type="button" className={`chip${f.method === k ? ' is-on' : ''}`} onClick={() => set('method', k)}><i className={`fa-solid ${{ bank_transfer: 'fa-building-columns', cheque: 'fa-money-check', deposit: 'fa-piggy-bank' }[k]}`} />{l}</button>)}</div></Field>
148:             <Field label="اسم البنك" req error={errs.bank}><input className={`line-input${errs.bank ? ' is-invalid' : ''}`} placeholder="مثال: البنك الأهلي المصري" value={f.bank} onChange={(e) => set('bank', e.target.value)} /></Field>
149:             <Field label={f.method === 'cheque' ? 'رقم الشيك' : 'رقم المرجع'} req error={errs.ref}><input className={`line-input ltr${errs.ref ? ' is-invalid' : ''}`} style={{ textAlign: 'right' }} value={f.ref} onChange={(e) => set('ref', e.target.value)} /></Field>
150:             <Field label="الإيصال" req span error={errs.file}>
151:               {file ? (
152:                 <div className="file-row" style={file.bad ? { borderColor: '#fecaca', background: '#fffafa' } : null}><i className="fa-regular fa-file-pdf" /><div className="grow"><b className="num">{file.name}</b> <span className="soft num">· {file.size}</span></div><button className="btn-link muted" onClick={() => setFile(null)}><i className="fa-solid fa-xmark" /></button></div>
153:               ) : (
154:                 <div className={`drop${errs.file ? ' is-invalid' : ''}`} style={{ minHeight: 120 }} onClick={() => { setFile({ name: 'nbe-transfer-receipt.pdf', size: '412 KB' }); setErrs({ ...errs, file: null }); }}>
155:                   <i className="fa-solid fa-receipt" /><b>ارفع صورة أو PDF للإيصال</b><small>PDF · JPG · JPEG · PNG · WebP — حتى <span className="num">10</span> ميجابايت</small></div>
156:               )}
157:               {!file && <button className="btn-link muted mt-8" style={{ fontSize: 12 }} onClick={() => setFile({ name: 'scan-hq.png', size: '14.2 MB', bad: true })}>جرب ملف كبير (حالة خطأ)</button>}
158:             </Field>
159:           </div>
160:         </div></section>
161:         <aside className="stack" style={{ position: 'sticky', top: 100 }}>
162:           <Panel title="مراجعة">
163:             <div className="sum-row"><span>الطلب</span><strong className="num">{f.order || 'على الحساب'}</strong></div>
164:             <div className="sum-row"><span>الطريقة</span><strong>{NOTICE_METHOD[f.method]}</strong></div>
165:             <div className="sum-total"><span>المبلغ</span><span className="num">{f.amount ? fmt(f.amount) : '—'}</span></div>
166:             <button className="btn-block mt-24" onClick={() => validate() && setStage('confirm')}>إرسال للمراجعة</button>
167:           </Panel>
168:           <p className="note"><i className="fa-solid fa-circle-info" />السداد مش بيتعتمد تلقائيًا؛ الإدارة بتراجع الإيصال مع كشف البنك.</p>
169:         </aside>
170:       </div>
171:       {(stage === 'confirm' || stage === 'sending') && <Modal title="تأكيد إرسال إشعار السداد" onClose={() => setStage('form')} icon={<div className="modal-icon"><i className="fa-solid fa-money-check-dollar" /></div>}
172:         foot={<><button className="btn-pill" onClick={() => setStage('form')}>تعديل</button><button className="btn-pill is-dark" disabled={stage === 'sending'} onClick={() => { setStage('sending'); setTimeout(() => setStage('done'), 900); }}>{stage === 'sending' ? <span className="spin" /> : null} تأكيد الإرسال</button></>}>
173:         <dl className="kv"><dt>المبلغ</dt><dd><Money v={f.amount} strong /></dd><dt>الطريقة</dt><dd>{NOTICE_METHOD[f.method]}</dd><dt>البنك</dt><dd>{f.bank}</dd><dt>المرجع</dt><dd className="sku">{f.ref}</dd><dt>التاريخ</dt><dd className="num">{f.date}</dd><dt>الإيصال</dt><dd className="num">{file?.name}</dd></dl>
174:       </Modal>}
175:     </>
176:   );
177: };
