179: /* ---------- 21. Notices list + detail ---------- */
180: const Notices = () => {
181:   const { go } = useApp();
182:   return (
183:     <>
184:       <PageHead en="Payment Notices" ar="إشعارات السداد المرسلة وحالة مراجعتها"><button className="btn-pill is-dark" onClick={() => go('noticeNew')}><i className="fa-solid fa-plus" /> إشعار جديد</button></PageHead>
185:       <section className="panel">
186:         <Async rows={5} cols={6} empty={<Empty icon="fa-money-check" title="لا توجد إشعارات سداد" action={<button className="btn-pill is-dark" onClick={() => go('noticeNew')}>تسجيل إشعار</button>} />}>
187:           <div className="tbl-wrap"><table className="tbl">
188:             <thead><tr><th>رقم الإشعار</th><th>الطلب</th><th>الطريقة</th><th>تاريخ التحويل</th><th>الحالة</th><th>تاريخ الإنشاء</th><th className="t-end">المبلغ</th></tr></thead>
189:             <tbody>{NOTICES.map((n) => (
190:               <tr key={n.id} className="is-click" onClick={() => go('notice', n.id)}>
191:                 <td className="strong num">{n.number}</td><td className="num">{n.order || <span className="soft">على الحساب</span>}</td><td>{NOTICE_METHOD[n.method]}</td><td className="num">{n.date}</td>
192:                 <td><Badge map={NOTICE_STATUS} k={n.status} /></td><td className="num">{n.created}</td><td className="t-end strong num">{fmt(n.amount)}</td></tr>))}</tbody>
193:           </table></div>
194:           <Pager total={NOTICES.length} pages={1} />
195:         </Async>
196:       </section>
197:     </>
198:   );
199: };
