201: const NoticeDetail = ({ id }) => {
202:   const { go, toast } = useApp();
203:   const n = NOTICES.find((x) => x.id === id) || NOTICES[0];
204:   return (
205:     <>
206:       <PageHead en={n.number} crumb={<Crumb items={[{ label: 'إشعارات السداد', go: () => go('notices') }, { label: n.number, mono: true }]} />} ar={<>أُرسل في <span className="num">{n.created}</span></>}>
207:         <Badge map={NOTICE_STATUS} k={n.status} lg />
208:       </PageHead>
209:       {n.status === 'rejected' && <div className="mb-24"><Banner kind="error" action={<button className="btn-pill sm" onClick={() => go('noticeNew')}>إرسال إشعار جديد</button>}>تم رفض الإشعار. راجع ملاحظة الإدارة وأرسل إشعار جديد بالبيانات الصحيحة.</Banner></div>}
210:       {n.status === 'pending' && <div className="mb-24"><Banner kind="warn" icon="fa-hourglass-half">الإشعار قيد المراجعة من الإدارة. المبلغ لن يُخصم من المديونية قبل الاعتماد.</Banner></div>}
211:       <div className="grid-2e">
212:         <Panel title="بيانات السداد" en="DETAILS">
213:           <dl className="kv"><dt>المبلغ</dt><dd><Money v={n.amount} strong /></dd><dt>الطريقة</dt><dd>{NOTICE_METHOD[n.method]}</dd><dt>اسم البنك</dt><dd>{n.bank}</dd><dt>رقم المرجع</dt><dd className="sku">{n.ref}</dd><dt>تاريخ التحويل</dt><dd className="num">{n.date}</dd>
214:             <dt>الطلب المرتبط</dt><dd>{n.order ? <button className="btn-link num" onClick={() => go('order', 8)}>{n.order}</button> : <span className="soft">على الحساب</span>}</dd></dl>
215:         </Panel>
216:         <div className="stack">
217:           <Panel title="الإيصال" en="RECEIPT">
218:             <div className="file-row"><i className={`fa-regular ${n.receipt.endsWith('.pdf') ? 'fa-file-pdf' : 'fa-file-image'}`} /><div className="grow num">{n.receipt}</div><button className="btn-pill sm" onClick={() => toast('جارٍ تنزيل الإيصال')}><i className="fa-solid fa-download" /> تنزيل</button></div>
219:           </Panel>
220:           <Panel title="ملاحظات الإدارة" en="ADMIN NOTE">
221:             <div className={`note-bubble is-admin`} style={{ margin: 0 }}><p>{n.admin_note || <span className="soft">لا توجد ملاحظات</span>}</p></div>
222:           </Panel>
223:         </div>
224:       </div>
225:     </>
226:   );
227: };
