163: /* ---------- 16. Create / edit quote ---------- */
164: const QuoteForm = ({ id }) => {
165:   const { go, toast } = useApp();
166:   const editing = QUOTES.find((q) => q.id === id);
167:   const init = editing ? editing.items.map((it) => ({ v: ALL_VARIANTS.find((v) => v.sku === it.sku), qty: it.qty, target: String(it.target || '') }))
168:     : [{ v: ALL_VARIANTS[0], qty: 80, target: '950' }, { v: ALL_VARIANTS[5], qty: 50, target: '' }];
169:   const [items, setItems] = useState(init);
170:   const [note, setNote] = useState(editing?.trader_note || '');
171:   const [search, setSearch] = useState('');
172:   const [errs, setErrs] = useState({});
173:   const [confirm, setConfirm] = useState(null);
174:   const matches = search ? ALL_VARIANTS.filter((v) => (v.product.name_ar + v.sku + v.label).toLowerCase().includes(search.toLowerCase())).slice(0, 5) : [];
175:   const upd = (i, k, val) => setItems(items.map((it, j) => j === i ? { ...it, [k]: val } : it));
176:   const validate = () => { const e = {}; items.forEach((it, i) => { if (!it.qty) e[i] = 'الكمية مطلوبة'; }); if (!items.length) e.items = 'أضف بند واحد على الأقل.'; setErrs(e); return !Object.keys(e).length; };
177:   return (
178:     <>
179:       <PageHead en={editing ? editing.number : 'New Quote'} crumb={<Crumb items={[{ label: 'عروض الأسعار', go: () => go('quotes') }, { label: editing ? 'تعديل مسودة' : 'طلب جديد' }]} />} ar={editing ? 'مسودة — يمكنك التعديل قبل الإرسال' : 'اختر المنتجات والكميات، واقترح السعر المستهدف لو حابب'}>
180:         {editing && <button className="btn-pill is-danger" onClick={() => setConfirm('delete')}><i className="fa-regular fa-trash-can" /> حذف المسودة</button>}
181:       </PageHead>
182:       <div className="grid-2" style={{ gridTemplateColumns: '1fr 340px' }}>
183:         <section className="panel">
184:           <div className="toolbar" style={{ position: 'relative' }}>
185:             <div className="search" style={{ flex: 1 }}><i className="fa-solid fa-plus" /><input className="line-input" placeholder="أضف منتج — ابحث بالاسم أو SKU" value={search} onChange={(e) => setSearch(e.target.value)} /></div>
186:             <span className="soft small"><span className="num">{items.length}</span> / <span className="num">100</span> بند</span>
187:             {matches.length > 0 && (
188:               <div className="qf-suggest">{matches.map((v) => (
189:                 <button key={v.id} onClick={() => { setItems([...items, { v, qty: v.tiers[0][0], target: '' }]); setSearch(''); }}>
190:                   <Thumb sm /><span style={{ flex: 1 }}><b>{v.product.name_ar} — {v.label}</b><span className="sku">{v.sku}</span></span><span className="num small">{fmt(v.price)}</span></button>))}</div>
191:             )}
192:           </div>
193:           {items.length === 0 ? <Empty icon="fa-list" title="مفيش بنود" desc="ابحث وأضف المنتجات اللي عايز تسعيرها." /> : (
194:             <div className="tbl-wrap"><table className="tbl">
195:               <thead><tr><th>المتغير</th><th>سعرك الحالي</th><th>الكمية</th><th>السعر المستهدف <span className="f-opt">(اختياري)</span></th><th></th></tr></thead>
196:               <tbody>{items.map((it, i) => (
197:                 <tr key={i} className={errs[i] ? 'is-error' : ''}>
198:                   <td><div className="prod-cell"><Thumb sm /><div><div className="prod-name">{it.v.product.name_ar}</div><div className="soft small">{it.v.label} · <span className="sku">{it.v.sku}</span></div></div></div></td>
199:                   <td className="num">{fmt(it.v.price)}</td>
200:                   <td><Qty value={it.qty} onChange={(n) => upd(i, 'qty', n)} />{errs[i] && <p className="f-error">{errs[i]}</p>}</td>
201:                   <td><input className="box-input ltr" style={{ width: 120 }} placeholder="0.00" value={it.target} onChange={(e) => upd(i, 'target', e.target.value.replace(/[^\d.]/g, ''))} /></td>
202:                   <td><button className="btn-link muted" onClick={() => setItems(items.filter((_, j) => j !== i))} aria-label="حذف"><i className="fa-solid fa-xmark" /></button></td>
203:                 </tr>))}</tbody>
204:             </table></div>
205:           )}
206:           {errs.items && <p className="f-error" style={{ padding: '0 24px 16px' }}>{errs.items}</p>}
207:         </section>
208:         <aside className="stack" style={{ position: 'sticky', top: 100 }}>
209:           <Panel title="ملاحظات للإدارة">
210:             <Field label="ملاحظات التاجر" opt counter={<span className="f-counter" style={{ color: note.length > 2000 ? '#b91c1c' : null }}>{note.length}/2000</span>} error={note.length > 2000 ? 'الحد الأقصى 2000 حرف.' : null}>
211:               <textarea className="line-input" rows="5" value={note} placeholder="مواعيد التسليم، تغليف خاص، شروط الدفع…" onChange={(e) => setNote(e.target.value)} />
212:             </Field>
213:             <div className="divider" />
214:             <div className="sum-row"><span>عدد البنود</span><strong className="num">{items.length}</strong></div>
215:             <div className="sum-row"><span>إجمالي الكميات</span><strong className="num">{items.reduce((a, it) => a + it.qty, 0)}</strong></div>
216:             <button className="btn-block mt-24" onClick={() => validate() && setConfirm('submit')}><i className="fa-solid fa-paper-plane" /> إرسال للإدارة للتسعير</button>
217:             <button className="btn-pill mt-8" style={{ width: '100%', justifyContent: 'center' }} onClick={() => { toast('تم حفظ المسودة'); go('quotes'); }}><i className="fa-regular fa-floppy-disk" /> حفظ كمسودة</button>
218:           </Panel>
219:           <p className="note"><i className="fa-solid fa-circle-info" />بعد الإرسال مش هتقدر تعدّل الطلب. الإدارة هترد بالأسعار وتاريخ صلاحية العرض.</p>
220:         </aside>
221:       </div>
222:       {confirm === 'submit' && <Modal title="إرسال طلب التسعير؟" onClose={() => setConfirm(null)} icon={<div className="modal-icon"><i className="fa-solid fa-paper-plane" /></div>}
223:         foot={<><button className="btn-pill" onClick={() => setConfirm(null)}>رجوع</button><button className="btn-pill is-dark" onClick={() => { toast('تم إرسال الطلب للإدارة'); go('quote', 30); }}>إرسال</button></>}>
224:         <p className="muted">هيتم إرسال <span className="num">{items.length}</span> بند للإدارة. الحالة هتتغير إلى «مطلوب تسعيره».</p></Modal>}
225:       {confirm === 'delete' && <Modal title="حذف المسودة؟" onClose={() => setConfirm(null)} icon={<div className="modal-icon is-err"><i className="fa-solid fa-trash-can" /></div>}
226:         foot={<><button className="btn-pill" onClick={() => setConfirm(null)}>رجوع</button><button className="btn-pill is-danger" onClick={() => { toast('تم حذف المسودة'); go('quotes'); }}>حذف</button></>}>
227:         <p className="muted">الإجراء ده نهائي.</p></Modal>}
228:     </>
229:   );
230: };
