280: /* ---------- 22. Returns ---------- */
281: const Returns = () => {
282:   const { go } = useApp();
283:   return (
284:     <>
285:       <PageHead en="Returns" ar="طلبات الإرجاع والاسترداد"><button className="btn-pill is-dark" onClick={() => go('returnNew')}><i className="fa-solid fa-plus" /> طلب إرجاع</button></PageHead>
286:       <section className="panel">
287:         <Async rows={4} cols={5} empty={<Empty icon="fa-rotate-left" title="مفيش مرتجعات" desc="تقدر تطلب إرجاع لأي طلب مؤهل بعد التسليم." />}>
288:           <div className="tbl-wrap"><table className="tbl">
289:             <thead><tr><th>رقم المرتجع</th><th>الطلب</th><th>الحالة</th><th>مبلغ الاسترداد</th><th>التاريخ</th><th></th></tr></thead>
290:             <tbody>{RETURNS.map((r) => (
291:               <tr key={r.id} className="is-click" onClick={() => go('return', r.id)}>
292:                 <td className="strong num">{r.number}</td><td className="num">{r.order}</td><td><Badge map={RETURN_STATUS} k={r.status} /></td>
293:                 <td className="strong num">{fmt(r.refund)}</td><td className="num">{r.date}</td><td className="t-end"><button className="btn-link muted">التفاصيل</button></td></tr>))}</tbody>
294:           </table></div>
295:         </Async>
296:       </section>
297:     </>
298:   );
299: };
