301: const ReturnForm = ({ orderId }) => {
302:   const { go, toast } = useApp();
303:   const eligible = ORDERS.filter((o) => o.returnable);
304:   const [oid, setOid] = useState(orderId || eligible[0].id);
305:   const o = ORDERS.find((x) => x.id === oid);
306:   const [sel, setSel] = useState({});
307:   const [reason, setReason] = useState('');
308:   const [method, setMethod] = useState('wallet');
309:   const [errs, setErrs] = useState({});
310:   const toggle = (sku) => setSel({ ...sel, [sku]: sel[sku] ? undefined : { qty: 1, reason: '', photos: 0 } });
311:   const set = (sku, k, v) => setSel({ ...sel, [sku]: { ...sel[sku], [k]: v } });
312:   const chosen = Object.entries(sel).filter(([, v]) => v);
313:   const totalPhotos = chosen.reduce((a, [, v]) => a + v.photos, 0);
314:   const submit = () => {
315:     const e = {};
316:     if (!chosen.length) e.items = 'اختر بند واحد على الأقل.';
317:     if (!reason.trim()) e.reason = 'السبب العام مطلوب.';
318:     chosen.forEach(([s, v]) => { if (!v.reason.trim()) e[s] = 'سبب البند مطلوب.'; });
319:     setErrs(e); if (!Object.keys(e).length) { toast('تم تقديم طلب الإرجاع'); go('return', 95); }
320:   };
321:   return (
322:     <>
323:       <PageHead en="New Return" crumb={<Crumb items={[{ label: 'المرتجعات', go: () => go('returns') }, { label: 'طلب جديد' }]} />} ar="اختر الطلب والبنود، ووضح السبب" />
324:       <div className="grid-2" style={{ gridTemplateColumns: '1fr 340px' }}>
325:         <div className="stack">
326:           <Panel title="الطلب المؤهل" en="ORDER">
327:             <div className="addr-picks">{eligible.map((x) => (
328:               <button key={x.id} className={`addr-pick${oid === x.id ? ' is-on' : ''}`} onClick={() => { setOid(x.id); setSel({}); }}><b className="num">{x.number}</b><span>تم التسليم · <span className="num">{x.date}</span> · <span className="num">{fmt(x.total)}</span> EGP</span></button>))}</div>
329:             <p className="note mt-16"><i className="fa-solid fa-circle-info" />الطلبات المؤهلة بس هي اللي بتظهر هنا (تم تسليمها وضمن مدة الإرجاع).</p>
330:           </Panel>
331:           <Panel title="البنود المرتجعة" en="ITEMS">
332:             {errs.items && <p className="f-error" style={{ marginTop: 0 }}>{errs.items}</p>}
333:             {o.items.map((it) => {
334:               const s = sel[it.sku];
335:               return (
336:                 <div key={it.sku} className={`ret-item${s ? ' is-on' : ''}`}>
337:                   <label className="row" style={{ cursor: 'pointer' }}>
338:                     <input type="checkbox" checked={!!s} onChange={() => toggle(it.sku)} style={{ accentColor: '#111', width: 16, height: 16 }} />
339:                     <Thumb sm /><div style={{ flex: 1 }}><div className="prod-name">{it.name}</div><div className="soft small"><span className="sku">{it.sku}</span> · تم شراء <span className="num">{it.qty}</span> · <span className="num">{fmt(it.unit)}</span></div></div>
340:                   </label>
341:                   {s && (
342:                     <div className="fields mt-16" style={{ paddingInlineStart: 42 }}>
343:                       <Field label="الكمية المرتجعة" req hint={`حتى ${it.qty}`}><Qty value={s.qty} min={1} onChange={(n) => set(it.sku, 'qty', Math.min(n, it.qty))} /></Field>
344:                       <Field label="سبب البند" req error={errs[it.sku]}><input className={`line-input${errs[it.sku] ? ' is-invalid' : ''}`} value={s.reason} placeholder="مثال: عيب في السحّاب" onChange={(e) => set(it.sku, 'reason', e.target.value)} /></Field>
345:                       <Field label="صور" opt span hint="حتى 5 صور للبند · 5 ميجابايت للصورة · JPG / PNG / WebP">
346:                         <div className="row wrap">
347:                           {Array.from({ length: s.photos }).map((_, k) => <span key={k} className="photo-chip"><i className="fa-regular fa-image" /></span>)}
348:                           {s.photos < 5 && totalPhotos < 10 && <button className="drop sm" style={{ minHeight: 52, width: 52, padding: 0, justifyContent: 'center' }} onClick={() => set(it.sku, 'photos', s.photos + 1)} aria-label="إضافة صورة"><i className="fa-solid fa-plus" /></button>}
349:                         </div>
350:                       </Field>
351:                     </div>
352:                   )}
353:                 </div>);
354:             })}
355:           </Panel>
356:         </div>
357:         <aside className="stack" style={{ position: 'sticky', top: 100 }}>
358:           <Panel title="السبب والاسترداد">
359:             <Field label="السبب العام" req error={errs.reason}><textarea className={`line-input${errs.reason ? ' is-invalid' : ''}`} rows="3" value={reason} onChange={(e) => setReason(e.target.value)} /></Field>
360:             <div className="f-label mt-24">طريقة الاسترداد</div>
361:             <div className="radio-list">{Object.entries(REFUND_METHOD).map(([k, l]) => <label key={k} className="radio-row"><span className="radio-left"><input type="radio" checked={method === k} onChange={() => setMethod(k)} /><span className="radio-title">{l}</span></span></label>)}</div>
362:             <div className="sum-row mt-16"><span>صور مرفقة</span><strong className="num" style={{ color: totalPhotos > 10 ? '#b91c1c' : null }}>{totalPhotos} / 10</strong></div>
363:             <button className="btn-block mt-24" onClick={submit}>تقديم طلب الإرجاع</button>
364:           </Panel>
365:           <p className="note"><i className="fa-solid fa-circle-info" />إجمالي حجم الصور حتى 25 ميجابايت. مبلغ الاسترداد النهائي بيتحدد بعد فحص المرتجع.</p>
366:         </aside>
367:       </div>
368:     </>
369:   );
370: };
