372: const ReturnDetail = ({ id }) => {
373:   const { go } = useApp();
374:   const r = RETURNS.find((x) => x.id === id) || RETURNS[0];
375:   const steps = [['requested', r.date], ['approved', r.approved_at], ['received', r.received_at], ['refunded', r.refunded_at]];
376:   return (
377:     <>
378:       <PageHead en={r.number} crumb={<Crumb items={[{ label: 'المرتجعات', go: () => go('returns') }, { label: r.number, mono: true }]} />} ar={<>على الطلب <button className="btn-link" onClick={() => go('order', 6)}><span className="num">{r.order}</span></button></>}>
379:         <Badge map={RETURN_STATUS} k={r.status} lg />
380:       </PageHead>
381:       <div className="grid-2">
382:         <div className="stack">
383:           <Panel title="البنود" en="ITEMS" body={false}>
384:             <table className="tbl"><thead><tr><th>المنتج</th><th>الكمية</th><th>السبب</th><th>صور</th></tr></thead>
385:               <tbody>{r.items.map((it) => <tr key={it.sku}><td><div className="prod-cell"><Thumb sm /><div><div className="prod-name">{it.name}</div><div className="sku">{it.sku}</div></div></div></td><td className="num">{it.qty}</td><td>{it.reason}</td><td><div className="row" style={{ gap: 6 }}>{Array.from({ length: it.photos }).map((_, k) => <span key={k} className="photo-chip" style={{ width: 36, height: 36 }}><i className="fa-regular fa-image" /></span>)}</div></td></tr>)}</tbody></table>
386:           </Panel>
387:           <Panel title="السبب العام"><p style={{ margin: 0 }}>{r.reason}</p></Panel>
388:         </div>
389:         <div className="stack">
390:           <Panel title="الاسترداد" en="REFUND">
391:             <dl className="kv"><dt>المبلغ</dt><dd><Money v={r.refund} strong /></dd><dt>الطريقة</dt><dd>{REFUND_METHOD[r.method]}</dd><dt>المرجع</dt><dd className="sku">{r.ref || '—'}</dd></dl>
392:           </Panel>
393:           <Panel title="المراحل" en="TIMELINE">
394:             <ul className="tl">{steps.map(([s, d], i) => <li key={s} className={d ? (steps[i + 1] && steps[i + 1][1] ? 'is-done' : 'is-now') : 'is-future'}><div className="tl-title">{RETURN_STATUS[s][0]}</div>{d && <div className="tl-meta num">{d}</div>}</li>)}</ul>
395:           </Panel>
396:         </div>
397:       </div>
398:     </>
399:   );
400: };
