  2: const { useState, useEffect, useCallback, useMemo } = React;
  3: 
  4: const NAV_GROUPS = [
  5:   {
  6:     title: 'نظرة عامة',
  7:     items: [
  8:       { id: 'dashboard', label: 'لوحة التحكم', icon: 'fa-gauge-high' },
  9:     ],
 10:   },
 11:   {
 12:     title: 'الطلبات والمشتريات',
 13:     items: [
 14:       { id: 'catalog', label: 'الكتالوج', icon: 'fa-table-cells-large' },
 15:       { id: 'quick', label: 'طلب سريع', icon: 'fa-bolt' },
 16:       { id: 'cart', label: 'سلة المشتريات', icon: 'fa-bag-shopping', badge: 'cart' },
 17:       { id: 'orders', label: 'الطلبات', icon: 'fa-box' },
 18:       { id: 'quotes', label: 'عروض الأسعار', icon: 'fa-file-signature' },
 19:       { id: 'returns', label: 'المرتجعات', icon: 'fa-rotate-left' },
 20:     ],
 21:   },
 22:   {
 23:     title: 'المالية والحساب',
 24:     items: [
 25:       { id: 'invoices', label: 'الفواتير', icon: 'fa-file-lines' },
 26:       { id: 'statement', label: 'كشف الحساب', icon: 'fa-file-invoice-dollar' },
 27:       { id: 'notices', label: 'إشعارات السداد', icon: 'fa-money-check-dollar' },
 28:       { id: 'wallet', label: 'المحفظة', icon: 'fa-wallet' },
 29:     ],
 30:   },
 31:   {
 32:     title: 'الإعدادات',
 33:     items: [
 34:       { id: 'account', label: 'بيانات الحساب', icon: 'fa-building' },
 35:       { id: 'notifications', label: 'الإشعارات', icon: 'fa-bell', badge: 'notifs' },
 36:       { id: 'status', label: 'حالة الحساب', icon: 'fa-shield-halved' },
 37:     ],
 38:   },
 39: ];
 40: 
 41: function WholesalePortal({ initialScreen = 'dashboard', onLogout }) {
 42:   const [route, setRoute] = useState({ screen: initialScreen, id: null });
 43:   const [cart, setCart] = useState([
 44:     {
 45:       ...ALL_VARIANTS[0],
 46:       product: PRODUCTS[0],
 47:       qty: 6,
 48:     },
 49:     {
 50:       ...ALL_VARIANTS[3],
 51:       product: PRODUCTS[1],
 52:       qty: 4,
 53:     },
 54:   ]);
 55:   const [notifs, setNotifs] = useState(NOTIFS);
 56:   const [orders, setOrders] = useState(ORDERS);
 57:   const [lastOrder, setLastOrder] = useState(ORDERS[0]);
 58:   const [toasts, setToasts] = useState([]);
 59: 
 60:   const toast = useCallback((msg) => {
 61:     const id = Date.now() + Math.random();
 62:     setToasts((prev) => [...prev, { id, msg }]);
 63:     setTimeout(() => {
 64:       setToasts((prev) => prev.filter((t) => t.id !== id));
 65:     }, 3500);
 66:   }, []);
 67: 
 68:   const go = useCallback((screen, id = null) => {
 69:     setRoute({ screen, id });
 70:     window.scrollTo({ top: 0, behavior: 'smooth' });
 71:   }, []);
 72: 
 73:   const addToCart = useCallback((variant, qty = 1) => {
 74:     setCart((prev) => {
 75:       const existing = prev.find((item) => item.sku === variant.sku);
 76:       if (existing) {
 77:         return prev.map((item) =>
 78:           item.sku === variant.sku ? { ...item, qty: item.qty + qty } : item
 79:         );
 80:       }
 81:       const prod = PRODUCTS.find((p) => p.id === variant.productId) || PRODUCTS[0];
 82:       return [...prev, { ...variant, product: prod, qty }];
 83:     });
 84:     toast('تمت الإضافة إلى سلة المشتريات بنجاح');
 85:   }, [toast]);
 86: 
 87:   const placeOrder = useCallback((payload) => {
 88:     const newId = orders.length + 1;
 89:     const newOrder = {
 90:       id: newId,
 91:       number: `ORD-2026-0${140 + newId}`,
 92:       date: new Date().toISOString().split('T')[0],
 93:       status: 'pending',
 94:       pay: payload.payment_method === 'credit' ? 'unpaid' : 'paid',
 95:       method: payload.payment_method || 'credit',
 96:       subtotal: payload.subtotal || 25000,
 97:       discount: payload.discount || 0,
 98:       tax: payload.tax || 3500,
 99:       shipping: payload.shipping || 0,
100:       total: payload.total || 28500,
101:       items: cart.map((it) => ({
102:         name: it.product?.name_ar || it.name || 'حقيبة',
103:         sku: it.sku,
104:         qty: it.qty,
105:         price: it.price || 1500,
106:         color: it.color || 'أسود',
107:       })),
108:       history: [
109:         ['pending', 'الآن', 'تم استلام الطلب وبانتظار المراجعة والتأكيد'],
110:       ],
111:       po: payload.po_number || null,
112:       address: payload.shipping_address || 'المخزن الرئيسي',
113:       notes: payload.notes || null,
114:     };
115:     setOrders((prev) => [newOrder, ...prev]);
116:     setLastOrder(newOrder);
117:     setCart([]);
118:     toast(`تم تسجيل الطلب ${newOrder.number} بنجاح`);
119:     return newOrder;
120:   }, [cart, orders.length, toast]);
121: 
122:   const logout = useCallback(() => {
123:     if (onLogout) onLogout();
124:     else toast('تم تسجيل الخروج');
125:   }, [onLogout, toast]);
126: 
127:   const unreadNotifsCount = useMemo(() => notifs.filter((n) => n.unread).length, [notifs]);
128:   const cartTotalQty = useMemo(() => cart.reduce((sum, it) => sum + (it.qty || 0), 0), [cart]);
129: 
130:   const contextValue = useMemo(() => ({
131:     go,
132:     route,
133:     cart,
134:     setCart,
135:     addToCart,
136:     placeOrder,
137:     lastOrder,
138:     notifs,
139:     setNotifs,
140:     orders,
141:     setOrders,
142:     toast,
143:     account: ACCOUNT,
144:     logout,
145:   }), [go, route, cart, placeOrder, lastOrder, notifs, orders, toast, logout]);
146: 
147:   // Render subscreen
148:   const renderScreen = () => {
149:     const { screen, id } = route;
150:     switch (screen) {
151:       case 'dashboard':
152:         return <Dashboard />;
153:       case 'catalog':
154:         return <Catalog />;
155:       case 'quick':
156:         return <QuickOrder />;
157:       case 'cart':
158:         return <Cart />;
159:       case 'checkout':
160:         return <Checkout />;
161:       case 'success':
162:       case 'orderSuccess':
163:         return <OrderSuccess />;
164:       case 'orders':
165:         return <Orders />;
166:       case 'order':
167:         return <OrderDetail id={id} />;
168:       case 'quotes':
169:         return <Quotes />;
170:       case 'quoteNew':
171:         return <QuoteForm />;
172:       case 'quoteEdit':
173:         return <QuoteForm id={id} />;
174:       case 'quote':
175:         return <QuoteDetail id={id} />;
176:       case 'returns':
177:         return <Returns />;
178:       case 'returnNew':
179:         return <ReturnForm orderId={id} />;
180:       case 'return':
181:         return <ReturnDetail id={id} />;
182:       case 'invoices':
183:         return <Invoices />;
184:       case 'statement':
185:         return <Statement />;
186:       case 'notices':
187:         return <Notices />;
188:       case 'noticeNew':
189:         return <NoticeForm />;
190:       case 'notice':
191:         return <NoticeDetail id={id} />;
192:       case 'wallet':
193:         return <Wallet />;
194:       case 'notifications':
195:         return <Notifications />;
196:       case 'account':
197:         return <Account />;
198:       case 'status':
199:         return <ApplicationStatus onBack={() => go('dashboard')} onEnter={() => go('dashboard')} />;
200:       case 'forgot':
201:         return <ForgotPassword onBack={() => go('dashboard')} onGoReset={() => go('reset')} />;
202:       case 'reset':
203:         return <ResetPassword onBack={() => go('dashboard')} onForgot={() => go('forgot')} />;
204:       default:
205:         return <Dashboard />;
206:     }
207:   };
208: 
209:   const isAuthScreen = ['status', 'forgot', 'reset'].includes(route.screen);
210: 
211:   return (
212:     <AppCtx.Provider value={contextValue}>
213:       <div className="wholesale-portal-app" dir="rtl">
214:         {/* Sticky Header */}
215:         <header className="wp-header">
216:           <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
217:             <button className="wp-logo" onClick={() => go('dashboard')}>
218:               <span>SOPHIE</span>
219:               <span className="wp-logo-tag">WHOLESALE</span>
220:             </button>
221:           </div>
222: 
223:           <div className="wp-head-right">
224:             <div className="wp-credit-chip" title="الحد الائتماني والمتاح">
225:               <span>الرصيد المتاح:</span>
226:               <strong className="num">{fmt(ACCOUNT.available_credit, 0)} EGP</strong>
227:             </div>
228: 
229:             <button
230:               className="wp-icon-btn"
231:               onClick={() => go('notifications')}
232:               title="الإشعارات"
233:             >
234:               <i className="fa-regular fa-bell" />
235:               {unreadNotifsCount > 0 && <span className="wp-count">{unreadNotifsCount}</span>}
236:             </button>
237: 
238:             <button
239:               className="wp-icon-btn"
240:               onClick={() => go('cart')}
241:               title="سلة المشتريات"
242:             >
243:               <i className="fa-solid fa-bag-shopping" />
244:               {cartTotalQty > 0 && <span className="wp-count">{cartTotalQty}</span>}
245:             </button>
246: 
247:             <button
248:               className="wp-avatar"
249:               onClick={() => go('account')}
250:               title="الملف التجاري"
251:             >
252:               {ACCOUNT.name.split(' ').map(s => s[0]).slice(0, 2).join('')}
253:             </button>
254:           </div>
255:         </header>
256: 
257:         {/* Auth full page or standard layout */}
258:         {isAuthScreen ? (
259:           <div className="wp-main" style={{ padding: 0 }}>
260:             {renderScreen()}
261:           </div>
262:         ) : (
263:           <div className="wp-layout">
264:             {/* Sidebar */}
265:             <aside className="wp-side">
266:               <div className="wp-side-tag">B2B PORTAL</div>
267: 
268:               {NAV_GROUPS.map((group) => (
269:                 <div key={group.title} className="wp-side-group">
270:                   <div className="wp-side-group-title">{group.title}</div>
271:                   {group.items.map((item) => {
272:                     const isActive = route.screen === item.id ||
273:                       (item.id === 'orders' && route.screen === 'order') ||
274:                       (item.id === 'quotes' && ['quote', 'quoteNew', 'quoteEdit'].includes(route.screen)) ||
275:                       (item.id === 'returns' && ['return', 'returnNew'].includes(route.screen)) ||
276:                       (item.id === 'notices' && ['notice', 'noticeNew'].includes(route.screen));
277:                     const badgeVal =
278:                       item.badge === 'cart' && cartTotalQty > 0
279:                         ? cartTotalQty
280:                         : item.badge === 'notifs' && unreadNotifsCount > 0
281:                         ? unreadNotifsCount
282:                         : null;
283: 
284:                     return (
285:                       <button
286:                         key={item.id}
287:                         className={`wp-side-link ${isActive ? 'is-active' : ''}`}
288:                         onClick={() => go(item.id)}
289:                       >
290:                         <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
291:                           <span className="wp-side-dot" />
292:                           <i className={`fa-solid ${item.icon}`} style={{ width: 18, textAlign: 'center', fontSize: 13 }} />
293:                           <span>{item.label}</span>
294:                         </div>
295:                         {badgeVal && <span className="wp-side-badge num">{badgeVal}</span>}
296:                       </button>
297:                     );
298:                   })}
299:                 </div>
300:               ))}
301: 
302:               <div className="wp-side-foot">
303:                 <button
304:                   className="wp-side-link"
305:                   onClick={logout}
306:                   style={{ color: '#be123c' }}
307:                 >
308:                   <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
309:                     <i className="fa-solid fa-arrow-right-from-bracket" style={{ width: 18, textAlign: 'center' }} />
310:                     <span>تسجيل الخروج</span>
311:                   </div>
312:                 </button>
313:               </div>
314:             </aside>
315: 
316:             {/* Main Content Area */}
317:             <main className="wp-main">
318:               <div className="wp-wrap">
319:                 {renderScreen()}
320:               </div>
321:             </main>
322:           </div>
323:         )}
324: 
325:         {/* Floating Toasts */}
326:         {toasts.length > 0 && (
327:           <div style={{ position: 'fixed', bottom: 24, left: '50%', transform: 'translateX(-50%)', zIndex: 9999, display: 'flex', flexDirection: 'column', gap: 8 }}>
328:             {toasts.map((t) => (
