16: class DashboardController extends Controller
17: {
18:     public function __construct(private readonly WholesalePaymentNoticeService $notices) {}
19: 
20:     public function index(Request $request): JsonResponse
21:     {
22:         /** @var Customer $customer */
23:         $customer = $request->user();
24: 
25:         $usedCredit = $this->notices->outstandingBalance($customer);
26:         $creditLimit = (float) $customer->credit_limit;
27: 
28:         $inProgress = Order::query()
29:             ->where('customer_id', $customer->id)
30:             ->whereIn('status', [
31:                 OrderStatus::Pending->value,
32:                 OrderStatus::Confirmed->value,
33:                 OrderStatus::Processing->value,
34:                 OrderStatus::Shipped->value,
35:             ])
36:             ->count();
37: 
38:         $latestInvoices = Order::query()
39:             ->where('customer_id', $customer->id)
40:             ->where(fn ($q) => $q->where('payment_method', 'credit')->orWhere('payment_status', 'paid'))
41:             ->latest('id')
42:             ->limit(5)
43:             ->get(['id', 'order_number', 'status', 'payment_method', 'payment_status', 'grand_total', 'created_at'])
44:             ->map(fn (Order $order) => [
45:                 'id' => $order->id,
46:                 'order_number' => $order->order_number,
47:                 'status' => $order->status->value,
48:                 'payment_method' => $order->payment_method,
49:                 'payment_status' => $order->payment_status,
50:                 'grand_total' => $order->grand_total,
51:                 'created_at' => $order->created_at?->toIso8601String(),
52:             ]);
53: 
54:         $latestQuotations = Quotation::query()
55:             ->where('customer_id', $customer->id)
56:             ->latest('id')
57:             ->limit(5)
58:             ->get(['id', 'quotation_number', 'status', 'grand_total', 'valid_until', 'created_at'])
59:             ->map(fn (Quotation $quotation) => [
60:                 'id' => $quotation->id,
61:                 'quotation_number' => $quotation->quotation_number,
62:                 'status' => $quotation->status->value,
63:                 'grand_total' => $quotation->grand_total,
64:                 'valid_until' => $quotation->valid_until?->toDateString(),
65:                 'created_at' => $quotation->created_at?->toIso8601String(),
66:             ]);
67: 
68:         return response()->json([
69:             'data' => [
70:                 'credit_limit' => number_format($creditLimit, 2, '.', ''),
71:                 'used_credit' => number_format($usedCredit, 2, '.', ''),
72:                 'available_credit' => number_format(max(0.0, $creditLimit - $usedCredit), 2, '.', ''),
73:                 'in_progress_orders_count' => $inProgress,
74:                 'latest_invoices' => $latestInvoices,
75:                 'latest_quotations' => $latestQuotations,
76:             ],
77:         ]);
78:     }
79: } 1: <?php
