 5: namespace App\Http\Controllers\Api\V1\Wholesale;
 6: 
 7: use App\Http\Controllers\Controller;
 8: use App\Imports\WholesaleQuickOrderImport;
 9: use App\Models\Customer;
10: use App\Services\WholesaleQuickOrderService;
11: use Illuminate\Http\JsonResponse;
12: use Illuminate\Http\Request;
13: use Maatwebsite\Excel\Facades\Excel;
14: 
15: class QuickOrderController extends Controller
16: {
17:     public function __construct(private readonly WholesaleQuickOrderService $service) {}
18: 
19:     /** بحث جماعي بالأكواد مع الكميات: أسعار الشرائح والتوفر لكل بند. */
20:     public function lookup(Request $request): JsonResponse
21:     {
22:         $validated = $request->validate([
23:             'items' => ['required', 'array', 'min:1', 'max:500'],
24:             'items.*.sku' => ['nullable', 'string', 'max:255', 'required_without:items.*.barcode'],
25:             'items.*.barcode' => ['nullable', 'string', 'max:255'],
26:             'items.*.qty' => ['required', 'numeric', 'gt:0', 'max:1000000'],
27:         ]);
28: 
29:         /** @var Customer $customer */
30:         $customer = $request->user();
31:         $lines = $this->service->lookup($customer, $validated['items']);
32: 
33:         return response()->json([
34:             'data' => $lines,
35:             'meta' => [
36:                 'found' => collect($lines)->where('found', true)->count(),
37:                 'total' => collect($lines)->where('found', true)->sum('line_total'),
38:             ],
39:         ]);
40:     }
41: 
42:     /**
43:      * استيراد ملف (sku, qty) إلى سلة التاجر مباشرة مع تقرير بالمضاف
44:      * والمتخطى (كود غير معروف أو مخزون لا يغطي).
45:      */
46:     public function import(Request $request): JsonResponse
47:     {
48:         $request->validate([
49:             'file' => ['required', 'file', 'mimes:xlsx,xls,csv,txt', 'max:5120'],
50:         ]);
51: 
52:         /** @var Customer $customer */
53:         $customer = $request->user();
54: 
55:         $import = new WholesaleQuickOrderImport;
56:         Excel::import($import, $request->file('file'));
57: 
58:         $rows = $this->normalizeRows($import->rows);
59:         $report = $this->service->importToCart($customer, $rows);
60: 
61:         return response()->json(['data' => $report]);
62:     }
63: 
64:     /**
65:      * صفوف الملف إلى [{sku, qty}] — يقبل صف ترويسة sku/qty بأي حالة أحرف
66:      * أو صفوفًا رقمية بلا ترويسة (العمود الأول SKU والثاني الكمية).
67:      *
68:      * @return list<array{sku: string, qty: float}>
69:      */
70:     private function normalizeRows(array $sheet): array
71:     {
72:         $rows = [];
73:         foreach ($sheet as $index => $row) {
74:             $values = array_values($row);
75: 
76:             if ($index === 0) {
77:                 $header = collect($values)->map(fn ($v) => strtolower(trim((string) $v)))->all();
78:                 if (in_array('sku', $header, true)) {
79:                     continue; // صف الترويسة
80:                 }
81:             }
82: 
83:             $sku = isset($values[0]) ? trim((string) $values[0]) : '';
84:             $qty = isset($values[1]) && is_numeric($values[1]) ? (float) $values[1] : 0.0;
85:             if ($sku === '' || $qty <= 0) {
86:                 continue;
87:             }
88: 
89:             $rows[] = ['sku' => $sku, 'qty' => $qty];
90:         }
91: 
92:         return $rows;
93:     }
94: } 1: <?php
