18: 
19: class QuotationController extends Controller
20: {
21:     public function __construct(private readonly QuotationService $service) {}
22: 
23:     public function index(Request $request): JsonResponse
24:     {
25:         $filters = $request->validate([
26:             'status' => ['nullable', Rule::in(array_column(QuotationStatus::cases(), 'value'))],
27:             'per_page' => ['nullable', 'integer', 'min:1', 'max:100'],
28:         ]);
29: 
30:         $quotations = Quotation::query()
31:             ->where('customer_id', $request->user()->id)
32:             ->with('items.variant.product')
33:             ->when($filters['status'] ?? null, fn ($q, $v) => $q->where('status', $v))
34:             ->latest('id')
35:             ->paginate($filters['per_page'] ?? 15);
36: 
37:         return QuotationResource::collection($quotations)->response();
38:     }
39: 
40:     public function store(StoreQuotationRequest $request): JsonResponse
41:     {
42:         /** @var Customer $customer */
43:         $customer = $request->user();
44:         $quotation = $this->service->create($customer, $request->validated());
45: 
46:         return (new QuotationResource($quotation))->response()->setStatusCode(201);
47:     }
48: 
49:     public function show(Request $request, int $quotation): JsonResponse
50:     {
51:         $model = $this->ownQuotation($request, $quotation);
52: 
53:         return (new QuotationResource($model->load('items.variant.product')))->response();
54:     }
55: 
56:     public function update(UpdateQuotationRequest $request, int $quotation): JsonResponse
57:     {
58:         $model = $this->ownQuotation($request, $quotation);
59: 
60:         return (new QuotationResource($this->service->update($model, $request->validated())))->response();
61:     }
62: 
63:     public function destroy(Request $request, int $quotation): JsonResponse
64:     {
65:         $this->service->deleteDraft($this->ownQuotation($request, $quotation));
66: 
67:         return response()->json(['message' => 'تم حذف مسودة عرض السعر.']);
68:     }
69: 
70:     public function submit(Request $request, int $quotation): JsonResponse
71:     {
72:         return (new QuotationResource($this->service->submit($this->ownQuotation($request, $quotation))))->response();
73:     }
74: 
75:     public function accept(Request $request, int $quotation): JsonResponse
76:     {
77:         return (new QuotationResource($this->service->accept($this->ownQuotation($request, $quotation))))->response();
78:     }
79: 
80:     public function reject(Request $request, int $quotation): JsonResponse
81:     {
82:         return (new QuotationResource($this->service->reject($this->ownQuotation($request, $quotation))))->response();
83:     }
84: 
85:     private function ownQuotation(Request $request, int $id): Quotation
86:     {
87:         return Quotation::query()
88:             ->where('customer_id', $request->user()->id)
89:             ->findOrFail($id);
90:     }
91: } 1: <?php
