 29:   const orderNumber = params.get('order') ?? '';
 30:   // sessionStorage survives refresh in the same tab. A new tab without it
 31:   // falls back to the phone-verified track page (track requires the order phone).
 32:   const [order, setOrder] = useState<StoreOrder | null>(null);
 33:   const [loading, setLoading] = useState(true);
 34:   const token = useAuthStore((s) => s.token);
 35:   const hydrated = useAuthHydrated();
 36:   useEffect(() => {
 37:     if (!hydrated) return;
 38:     let active = true;
 39:     setLoading(true);
 40:     let receipt: StoreOrder | null = null;
 41:     try {
 42:       const raw = sessionStorage.getItem('last_order');
 43:       const parsed = raw ? (JSON.parse(raw) as StoreOrder) : null;
 44:       if (parsed && parsed.order_number === orderNumber && Array.isArray(parsed.items)
 45:         && Number.isFinite(Number(parsed.grand_total))) receipt = parsed;
 46:     } catch { /* Without storage, signed-in shoppers can recover their own receipt. */ }
 47:     setOrder(receipt);
 48:     if (receipt || !token || !orderNumber) { setLoading(false); return; }
 49:     accountEndpoints.orders().then((orders) => {
 50:       if (active) setOrder(orders.find((o) => o.order_number === orderNumber) ?? null);
 51:     }).catch(() => {}).finally(() => { if (active) setLoading(false); });
 52:     return () => { active = false; };
 53:   }, [orderNumber, token, hydrated]);
