 5: namespace App\Http\Controllers\Api\V1\Shared;
 6: 
 7: use App\Http\Controllers\Controller;
 8: use Illuminate\Http\JsonResponse;
 9: use Illuminate\Http\Request;
10: use Illuminate\Support\Str;
11: 
12: /**
13:  * Unified notification controller managing polymorphic in-app alerts across all portals.
14:  */
15: class NotificationController extends Controller
16: {
17:     /**
18:      * Lists paginated notifications for the authenticated notifiable entity with unread count.
19:      *
20:      * @param Request $request Authenticated request
21:      * @return JsonResponse Paginated notifications with meta
22:      */
23:     public function index(Request $request): JsonResponse
24:     {
25:         $user = $request->user();
26:         $page = $user->notifications()->paginate(20);
27: 
28:         return response()->json([
29:             'data' => collect($page->items())->map(fn ($notification) => $this->formatNotification($notification))->all(),
30:             'meta' => [
31:                 'current_page' => $page->currentPage(),
32:                 'last_page' => $page->lastPage(),
33:                 'per_page' => $page->perPage(),
34:                 'total' => $page->total(),
35:                 'unread_count' => $user->unreadNotifications()->count(),
36:             ],
37:         ]);
38:     }
39: 
40:     /**
41:      * Marks a specific notification as read.
42:      *
43:      * @param Request $request Authenticated request
44:      * @param string $id UUID of the notification
45:      * @return JsonResponse Read confirmation and remaining unread count
46:      */
47:     public function markAsRead(Request $request, string $id): JsonResponse
48:     {
49:         abort_unless(Str::isUuid($id), 404);
50:         $notification = $request->user()->notifications()->findOrFail($id);
51:         $notification->markAsRead();
52: 
53:         return response()->json([
54:             'data' => [
55:                 'id' => $notification->id,
56:                 'read_at' => $notification->read_at?->toIso8601String(),
57:             ],
58:             'meta' => ['unread_count' => $request->user()->unreadNotifications()->count()],
59:         ]);
60:     }
61: 
62:     /**
63:      * Bulk marks all unread notifications as read in a single update query.
64:      *
65:      * @param Request $request Authenticated request
66:      * @return JsonResponse Bulk read confirmation
67:      */
68:     public function readAll(Request $request): JsonResponse
69:     {
70:         $request->user()->unreadNotifications()->update(['read_at' => now()]);
71: 
72:         return response()->json([
73:             'data' => ['read_all' => true],
74:             'meta' => ['unread_count' => 0],
75:         ]);
76:     }
77: 
78:     private function formatNotification(mixed $notification): array
79:     {
80:         return [
81:             'id' => $notification->id,
82:             'type' => class_basename($notification->type),
83:             'data' => $notification->data,
84:             'read_at' => $notification->read_at?->toIso8601String(),
85:             'created_at' => $notification->created_at?->toIso8601String(),
86:         ];
87:     }
88: }  1: <?php
