 10: use App\Models\Customer;
 11: use App\Models\Order;
 12: use App\Services\SettingService;
 13: use App\Services\WholesalePaymentNoticeService;
 14: use Barryvdh\DomPDF\Facade\Pdf;
 15: use Illuminate\Http\JsonResponse;
 16: use Illuminate\Http\Request;
 17: use Symfony\Component\HttpFoundation\Response;
 18: 
 19: class InvoiceController extends Controller
 20: {
 21:     public function __construct(
 22:         private readonly WholesalePaymentNoticeService $notices,
 23:         private readonly SettingService $settings,
 24:     ) {}
 25: 
 26:     /** فواتير التاجر: طلباته المسددة والآجلة معًا. */
 27:     public function index(Request $request): JsonResponse
 28:     {
 29:         $filters = $request->validate([
 30:             'payment_status' => ['nullable', 'string', 'in:paid,unpaid'],
 31:             'per_page' => ['nullable', 'integer', 'min:1', 'max:100'],
 32:         ]);
 33: 
 34:         $invoices = Order::query()
 35:             ->where('customer_id', $request->user()->id)
 36:             ->where(fn ($q) => $q->where('payment_method', 'credit')->orWhere('payment_status', 'paid'))
 37:             ->when($filters['payment_status'] ?? null, fn ($q, $v) => $q->where('payment_status', $v))
 38:             ->latest('id')
 39:             ->paginate($filters['per_page'] ?? 15);
 40: 
 41:         $data = $invoices->getCollection()->map(fn (Order $order) => [
 42:             'id' => $order->id,
 43:             'invoice_number' => $order->order_number,
 44:             'order_number' => $order->order_number,
 45:             'status' => $order->status->value,
 46:             'payment_method' => $order->payment_method,
 47:             'payment_status' => $order->payment_status,
 48:             'subtotal' => $order->subtotal,
 49:             'discount_amount' => $order->discount_amount,
 50:             'shipping_cost' => $order->shipping_cost,
 51:             'tax_amount' => $order->tax_amount,
 52:             'grand_total' => $order->grand_total,
 53:             'created_at' => $order->created_at?->toIso8601String(),
 54:             'pdf_url' => url("/api/v1/wholesale/invoices/{$order->id}/pdf"),
 55:         ])->values()->all();
 56: 
 57:         return response()->json([
 58:             'data' => $data,
 59:             'meta' => [
 60:                 'current_page' => $invoices->currentPage(),
 61:                 'last_page' => $invoices->lastPage(),
 62:                 'per_page' => $invoices->perPage(),
 63:                 'total' => $invoices->total(),
 64:             ],
 65:         ]);
 66:     }
 67: 
 68:     /** تنزيل فاتورة طلب التاجر كـ PDF (طلب الغير = 404). */
 69:     public function pdf(Request $request, int $order): Response
 70:     {
 71:         /** @var Customer $customer */
 72:         $customer = $request->user();
 73:         $model = Order::query()
 74:             ->where('customer_id', $customer->id)
 75:             ->with('items')
 76:             ->findOrFail($order);
 77: 
 78:         return Pdf::loadView('pdfs.wholesale_invoice', [
 79:             'company_name' => (string) $this->settings->get('company_name', 'Alfarid'),
 80:             'customer' => $customer,
 81:             'order' => $model,
 82:         ])->download("invoice-{$model->order_number}.pdf");
 83:     }
 84: 
 85:     /** كشف حساب مالي تفصيلي: آجل مدين، سداد ومرتجعات دائنة، رصيد تراكمي. */
 86:     /** رفع إشعار سداد بنكي لمديونية آجلة (نفس خدمة PaymentNoticeController). */
 87:     public function storePaymentNotice(StorePaymentNoticeRequest $request): JsonResponse
 88:     {
 89:         /** @var Customer $customer */
 90:         $customer = $request->user();
 91:         $notice = $this->notices->create($customer, $request->validated(), $request->file('receipt'));
 92: 
 93:         return (new WholesalePaymentNoticeResource($notice->load('order')))->response()->setStatusCode(201);
 94:     }
 95: 
 96:     public function statement(Request $request): JsonResponse
 97:     {
 98:         $validated = $request->validate([
 99:             'from' => ['nullable', 'date'],
100:             'to' => ['nullable', 'date', 'after_or_equal:from'],
101:         ]);
102: 
103:         /** @var Customer $customer */
104:         $customer = $request->user();
105:         $statement = $this->notices->statement($customer, $validated['from'] ?? null, $validated['to'] ?? null);
106: 
107:         return response()->json([
108:             'data' => [
109:                 'opening_balance' => number_format($statement['opening_balance'], 2, '.', ''),
110:                 'closing_balance' => number_format($statement['closing_balance'], 2, '.', ''),
111:                 'entries' => $statement['entries'],
112:             ],
113:         ]);
114:     }
