 7: use App\Enums\CustomerStatus;
 8: use App\Exceptions\BusinessException;
 9: use App\Models\Customer;
10: use App\Models\CustomerWalletTransaction;
11: use Illuminate\Support\Facades\DB;
12: 
13: /**
14:  * Manages customer wallet balance and immutable ledger transactions.
15:  *
16:  * All balance adjustments are computed using integer cents to prevent floating-point
17:  * rounding errors, guarded by pessimistic locking and idempotency uniqueness checks.
18:  */
19: class WalletService
20: {
21:     /**
22:      * Record a debit or credit transaction on a customer's wallet ledger.
23:      *
24:      * @param  int  $customerId
25:      * @param  float  $amount  Positive for credit/top-up, negative for debit/payment
26:      * @param  string  $type  Transaction type (e.g. checkout_payment, refund, adjustment)
27:      * @param  string  $referenceType  Morph class or table name of the triggering source
28:      * @param  int  $referenceId  ID of the triggering source record
29:      * @param  int|null  $createdBy  User ID if triggered by an administrator
30:      * @return CustomerWalletTransaction
31:      *
32:      * @throws BusinessException
33:      */
34:     public function record(int $customerId, float $amount, string $type, string $referenceType, int $referenceId, ?int $createdBy = null): CustomerWalletTransaction
35:     {
36:         return DB::transaction(function () use ($customerId, $amount, $type, $referenceType, $referenceId, $createdBy): CustomerWalletTransaction {
37:             // Lock customer row to serialize concurrent debits/credits on the same balance
38:             $customer = Customer::query()->lockForUpdate()->findOrFail($customerId);
39:             if ($type === 'checkout_payment' && $customer->status !== CustomerStatus::Approved) {
40:                 throw new BusinessException('الدفع بالمحفظة يتطلب حساب عميل نشطًا.');
41:             }
42:             // Enforce idempotency: prevent duplicate ledger entries for the same reference event
43:             if (CustomerWalletTransaction::query()->where('reference_type', $referenceType)->where('reference_id', $referenceId)->where('type', $type)->exists()) {
44:                 throw new BusinessException('حركة المحفظة مسجلة سابقًا.', [], 409);
45:             }
46:             // Calculate balances in integer cents to eliminate floating-point drift
47:             $amountCents = (int) round($amount * 100);
48:             $balanceCents = (int) round((float) $customer->wallet_balance * 100) + $amountCents;
49:             if ($balanceCents < 0) {
50:                 throw new BusinessException('رصيد المحفظة لا يكفي قيمة الطلب كاملة.');
51:             }
52:             if ($balanceCents > 999999999999) {
53:                 throw new BusinessException('رصيد المحفظة يتجاوز الحد المسموح.');
54:             }
55:             $entry = CustomerWalletTransaction::create([
56:                 'customer_id' => $customerId, 'type' => $type, 'amount' => $amountCents / 100,
57:                 'balance_after' => $balanceCents / 100, 'reference_type' => $referenceType,
58:                 'reference_id' => $referenceId, 'created_by' => $createdBy,
59:             ]);
60:             $customer->forceFill(['wallet_balance' => $balanceCents / 100])->save();
61: 
62:             return $entry;
63:         });
64:     }
65: }  1: <?php
