  5: namespace App\Services;
  6: 
  7: use App\Enums\ProductStatus;
  8: use App\Exceptions\BusinessException;
  9: use App\Models\Customer;
 10: use App\Models\Order;
 11: use App\Models\ProductVariant;
 12: use App\Models\StockLevel;
 13: use Illuminate\Support\Collection;
 14: 
 15: /**
 16:  * Quick-order service for wholesale customers.
 17:  * Handles bulk code lookups (with tiered pricing and stock availability), cart imports, and order re-ordering.
 18:  * All cart additions route through CartService to guarantee current real-time pricing.
 19:  */
 20: class WholesaleQuickOrderService
 21: {
 22:     public function __construct(
 23:         private readonly PricingService $pricing,
 24:         private readonly CartService $carts,
 25:     ) {}
 26: 
 27:     /**
 28:      * Batch lookup product variants by SKU or barcode with quantity-tier pricing and total available stock.
 29:      *
 30:      * @param  list<array{sku?: string|null, barcode?: string|null, qty: float}>  $lines
 31:      * @return list<array<string, mixed>>
 32:      */
 33:     public function lookup(Customer $customer, array $lines): array
 34:     {
 35:         $variants = $this->findVariants($lines);
 36:         $availability = $this->availabilityFor($variants->pluck('id')->all());
 37:         // F17: one context for the whole lookup, not one group query per line.
 38:         $ctx = $this->pricing->contextFor($customer, $variants->pluck('id')->unique()->all());
 39: 
 40:         return collect($lines)->map(function (array $line) use ($customer, $variants, $availability, $ctx): array {
 41:             $code = (string) ($line['sku'] ?? $line['barcode'] ?? '');
 42:             $variant = $variants->get($code);
 43:             $qty = (float) $line['qty'];
 44: 
 45:             if ($variant === null) {
 46:                 return [
 47:                     'code' => $code, 'found' => false, 'qty' => $qty,
 48:                     'available_qty' => 0.0, 'in_stock' => false,
 49:                 ];
 50:             }
 51: 
 52:             $available = $availability[$variant->id] ?? 0.0;
 53:             $unitPrice = $this->pricing->resolve($variant, $customer, $qty, null, $ctx)['unit_price'];
 54: 
 55:             return [
 56:                 'code' => $code,
 57:                 'found' => true,
 58:                 'product_variant_id' => $variant->id,
 59:                 'sku' => $variant->sku,
 60:                 'barcode' => $variant->barcode,
 61:                 'product_name' => $variant->product?->name_ar,
 62:                 'qty' => $qty,
 63:                 'unit_price' => $unitPrice,
 64:                 'line_total' => round($unitPrice * $qty, 2),
 65:                 'tier_prices' => $this->pricing->tiersFor($variant, $customer, $ctx),
 66:                 'available_qty' => $available,
 67:                 'in_stock' => $available >= $qty,
 68:             ];
 69:         })->all();
 70:     }
 71: 
 72:     /**
 73:      * Import multiple items from a parsed CSV/Excel file into the customer's active cart.
 74:      * Skips invalid codes or lines exceeding available stock with explanatory status reports.
 75:      *
 76:      * @param  list<array{sku: string, qty: float}>  $rows
 77:      * @return array{added: list<array<string, mixed>>, skipped: list<array<string, mixed>>, cart: array<string, mixed>}
 78:      */
 79:     public function importToCart(Customer $customer, array $rows): array
 80:     {
 81:         // Consolidate duplicate codes within the input before running stock availability checks
 82:         $merged = [];
 83:         foreach ($rows as $row) {
 84:             $sku = trim((string) $row['sku']);
 85:             if ($sku === '') {
 86:                 continue;
 87:             }
 88:             $merged[$sku] = ($merged[$sku] ?? 0.0) + (float) $row['qty'];
 89:         }
 90: 
 91:         $lines = collect($merged)->map(fn (float $qty, string $sku) => ['sku' => $sku, 'qty' => $qty])->values()->all();
 92:         $variants = $this->findVariants($lines);
 93:         $availability = $this->availabilityFor($variants->pluck('id')->all());
 94: 
 95:         $cart = $this->carts->resolveCart($customer, null);
 96:         $inCart = $cart->items()->pluck('qty', 'product_variant_id')->map(fn ($q) => (float) $q)->all();
 97: 
 98:         // F17: one context for the whole import, not one group query per line.
 99:         $ctx = $this->pricing->contextFor($customer, $variants->pluck('id')->unique()->all());
100: 
101:         $added = [];
102:         $skipped = [];
103:         foreach ($lines as $line) {
104:             $variant = $variants->get($line['sku']);
105: 
106:             if ($variant === null) {
107:                 $skipped[] = ['sku' => $line['sku'], 'qty' => $line['qty'], 'reason' => 'not_found_or_inactive'];
108: 
109:                 continue;
110:             }
111: 
112:             $alreadyInCart = $inCart[$variant->id] ?? 0.0;
113:             if (($availability[$variant->id] ?? 0.0) < $alreadyInCart + $line['qty']) {
114:                 $skipped[] = ['sku' => $line['sku'], 'qty' => $line['qty'], 'reason' => 'insufficient_stock'];
115: 
116:                 continue;
117:             }
118: 
119:             $cart = $this->carts->addItem($cart, $customer, $variant->id, $line['qty']);
120:             $inCart[$variant->id] = $alreadyInCart + $line['qty'];
121:             $added[] = [
122:                 'sku' => $variant->sku,
123:                 'product_variant_id' => $variant->id,
124:                 'qty' => $line['qty'],
125:                 'unit_price' => $this->pricing->resolve($variant, $customer, $inCart[$variant->id], null, $ctx)['unit_price'],
126:             ];
127:         }
128: 
129:         return [
130:             'added' => $added,
131:             'skipped' => $skipped,
132:             'cart' => $this->carts->present($cart, $customer),
133:         ];
134:     }
135: 
136:     /**
137:      * Copy lines from a previous order into the customer's current cart at today's real-time prices.
138:      * Skips items that are discontinued, unpublished, or out of stock.
139:      *
140:      * @return array{added: list<array<string, mixed>>, skipped: list<array<string, mixed>>, cart: array<string, mixed>}
141:      */
142:     public function reorderToCart(Customer $customer, Order $order): array
143:     {
144:         if ($order->customer_id !== $customer->id) {
145:             throw new BusinessException('الطلب غير موجود أو لا يخص هذا التاجر.', [], 404);
146:         }
147: 
148:         $rows = $order->items()
149:             ->get()
150:             ->groupBy('product_variant_id')
151:             ->map(fn (Collection $items, int $variantId) => [
152:                 'sku' => (string) ($items->first()->sku_snapshot ?? ''),
153:                 'qty' => (float) $items->sum('qty'),
154:                 'variant_id' => $variantId,
155:             ])
156:             ->values()
157:             ->all();
158: 
159:         // Mirror the import flow keyed by current variant ID rather than historical snapshot SKU
160:         $cart = $this->carts->resolveCart($customer, null);
161:         $inCart = $cart->items()->pluck('qty', 'product_variant_id')->map(fn ($q) => (float) $q)->all();
162:         $variants = ProductVariant::query()->with('product')
163:             ->whereIn('id', collect($rows)->pluck('variant_id')->all())
164:             ->get()->keyBy('id');
165:         $availability = $this->availabilityFor($variants->pluck('id')->all());
166:         $ctx = $this->pricing->contextFor($customer, $variants->pluck('id')->all());
167: 
168:         $added = [];
169:         $skipped = [];
170:         foreach ($rows as $row) {
171:             $variant = $variants->get($row['variant_id']);
172: 
173:             if ($variant === null || ! $variant->is_active || $variant->product?->status !== ProductStatus::Published) {
174:                 $skipped[] = ['sku' => $row['sku'], 'qty' => $row['qty'], 'reason' => 'not_found_or_inactive'];
175: 
176:                 continue;
177:             }
178: 
179:             $alreadyInCart = $inCart[$variant->id] ?? 0.0;
180:             if (($availability[$variant->id] ?? 0.0) < $alreadyInCart + $row['qty']) {
181:                 $skipped[] = ['sku' => $row['sku'], 'qty' => $row['qty'], 'reason' => 'insufficient_stock'];
182: 
183:                 continue;
184:             }
185: 
186:             $cart = $this->carts->addItem($cart, $customer, $variant->id, $row['qty']);
187:             $inCart[$variant->id] = $alreadyInCart + $row['qty'];
188:             $added[] = [
189:                 'sku' => $variant->sku,
190:                 'product_variant_id' => $variant->id,
191:                 'qty' => $row['qty'],
192:                 'unit_price' => $this->pricing->resolve($variant, $customer, $inCart[$variant->id], null, $ctx)['unit_price'],
193:             ];
194:         }
195: 
196:         return [
197:             'added' => $added,
198:             'skipped' => $skipped,
199:             'cart' => $this->carts->present($cart, $customer),
200:         ];
201:     }
202: 
203:     /**
204:      * Map active variants of published products by SKU and barcode.
205:      *
206:      * @param  list<array{sku?: string|null, barcode?: string|null}>  $lines
207:      * @return Collection<string, ProductVariant>
208:      */
209:     private function findVariants(array $lines): Collection
210:     {
211:         $skus = collect($lines)->pluck('sku')->filter()->unique()->all();
212:         $barcodes = collect($lines)->pluck('barcode')->filter()->unique()->all();
213: 
214:         $variants = ProductVariant::query()->with('product')
215:             ->where('is_active', true)
216:             ->whereHas('product', fn ($q) => $q->where('status', 'published'))
217:             ->where(function ($q) use ($skus, $barcodes): void {
218:                 if ($skus !== []) {
219:                     $q->orWhereIn('sku', $skus);
220:                 }
221:                 if ($barcodes !== []) {
222:                     $q->orWhereIn('barcode', $barcodes);
223:                 }
224:             })
225:             ->get();
226: 
227:         $map = collect();
228:         foreach ($variants as $variant) {
229:             $map->put($variant->sku, $variant);
230:             if ($variant->barcode !== null && $variant->barcode !== '') {
231:                 $map->put($variant->barcode, $variant);
232:             }
233:         }
234: 
235:         return $map;
236:     }
237: 
238:     /**
239:      * Total available stock across all branches for a given list of variant IDs.
240:      *
241:      * @param  list<int>  $variantIds
242:      * @return array<int, float>
243:      */
244:     private function availabilityFor(array $variantIds): array
245:     {
246:         if ($variantIds === []) {
247:             return [];
248:         }
249: 
250:         return StockLevel::query()
251:             ->whereIn('product_variant_id', $variantIds)
252:             ->groupBy('product_variant_id')
253:             ->selectRaw('product_variant_id, SUM(available) AS total_available')
254:             ->pluck('total_available', 'product_variant_id')
255:             ->map(fn ($v) => (float) $v)
256:             ->all();
257:     }
