22: class OrderController extends Controller
23: {
24:     public function __construct(private readonly OrderService $orders) {}
25: 
26:     /** تتبع عام: رقم الطلب + رقم هاتف الطلب للتحقق. */
27:     public function track(Request $request, string $number): TrackOrderResource
28:     {
29:         $request->validate(['phone' => ['required', 'string', 'max:50']]);
30: 
31:         $order = Order::query()
32:             ->where('order_number', $number)
33:             ->with(['items', 'statusHistories'])
34:             ->first();
35: 
36:         // مقارنة بعد توحيد صيغة الهاتف على الجانبين (M5)
