50:     {
51:         /** @var Customer $customer */
52:         $customer = $request->user();
53: 
54:         $orders = Order::query()
55:             ->where('customer_id', $customer->id)
56:             ->with('items')
57:             ->latest('id')
58:             ->paginate(15);
59: 
60:         return OrderResource::collection($orders);
61:     }
62: 
63:     public function cancel(Request $request, int $order): OrderResource
64:     {
65:         /** @var Customer $customer */
66:         $customer = $request->user();
67: 
68:         $order = Order::query()->where('customer_id', $customer->id)->findOrFail($order);
69: 
70:         if (! in_array($order->status, [OrderStatus::Pending, OrderStatus::Confirmed], true)) {
71:             throw new BusinessException('لا يمكن إلغاء الطلب في حالته الحالية؛ الإلغاء متاح قبل بدء التجهيز والشحن فقط.');
72:         }
73: 
74:         // الفحص على النسخة المقفولة داخل changeStatus (F-11): الفحص أعلاه
