13: /**
14:  * Generates customer-specific wholesale price list export rows.
15:  * Acts as the single source of truth for both Excel and PDF price list exports.
16:  */
17: class WholesalePriceListService
18: {
19:     public function __construct(private readonly PricingService $pricing) {}
20: 
21:     /**
22:      * Build tabular pricing and availability rows for all active variants for the given customer.
23:      *
24:      * @return list<array{sku: string, barcode: string|null, product_name: string|null, base_price: float|null, wholesale_price: float|null, tier_prices: list<array{min_qty: float, unit_price: float}>, available_qty: float}>
25:      */
26:     public function rows(Customer $customer): array
27:     {
28:         $variants = ProductVariant::query()->with('product')
29:             ->where('is_active', true)
30:             ->whereHas('product', fn ($q) => $q->where('status', ProductStatus::Published->value))
31:             ->orderBy('sku')
32:             ->get();
33: 
34:         $availability = StockLevel::query()
35:             ->whereIn('product_variant_id', $variants->pluck('id')->all())
36:             ->groupBy('product_variant_id')
37:             ->selectRaw('product_variant_id, SUM(available) AS total_available')
38:             ->pluck('total_available', 'product_variant_id')
39:             ->map(fn ($v) => (float) $v)
40:             ->all();
41: 
42:         // F17: one context for the whole export, not one group lookup per row.
43:         $ctx = $this->pricing->contextFor($customer, $variants->pluck('id')->all());
44: 
45:         return $variants->map(function (ProductVariant $variant) use ($customer, $availability, $ctx): array {
46:             try {
47:                 $resolved = $this->pricing->resolve($variant, $customer, 1, null, $ctx);
48:                 $price = $resolved['unit_price'];
49:                 $base = $resolved['base_price'];
50:                 $tiers = $this->pricing->tiersFor($variant, $customer, $ctx);
51:             } catch (BusinessException) {
52:                 // Unpriced variant: emit with null price rather than failing the entire export
53:                 $price = null;
54:                 $base = $variant->retail_price !== null ? (float) $variant->retail_price : null;
55:                 $tiers = [];
56:             }
57: 
58:             return [
59:                 'sku' => $variant->sku,
60:                 'barcode' => $variant->barcode,
61:                 'product_name' => $variant->product?->name_ar,
62:                 'base_price' => $base,
63:                 'wholesale_price' => $price,
64:                 'tier_prices' => $tiers,
65:                 'available_qty' => $availability[$variant->id] ?? 0.0,
66:             ];
67:         })->all();
68:     }
