 51: let queue: Promise<unknown> = Promise.resolve();
 52: let volatileSession: string | null = null;
 53: export function clearGuestCartSession() {
 54:   volatileSession = null;
 55:   try { localStorage.removeItem('cart_session'); } catch { /* Storage may be blocked. */ }
 56: }
 57: const identity = () => viewerKey(getAuthToken());
 58: const session = () => {
 59:   try { return localStorage.getItem('cart_session') ?? volatileSession; } catch { return volatileSession; }
 60: };
 61: 
 62: export const getCartSession = session;
 63: export function restoreGuestCartSession(value: string) {
 64:   volatileSession = value;
 65:   try { localStorage.setItem('cart_session', value); } catch { /* Volatile fallback remains available. */ }
 66: }
 67: 
 68: const emptyTotals: CartTotals = { subtotal: 0, pricing_discount: 0, items_total: 0, coupon_discount: 0, total: 0, coupon_code: null };
 69: 
 70: export const useCartStore = create<CartState>((set, get) => {
 71:   const apply = (cart: StoreCart) => {
 72:     if (cart.customer_id === null && cart.cart_token) {
 73:       volatileSession = cart.cart_token;
 74:       try { localStorage.setItem('cart_session', cart.cart_token); } catch { /* Keep this tab functional without storage. */ }
 75:     } else if (cart.customer_id !== null) {
