 78:       clearGuestCartSession();
 79:     }
 80:     set({
 81:       items: cart.items.map(item => ({ id: item.id, productId: item.product_id, variantId: item.product_variant_id,
 82:         name: item.product_name || item.product_name_en || item.sku || 'Product', price: item.unit_price,
 83:         // L7: the backend ceiling (min of sellable stock and the identity
