 85:         quantity: Number(item.qty), available: Number(item.max_qty ?? item.available),
 86:         image: item.image ?? null, slug: item.product_slug ?? null,
 87:         color: item.color ?? null, size: item.size ?? null,
 88:         priced: item.priced, lineTotal: Number(item.line_total ?? 0) })),
 89:       serverTotal: Number(cart.totals.total),
 90:       totals: { ...cart.totals },
 91:       couponCode: cart.totals.coupon_code,
 92:     });
 93:   };
 94:   const run = (operation: () => Promise<StoreCart>, mutation: boolean): Promise<boolean> => {
 95:     const owner = identity();
 96:     if (get().identity !== owner) set({ items: [], serverTotal: 0, totals: { ...emptyTotals }, couponCode: null, identity: owner, error: null });
 97:     const execute = async (): Promise<boolean> => {
 98:       if (owner !== identity()) return false;
 99:       set({ busy: mutation, loading: !mutation, error: null });
100:       try {
101:         const cart = await operation();
102:         if (owner !== identity()) return false;
103:         apply(cart);
104:         if (mutation) {
105:           try { localStorage.setItem('cart_updated_at', `${Date.now()}:${Math.random()}`); } catch { /* Cross-tab sync is optional when storage is blocked. */ }
106:         }
107:         return true;
108:       } catch (error) {
109:         if (owner === identity()) {
110:           const message = (error as { response?: { data?: { message?: string } } }).response?.data?.message;
111:           set({ error: message || 'We could not update your cart. Please try again.' });
112:         }
113:         return false;
114:       } finally {
115:         set({ busy: false, loading: false });
116:       }
117:     };
118:     const task = queue.then(async (): Promise<boolean> => {
119:       if (typeof navigator !== 'undefined' && navigator.locks) return Boolean(await navigator.locks.request('alfarid-store-cart', execute));
120:       return execute();
121:     });
122:     queue = task.catch(() => {});
123:     return task;
124:   };
125:   return {
126:     items: [], busy: false, loading: false, error: null, serverTotal: 0,
127:     totals: null, couponCode: null, identity: 'guest',
128:     loadCart: () => run(() => cartEndpoints.get(session()), false),
129:     addItem: (variantId, quantity) => {
130:       const qty = quantity ?? 1;
131:       if (!Number.isInteger(qty) || qty < 1) return Promise.resolve(false);
132:       return run(() => cartEndpoints.add(variantId, qty, session()), true);
133:     },
134:     removeItem: (id) => run(() => cartEndpoints.remove(id, session()), true),
135:     updateQuantity: (id, qty) => {
136:       if (!Number.isInteger(qty) || qty < 0) return Promise.resolve(false);
137:       const item = get().items.find((item) => item.id === id);
138:       if (qty > 0 && item && qty > item.available) return Promise.resolve(false);
139:       return run(() => cartEndpoints.update(id, qty, session()), true);
140:     },
141:     clearCart: () => run(() => cartEndpoints.clear(session()), true),
142:     applyCoupon: (code) => run(() => cartEndpoints.applyCoupon(code, session()).then((res) => res.cart), true),
143:     removeCoupon: () => run(() => cartEndpoints.removeCoupon(session()), true),
144:     total: () => get().serverTotal,
145:   };
146: });
