31:     public function register(RegisterRequest $request): JsonResponse
32:     {
33:         [$customer, $token] = DB::transaction(function () use ($request): array {
34:             $customer = $this->auth->registerRetail($request->validated());
35: 
36:             return [$customer, $this->auth->issueToken($customer, 'store-token')];
37:         });
38: 
39:         // حساب جديد = دخول فوري: تُدمج سلة الزائر إن وُجدت
40:         $this->carts->mergeGuestCart($customer, $request->header('X-Cart-Session'));
41: 
42:         return CustomerResource::make($customer)
43:             ->additional(['message' => 'تم إنشاء حسابك بنجاح', 'token' => $token])
44:             ->response()
45:             ->setStatusCode(201);
46:     }
