48:     public function login(LoginRequest $request): CustomerResource
49:     {
50:         $customer = $this->auth->login($request->validated()['login'], $request->validated()['password']);
51:         $token = $this->auth->issueToken($customer, 'store-token');
52: 
53:         // دمج سلة الزائر (إن وُجدت بهيدر الجلسة) في سلة الحساب تلقائيًا
54:         $this->carts->mergeGuestCart($customer, $request->header('X-Cart-Session'));
55: 
56:         return CustomerResource::make($customer)
57:             ->additional(['message' => 'تم تسجيل الدخول بنجاح', 'token' => $token]);
58:     }
