60:     /** خروج: حذف التوكن الحالي فقط (بقية الجلسات على أجهزة أخرى تظل فعالة). */
61:     public function logout(Request $request): JsonResponse
62:     {
63:         $request->user()->currentAccessToken()->delete();
64: 
65:         return response()->json(['message' => 'تم تسجيل الخروج بنجاح']);
