 27: class ProductController extends Controller
 28: {
 29:     public function __construct(
 30:         private readonly PricingService $pricing,
 31:         private readonly WholesalePriceListService $priceList,
 32:         private readonly SettingService $settings,
 33:     ) {}
 34: 
 35:     /** كتالوج الجملة: لكل متغير سعر هذا التاجر وشرائح كمياته والمتاح. */
 36:     public function index(Request $request): JsonResponse
 37:     {
 38:         $filters = $request->validate([
 39:             'search' => ['nullable', 'string', 'max:255'],
 40:             'per_page' => ['nullable', 'integer', 'min:1', 'max:100'],
 41:         ]);
 42: 
 43:         /** @var Customer $customer */
 44:         $customer = $request->user();
 45: 
 46:         $products = Product::query()
 47:             // M6: wholesale sees wholesale-channel products only, on active
 48:             // category paths (mirrors the storefront's publishedQuery guards).
 49:             ->where('status', 'published')
 50:             ->whereIn('sales_channel', [SalesChannel::Wholesale, SalesChannel::Both])
 51:             ->whereHas('category', fn ($q) => $q->where('is_active', true)
 52:                 ->whereDoesntHave('parent', fn ($parent) => $parent->where('is_active', false)
 53:                     ->orWhereHas('parent', fn ($ancestor) => $ancestor->where('is_active', false))))
 54:             ->with(['variants' => fn ($q) => $q->where('is_active', true)])
 55:             ->when($filters['search'] ?? null, function ($q, $v): void {
 56:                 $pattern = SearchTerm::pattern($v);
 57:                 $q->where(fn ($sub) => $sub
 58:                     ->whereLike('name_ar', $pattern, caseSensitive: false)
 59:                     ->orWhereLike('name_en', $pattern, caseSensitive: false)
 60:                     ->orWhereHas('variants', fn ($qv) => $qv->whereLike('sku', $pattern, caseSensitive: false)));
 61:             })
 62:             ->latest('id')
 63:             ->paginate($filters['per_page'] ?? 15);
 64: 
 65:         $variantIds = $products->getCollection()
 66:             ->flatMap(fn (Product $product) => $product->variants->pluck('id'))
 67:             ->all();
 68: 
 69:         // M6: availability counts active branches only, like the storefront.
 70:         $availability = StockLevel::query()
 71:             ->join('branches', 'branches.id', '=', 'stock_levels.branch_id')
 72:             ->where('branches.is_active', true)
 73:             ->whereIn('product_variant_id', $variantIds)
 74:             ->groupBy('product_variant_id')
 75:             ->selectRaw('product_variant_id, SUM(available) AS total_available')
 76:             ->pluck('total_available', 'product_variant_id')
 77:             ->map(fn ($v) => (float) $v)
 78:             ->all();
 79: 
 80:         // F17: customer price-list context is identical for every variant on
 81:         // this page — load it once instead of per variant.
 82:         $pricingCtx = $this->pricing->contextFor($customer, $variantIds);
 83: 
 84:         $data = $products->getCollection()->map(fn (Product $product) => [
 85:             'id' => $product->id,
 86:             'name' => $product->name_ar,
 87:             'name_en' => $product->name_en,
 88:             'variants' => $product->variants->map(function (ProductVariant $variant) use ($customer, $availability, $pricingCtx): array {
 89:                 try {
 90:                     $resolved = $this->pricing->resolve($variant, $customer, 1, null, $pricingCtx);
 91:                     $price = $resolved['unit_price'];
 92:                     $base = $resolved['base_price'];
 93:                     $tiers = $this->pricing->tiersFor($variant, $customer, $pricingCtx);
 94:                 } catch (BusinessException) {
 95:                     $price = null;
 96:                     $base = $variant->retail_price !== null ? (float) $variant->retail_price : null;
 97:                     $tiers = [];
 98:                 }
 99: 
100:                 return [
101:                     'id' => $variant->id,
102:                     'sku' => $variant->sku,
103:                     'barcode' => $variant->barcode,
104:                     'base_price' => $base,
105:                     'your_price' => $price,
106:                     'tier_prices' => $tiers,
107:                     'available_qty' => $availability[$variant->id] ?? 0.0,
108:                 ];
109:             })->values()->all(),
110:         ])->values()->all();
111: 
112:         return response()->json([
113:             'data' => $data,
114:             'meta' => [
115:                 'current_page' => $products->currentPage(),
116:                 'last_page' => $products->lastPage(),
117:                 'per_page' => $products->perPage(),
118:                 'total' => $products->total(),
119:             ],
120:         ]);
121:     }
122: 
123:     /** تصدير قائمة أسعار التاجر: xlsx منسق أو PDF بترويسة الشركة وصلاحية. */
124:     public function exportPriceList(Request $request): BinaryFileResponse|Response
125:     {
126:         $validated = $request->validate([
127:             'format' => ['required', Rule::in(['pdf', 'xlsx'])],
128:         ]);
129: 
130:         /** @var Customer $customer */
131:         $customer = $request->user();
132:         $rows = $this->priceList->rows($customer);
133: 
134:         if ($validated['format'] === 'xlsx') {
135:             return Excel::download(new WholesalePriceListExport($rows), 'price-list.xlsx');
136:         }
137: 
138:         $validUntil = now()->addDays(30);
139: 
140:         return Pdf::loadView('pdfs.wholesale_price_list', [
141:             'company_name' => (string) $this->settings->get('company_name', 'Alfarid'),
142:             'customer' => $customer,
143:             'rows' => $rows,
144:             'valid_until' => $validUntil,
145:             'generated_at' => now(),
146:         ])->download('price-list.pdf');
147:     }
