12: /** تقديم طلب إرجاع من حساب العميل — مع صور عيوب اختيارية لكل بند. */
13: class StoreReturnRequest extends FormRequest
14: {
15:     public function authorize(): bool
16:     {
17:         return true;
18:     }
19: 
20:     /**
21:      * @return array<string, mixed>
22:      */
23:     public function rules(): array
24:     {
25:         return [
26:             'order_id' => ['required', 'integer'],
27:             'reason' => ['required', 'string', 'max:2000'],
28:             'refund_method' => ['nullable', Rule::enum(RefundMethod::class)],
29:             'items' => ['required', 'array', 'min:1', 'max:50'],
30:             'items.*.order_item_id' => ['required', 'integer', 'distinct'],
31:             'items.*.requested_qty' => ['required', 'integer', 'gt:0', 'max:99999999'],
32:             'items.*.item_reason' => ['nullable', 'string', 'max:255'],
33:             'items.*.attachments' => ['nullable', 'array', 'max:5'],
34:             'items.*.attachments.*' => ['file', 'image', 'mimes:jpg,jpeg,png,webp', 'max:5120'],
35:         ];
36:     }
37: 
38:     public function withValidator(Validator $validator): void
39:     {
40:         $validator->after(function (Validator $validator): void {
41:             $files = 0;
42:             $kilobytes = 0;
43:             foreach (array_keys($this->input('items', []) ?? []) as $index) {
44:                 $itemFiles = $this->file("items.{$index}.attachments");
45:                 $itemFiles = is_array($itemFiles) ? $itemFiles : ($itemFiles !== null ? [$itemFiles] : []);
46:                 foreach ($itemFiles as $file) {
47:                     if (! is_object($file) || ! method_exists($file, 'getSize')) {
48:                         continue;
49:                     }
50:                     $files++;
51:                     $kilobytes += (int) ceil($file->getSize() / 1024);
52:                 }
53:             }
54:             if ($files > 10) {
55:                 $validator->errors()->add('items', 'الحد الأقصى لمرفقات طلب الإرجاع 10 ملفات.');
56:             }
57:             if ($kilobytes > 25600) {
58:                 $validator->errors()->add('items', 'الحجم الإجمالي لمرفقات طلب الإرجاع يجب ألا يتجاوز 25 ميغابايت.');
59:             }
60:         });
61:     }
62: 
63:     /**
64:      * الحمولة الجاهزة للخدمة: البيانات المتحقق منها + ملفات كل بند.
65:      *
66:      * @return array<string, mixed>
67:      */
68:     public function payload(): array
69:     {
70:         $data = $this->validated();
71:         foreach (array_keys($data['items'] ?? []) as $i) {
72:             $files = $this->file("items.{$i}.attachments");
73:             $data['items'][$i]['attachments'] = is_array($files) ? $files : ($files !== null ? [$files] : []);
74:         }
75: 
76:         return $data;
77:     }
