66:             ->acceptsMimeTypes(['image/jpeg', 'image/png', 'image/webp']);
67:         $this->addMediaCollection('images_staging')->useDisk('r2_public')->storeConversionsOnDisk('r2_public')
68:             ->acceptsMimeTypes(['image/jpeg', 'image/png', 'image/webp']);
