  7: use App\Enums\OrderStatus;
  8: use App\Enums\QuotationStatus;
  9: use App\Events\OrderCreated;
 10: use App\Exceptions\BusinessException;
 11: use App\Models\Customer;
 12: use App\Models\Order;
 13: use App\Models\OrderStatusHistory;
 14: use App\Models\ProductVariant;
 15: use App\Models\Quotation;
 16: use App\Models\User;
 17: use Illuminate\Support\Facades\DB;
 18: 
 19: /**
 20:  * Manages the wholesale quotation lifecycle:
 21:  * Draft creation with dynamic pricing -> customer submission -> administrator pricing and validation ->
 22:  * customer acceptance with automated order generation and stock allocation, or rejection/expiry.
 23:  *
 24:  * Quotations hold no inventory reservations; stock allocation occurs only upon customer acceptance.
 25:  */
 26: class QuotationService
 27: {
 28:     public function __construct(
 29:         private readonly SettingService $settings,
 30:         private readonly PricingService $pricing,
 31:         private readonly OrderService $orders,
 32:         private readonly OrderAllocationService $allocation,
 33:     ) {}
 34: 
 35:     /**
 36:      * Create a new draft quotation for a wholesale customer.
 37:      *
 38:      * @param  Customer  $customer
 39:      * @param  array{customer_notes?: string|null, items: list<array{product_variant_id: int, qty: float, requested_target_price?: float|null}>}  $data
 40:      * @return Quotation
 41:      */
 42:     public function create(Customer $customer, array $data): Quotation
 43:     {
 44:         return DB::transaction(function () use ($customer, $data): Quotation {
 45:             $quotation = Quotation::create([
 46:                 'quotation_number' => $this->settings->generateNextNumber('quotation'),
 47:                 'customer_id' => $customer->id,
 48:                 'status' => QuotationStatus::Draft,
 49:                 'customer_notes' => $data['customer_notes'] ?? null,
 50:             ]);
 51: 
 52:             $this->syncItems($quotation, $customer, $data['items']);
 53:             $this->recalculate($quotation);
 54: 
 55:             return $quotation->load('items.variant.product');
 56:         });
 57:     }
 58: 
 59:     /**
 60:      * Update items and customer notes on an unsubmitted draft quotation.
 61:      *
 62:      * @param  Quotation  $quotation
 63:      * @param  array{customer_notes?: string|null, items?: list<array{product_variant_id: int, qty: float, requested_target_price?: float|null}>}  $data
 64:      * @return Quotation
 65:      *
 66:      * @throws BusinessException
 67:      */
 68:     public function update(Quotation $quotation, array $data): Quotation
 69:     {
 70:         if ($quotation->status !== QuotationStatus::Draft) {
 71:             throw new BusinessException('لا يمكن تعديل عرض السعر إلا وهو مسودة.');
 72:         }
 73: 
 74:         return DB::transaction(function () use ($quotation, $data): Quotation {
 75:             $quotation->update([
 76:                 'customer_notes' => $data['customer_notes'] ?? $quotation->customer_notes,
 77:             ]);
 78: 
 79:             if (isset($data['items'])) {
 80:                 $quotation->items()->delete();
 81:                 $this->syncItems($quotation, $quotation->customer, $data['items']);
 82:             }
 83: 
 84:             $this->recalculate($quotation);
 85: 
 86:             return $quotation->load('items.variant.product');
 87:         });
 88:     }
 89: 
 90:     /**
 91:      * Submit a draft quotation for administrator pricing and review.
 92:      *
 93:      * @param  Quotation  $quotation
 94:      * @return Quotation
 95:      *
 96:      * @throws BusinessException
 97:      */
 98:     public function submit(Quotation $quotation): Quotation
 99:     {
100:         if ($quotation->status !== QuotationStatus::Draft) {
101:             throw new BusinessException('لا يمكن إرسال عرض السعر إلا من حالة المسودة.');
102:         }
103: 
104:         if ($quotation->items()->count() === 0) {
105:             throw new BusinessException('لا يمكن إرسال عرض سعر بلا بنود.');
106:         }
107: 
108:         $quotation->update(['status' => QuotationStatus::Requested]);
109: 
110:         return $quotation->load('items.variant.product');
111:     }
112: 
113:     /**
114:      * Set negotiated prices, validity expiration, discounts, and taxes by an administrator.
115:      *
116:      * @param  Quotation  $quotation
117:      * @param  array{valid_until?: string|null, admin_notes?: string|null, discount_amount?: float|null, tax_amount?: float|null, items?: list<array{id: int, offered_unit_price: float}>}  $data
118:      * @return Quotation
119:      *
120:      * @throws BusinessException
121:      */
122:     public function price(Quotation $quotation, array $data): Quotation
123:     {
124:         if ($quotation->status !== QuotationStatus::Requested) {
125:             throw new BusinessException('لا يمكن تسعير عرض السعر إلا بعد إرساله من التاجر.');
126:         }
127: 
128:         return DB::transaction(function () use ($quotation, $data): Quotation {
129:             foreach ($data['items'] ?? [] as $row) {
130:                 $item = $quotation->items()->whereKey($row['id'])->first();
131: 
132:                 if ($item === null) {
133:                     throw new BusinessException('أحد بنود التسعير لا ينتمي لعرض السعر هذا.');
134:                 }
135: 
136:                 $item->update([
137:                     'offered_unit_price' => $row['offered_unit_price'],
138:                     'line_total' => round((float) $row['offered_unit_price'] * (float) $item->qty, 2),
139:                 ]);
140:             }
141: 
142:             $quotation->update([
143:                 'status' => QuotationStatus::PricedByAdmin,
144:                 'valid_until' => $data['valid_until'] ?? $quotation->valid_until,
145:                 'admin_notes' => $data['admin_notes'] ?? $quotation->admin_notes,
146:                 'discount_amount' => $data['discount_amount'] ?? $quotation->discount_amount,
147:                 'tax_amount' => $data['tax_amount'] ?? $quotation->tax_amount,
148:             ]);
149: 
150:             $this->recalculate($quotation);
151: 
152:             return $quotation->load('items.variant.product');
153:         });
154:     }
155: 
156:     /**
157:      * Accept an administrator-priced quotation and automatically convert it into a confirmed order.
158:      *
159:      * Preserves negotiated line prices, distributes header discounts/taxes using Hare-Niemeyer,
160:      * and allocates inventory. Fails the conversion entirely if any item lacks available stock.
161:      *
162:      * @param  Quotation  $quotation
163:      * @return Quotation
164:      *
165:      * @throws BusinessException
166:      */
167:     public function accept(Quotation $quotation): Quotation
168:     {
169:         if ($quotation->status !== QuotationStatus::PricedByAdmin) {
170:             throw new BusinessException('لا يمكن قبول عرض السعر إلا بعد تسعير الإدارة له.');
171:         }
172: 
173:         if ($quotation->valid_until !== null && $quotation->valid_until->lt(now()->startOfDay())) {
174:             $quotation->update(['status' => QuotationStatus::Expired]);
175: 
176:             throw new BusinessException('انتهت صلاحية عرض السعر هذا.');
177:         }
178: 
179:         return DB::transaction(function () use ($quotation): Quotation {
180:             $quotation->loadMissing(['customer', 'items.variant.product']);
181:             $customer = $quotation->customer;
182: 
183:             $order = Order::create([
184:                 'order_number' => $this->settings->generateNextNumber('order'),
185:                 'channel' => 'wholesale',
186:                 'customer_id' => $customer->id,
187:                 'guest_name' => $customer->name,
188:                 'guest_phone' => $customer->phone,
189:                 'guest_phone_normalized' => Customer::normalizePhone((string) $customer->phone),
190:                 'guest_email' => $customer->email,
191:                 'status' => OrderStatus::Pending,
192:                 'payment_method' => 'credit',
193:                 'payment_status' => 'unpaid',
194:                 'subtotal' => $quotation->subtotal,
195:                 'discount_amount' => $quotation->discount_amount,
196:                 'shipping_cost' => 0,
197:                 'cod_fee' => 0,
198:                 'tax_amount' => $quotation->tax_amount,
199:                 'grand_total' => $quotation->grand_total,
200:             ]);
201: 
202:             // Distribute header discount and tax to items using largest remainder for exact cent precision
203:             $weights = $quotation->items->map(fn ($item) => (float) $item->line_total)->all();
204:             $discountShares = $this->distributeLargestRemainder((float) $quotation->discount_amount, $weights);
205:             $taxShares = $this->distributeLargestRemainder((float) $quotation->tax_amount, $weights);
206: 
207:             foreach ($quotation->items->values() as $i => $item) {
208:                 $order->items()->create([
209:                     'product_variant_id' => $item->product_variant_id,
210:                     'product_name_snapshot' => $item->variant->product?->name_ar ?? '',
211:                     'sku_snapshot' => $item->variant->sku,
212:                     'qty' => $item->qty,
213:                     'unit_price' => $item->offered_unit_price,
214:                     'discount_amount' => $discountShares[$i],
215:                     'tax_amount' => $taxShares[$i],
216:                     'line_total' => $item->line_total,
217:                 ]);
218:             }
219: 
220:             OrderStatusHistory::create([
221:                 'order_id' => $order->id,
222:                 'from_status' => null,
223:                 'to_status' => OrderStatus::Pending,
224:                 'changed_by_type' => Customer::class,
225:                 'changed_by_id' => $customer->id,
226:                 'notes' => "أُنشئ من عرض السعر {$quotation->quotation_number}",
227:             ]);
228: 
229:             $order->load('items');
230:             $this->allocation->allocate($order, performedBy: $this->systemActorId());
231: 
232:             $this->orders->changeStatus($order, OrderStatus::Confirmed, $customer, "قبول عرض السعر {$quotation->quotation_number}");
