234:             $quotation->update([
235:                 'status' => QuotationStatus::ConvertedToOrder,
236:                 'converted_order_id' => $order->id,
237:             ]);
238: 
239:             OrderCreated::dispatch($order->fresh());
240: 
241:             return $quotation->load(['items.variant.product', 'convertedOrder']);
242:         });
