245:     /**
246:      * Retrieve the designated system user ID for recording customer-initiated ledger movements.
247:      */
248:     private function systemActorId(): ?int
249:     {
250:         $id = User::query()
251:             ->where('is_system', true)
252:             ->value('id');
253: 
254:         return $id !== null ? (int) $id : null;
255:     }
256: 
257:     /**
258:      * Distribute an amount proportionally across weights using the Largest Remainder (Hare-Niemeyer) method.
259:      *
260:      * Ensures line item shares sum exactly to the header amount with zero rounding discrepancies.
261:      *
262:      * @param  float  $amount
263:      * @param  list<float>  $weights
264:      * @return list<float>
265:      */
266:     private function distributeLargestRemainder(float $amount, array $weights): array
267:     {
268:         $count = count($weights);
269:         $totalCents = (int) round($amount * 100);
270:         $totalWeight = array_sum($weights);
271: 
272:         if ($count === 0 || $totalCents === 0 || $totalWeight <= 0) {
273:             return array_fill(0, $count, 0.0);
274:         }
275: 
276:         $shares = [];
277:         $remainders = [];
278:         $allocated = 0;
279:         foreach ($weights as $i => $weight) {
280:             $exact = $totalCents * $weight / $totalWeight;
281:             $floor = (int) floor($exact);
282:             $shares[$i] = $floor;
283:             $remainders[$i] = $exact - $floor;
284:             $allocated += $floor;
285:         }
286: 
287:         $order = array_keys($remainders);
288:         usort($order, fn (int $a, int $b): int => $remainders[$b] <=> $remainders[$a]);
289:         for ($k = 0; $k < $totalCents - $allocated; $k++) {
290:             $shares[$order[$k % $count]]++;
291:         }
292: 
293:         return array_map(fn (int $cents): float => $cents / 100, $shares);
294:     }
295: 
296:     /**
297:      * Reject a submitted or priced quotation.
298:      *
299:      * @param  Quotation  $quotation
300:      * @return Quotation
301:      *
302:      * @throws BusinessException
303:      */
304:     public function reject(Quotation $quotation): Quotation
305:     {
306:         if (! in_array($quotation->status, [QuotationStatus::Requested, QuotationStatus::PricedByAdmin], true)) {
307:             throw new BusinessException('لا يمكن رفض عرض السعر في حالته الحالية.');
308:         }
309: 
310:         $quotation->update(['status' => QuotationStatus::Rejected]);
311: 
312:         return $quotation->load('items.variant.product');
313:     }
314: 
315:     /**
316:      * Expire a past-due quotation.
317:      *
318:      * @param  Quotation  $quotation
319:      * @return Quotation
320:      *
321:      * @throws BusinessException
322:      */
323:     public function expire(Quotation $quotation): Quotation
324:     {
325:         if (! in_array($quotation->status, [QuotationStatus::Requested, QuotationStatus::PricedByAdmin], true)) {
326:             throw new BusinessException('لا يمكن إنهاء صلاحية عرض السعر في حالته الحالية.');
327:         }
328: 
329:         $quotation->update(['status' => QuotationStatus::Expired]);
330: 
331:         return $quotation->load('items.variant.product');
332:     }
333: 
334:     /**
335:      * Delete an unsubmitted draft quotation.
336:      *
337:      * @param  Quotation  $quotation
338:      * @return void
339:      *
340:      * @throws BusinessException
341:      */
342:     public function deleteDraft(Quotation $quotation): void
343:     {
344:         if ($quotation->status !== QuotationStatus::Draft) {
345:             throw new BusinessException('لا يمكن حذف عرض السعر إلا وهو مسودة.');
346:         }
347: 
348:         $quotation->delete();
349:     }
350: 
351:     /**
352:      * @param  list<array{product_variant_id: int, qty: float, requested_target_price?: float|null}>  $items
353:      */
354:     private function syncItems(Quotation $quotation, Customer $customer, array $items): void
355:     {
356:         $variantIds = collect($items)->pluck('product_variant_id')->unique()->all();
357:         $variants = ProductVariant::query()->whereIn('id', $variantIds)->get()->keyBy('id');
358: 
359:         foreach ($items as $row) {
360:             $variant = $variants->get($row['product_variant_id']);
361: 
362:             if ($variant === null || ! $variant->is_active) {
363:                 throw new BusinessException('أحد المتغيرات المطلوبة غير موجود أو غير نشط.');
364:             }
365: 
366:             $offered = $this->pricing->resolve($variant, $customer, (float) $row['qty'])['unit_price'];
367: 
368:             $quotation->items()->create([
369:                 'product_variant_id' => $variant->id,
370:                 'qty' => $row['qty'],
371:                 'requested_target_price' => $row['requested_target_price'] ?? null,
372:                 'offered_unit_price' => $offered,
373:                 'line_total' => round($offered * (float) $row['qty'], 2),
374:             ]);
375:         }
376:     }
377: 
378:     private function recalculate(Quotation $quotation): void
379:     {
380:         $subtotal = (float) $quotation->items()->sum('line_total');
381:         $grandTotal = round($subtotal - (float) $quotation->discount_amount + (float) $quotation->tax_amount, 2);
382: 
383:         if ($grandTotal < 0) {
384:             throw new BusinessException('إجمالي عرض السعر لا يمكن أن يكون سالبًا — راجع الخصم.');
385:         }
386: 
387:         $quotation->update([
388:             'subtotal' => $subtotal,
389:             'grand_total' => $grandTotal,
390:         ]);
391:     }
