 20: /**
 21:  * Wholesale customer self-registration service.
 22:  * Registers customer in Pending status and stages uploaded verification documents into private storage.
 23:  * Final approval is performed by administrators via CustomerManagementService.
 24:  */
 25: class WholesaleRegistrationService
 26: {
 27:     public function __construct(private readonly CustomerAuthService $auth) {}
 28: 
 29:     /**
 30:      * Register a new wholesale customer and store supporting verification documents.
 31:      * Staged files are moved into customer directory upon successful transaction.
 32:      *
 33:      * @param  list<UploadedFile>  $files
 34:      * @param  list<string|null>  $documentTypes Parallel document type tags (defaults to "other")
 35:      * @return array{customer: Customer, token: string}
 36:      */
 37:     public function register(array $data, array $files, array $documentTypes = []): array
 38:     {
 39:         $files = array_values($files);
 40:         $documentTypes = array_values($documentTypes);
 41:         $storedPaths = [];
 42:         $staged = [];
 43:         $stagingDirectory = 'customer_documents/pending/'.Str::uuid();
 44: 
 45:         try {
 46:             foreach ($files as $i => $file) {
 47:                 $filename = Str::uuid().'.'.($file->extension() ?: 'bin');
 48:                 $path = Storage::disk('r2')->putFileAs($stagingDirectory, $file, $filename);
 49:                 if ($path === false) {
 50:                     throw new \RuntimeException('تعذر حفظ مستند العميل.');
 51:                 }
 52:                 $storedPaths[] = $path;
 53:                 $staged[] = [
 54:                     'filename' => $filename, 'path' => $path,
 55:                     'document_type' => $documentTypes[$i] ?? CustomerDocumentType::Other->value,
 56:                     'original_name' => CustomerDocument::safeName($file->getClientOriginalName()),
 57:                     'mime_type' => $file->getMimeType() ?? 'application/octet-stream',
 58:                 ];
 59:             }
 60: 
 61:             $registration = DB::transaction(function () use ($data, $staged, &$storedPaths): array {
 62:                 $verified = app(CustomerPhoneVerificationService::class)->consume($data);
 63:                 $customer = Customer::query()->create([
 64:                     'name' => $data['name'],
 65:                     'email' => $data['email'] ?? null,
 66:                     'phone' => $data['phone'],
 67:                     'password' => $data['password'],
 68:                     'type' => CustomerType::Wholesale,
 69:                     'status' => CustomerStatus::Pending,
 70:                     'phone_verified_at' => $verified ? now() : null,
 71:                     'company_name' => $data['company_name'],
 72:                     'tax_number' => $data['tax_number'],
 73:                     'commercial_register' => $data['commercial_register'],
 74:                 ]);
 75: 
 76:                 foreach ($staged as $document) {
 77:                     // Private storage: sensitive corporate documents are never publicly exposed;
 78:                     // downloads are strictly routed through authenticated admin endpoints.
 79:                     $path = "customer_documents/{$customer->id}/".$document['filename'];
 80:                     $storedPaths[] = $path;
 81:                     if (! Storage::disk('r2')->move($document['path'], $path)) {
 82:                         throw new \RuntimeException('تعذر حفظ مستند العميل.');
 83:                     }
 84: 
 85:                     $customer->documents()->create([
 86:                         'document_type' => $document['document_type'],
 87:                         'file_path' => $path,
 88:                         'original_name' => $document['original_name'],
 89:                         'mime_type' => $document['mime_type'],
 90:                         'status' => CustomerDocumentStatus::Pending,
 91:                     ]);
 92:                 }
 93: 
 94:                 CustomerAuditLog::record($customer, 'self_registered', null, ['channel' => 'wholesale']);
 95:                 WholesaleApplicationSubmitted::dispatch($customer);
 96: 
 97:                 return [
 98:                     'customer' => $customer->load('documents'),
 99:                     'token' => $this->auth->issueToken($customer, 'wholesale-token'),
100:                 ];
101:             });
102:         } catch (\Throwable $e) {
103:             // Transaction failure: clean up uploaded files on cloud storage to prevent orphaned assets
104:             foreach ($storedPaths as $path) {
105:                 Storage::disk('r2')->delete($path);
106:             }
107:             if ($storedPaths !== []) {
108:                 Storage::disk('r2')->deleteDirectory($stagingDirectory);
109:             }
110: 
111:             throw $e;
112:         }
113: 
114:         Storage::disk('r2')->deleteDirectory($stagingDirectory);
115: 
116:         return $registration;
117:     }
