 19: /**
 20:  * Customer authentication lifecycle coordinator (retail store and wholesale portal).
 21:  * Handles self-registration, credential authentication, password recovery, and token issuance.
 22:  * Security boundaries: sensitive attributes (type/status) are strictly assigned programmatically.
 23:  */
 24: class CustomerAuthService
 25: {
 26:     /**
 27:      * Generate or return a cached dummy bcrypt/hasher hash to prevent user-enumeration timing attacks.
 28:      */
 29:     public static function dummyHash(): string
 30:     {
 31:         if (config('hashing.driver', 'bcrypt') === 'bcrypt') {
 32:             return sprintf('$2y$%02d$92IXUNpkjO0rOQ5byMi.Ye4oKoEa3Ro9llC/.og/at2uheWG/igi.', (int) config('hashing.bcrypt.rounds', 12));
 33:         }
 34:         static $hashes = [];
 35:         $key = json_encode(config('hashing'));
 36: 
 37:         return $hashes[$key] ??= Hash::make('not-a-customer-password');
 38:     }
 39: 
 40:     /**
 41:      * Compute HMAC key for phone/email to prevent rainbow-table reversal on small phone number spaces in audit logs.
 42:      */
 43:     private function identifierKey(string $identifier): string
 44:     {
 45:         return hash_hmac('sha256', $identifier, (string) config('app.key'));
 46:     }
 47: 
 48:     /**
 49:      * Self-register a retail store customer.
 50:      * Enforces Retail type and Approved status unconditionally.
 51:      */
 52:     public function registerRetail(array $data): Customer
 53:     {
 54:         $verified = app(CustomerPhoneVerificationService::class)->consume($data);
 55: 
 56:         $customer = Customer::query()->create([
 57:             'name' => $data['name'],
 58:             'email' => $data['email'] ?? null,
 59:             'phone' => $data['phone'],
 60:             'password' => $data['password'],
 61:             'type' => CustomerType::Retail,
 62:             'status' => CustomerStatus::Approved,
 63:             'phone_verified_at' => $verified ? now() : null,
 64:             'approved_at' => now(),
 65:         ]);
 66:         CustomerAuditLog::record($customer, 'self_registered', null, ['channel' => 'store']);
 67: 
 68:         return $customer;
 69:     }
 70: 
 71:     /**
 72:      * Authenticate customer credentials via phone or verified email.
 73:      * Suspended accounts are rejected with 403; pending/rejected wholesale accounts may log in
 74:      * to check application status, with channel guards restricting subsequent actions.
 75:      *
 76:      * @throws BusinessException If credentials invalid or account suspended
 77:      */
 78:     public function login(string $identifier, string $password): Customer
 79:     {
 80:         $emailLogin = str_contains($identifier, '@');
 81:         $identifier = $emailLogin ? mb_strtolower(trim($identifier)) : Customer::normalizePhone($identifier);
 82:         $dummyHash = self::dummyHash();
 83:         $customer = Customer::query()
 84:             ->when($emailLogin, fn ($q) => $q->whereNotNull('email_verified_at')->whereRaw('LOWER(email) = ?', [$identifier]), fn ($q) => $q->where('phone', $identifier))
 85:             ->first();
 86: 
 87:         $validPassword = Hash::check($password, $customer?->password ?? $dummyHash);
 88:         if ($customer === null || ! $validPassword) {
 89:             // Avoid inserting unbounded audit log rows for nonexistent identifiers during stuffing attacks;
 90:             // log sampled info metric instead, keyed by HMAC.
 91:             if ($customer === null) {
 92:                 if (random_int(1, 10) === 1) {
 93:                     logger()->info('customer.login_failed', ['identifier_key' => $this->identifierKey($identifier)]);
 94:                 }
 95:             } else {
 96:                 defer(fn () => CustomerAuditLog::record($customer, 'login_failed', null, ['identifier_key' => $this->identifierKey($identifier)]))->always();
 97:             }
 98:             throw new BusinessException('بيانات الدخول غير صحيحة.', [], 401);
 99:         }
100: 
101:         if ($customer->status === CustomerStatus::Suspended) {
102:             CustomerAuditLog::record($customer, 'login_failed', null, ['reason' => 'suspended']);
103:             throw new BusinessException(
104:                 'هذا الحساب موقوف.'.($customer->suspension_reason ? ' السبب: '.$customer->suspension_reason : ''),
105:                 ['suspension_reason' => $customer->suspension_reason],
106:                 403,
107:             );
108:         }
109: 
110:         if (Hash::needsRehash($customer->password)) {
111:             $customer->forceFill(['password' => $password])->save();
112:         }
113:         CustomerAuditLog::record($customer, 'login_succeeded', null);
114: 
115:         return $customer;
116:     }
117: 
118:     /**
119:      * Initiate asynchronous password reset workflow.
120:      * Returns generic success regardless of account existence to prevent user enumeration.
121:      */
122:     public function forgotPassword(?string $email, ?string $phone): void
123:     {
124:         if (! $email && ! $phone) {
125:             return;
126:         }
127: 
128:         SendCustomerPasswordReset::dispatch($email, $phone)
129:             ->onConnection(config('auth.customer_password_reset.connection', 'database'));
130:     }
131: 
132:     /**
133:      * Generate password reset token and dispatch notification.
134:      * Enforces token throttling and message budget limits.
135:      */
136:     public function sendPasswordReset(?string $email, ?string $phone): void
137:     {
138:         if (! $email && ! $phone) {
139:             return;
140:         }
141: 
142:         $customer = Customer::query()
143:             ->when($email, fn ($q) => $q->whereNotNull('email_verified_at')->whereRaw('LOWER(email) = ?', [mb_strtolower(trim($email))]),
144:                 fn ($q) => $q->where('phone', Customer::normalizePhone($phone)))
145:             ->first();
146: 
147:         if ($customer === null || $customer->status === CustomerStatus::Suspended) {
148:             return;
149:         }
150: 
151:         $plainToken = Str::random(64);
152:         $key = $customer->getEmailForPasswordReset();
153: 
154:         $stored = DB::transaction(function () use ($customer, $key, $plainToken, $email): bool {
155:             $current = Customer::query()->lockForUpdate()->find($customer->id);
156:             if ($current === null || $current->status === CustomerStatus::Suspended) {
157:                 return false;
158:             }
159:             if ($email && ($current->email_verified_at === null || $current->email !== mb_strtolower(trim($email)))) {
160:                 return false;
161:             }
162:             $existing = DB::table('password_reset_tokens')->where('email', $key)->first();
163:             if ($existing && now()->subSeconds(60)->lt($existing->created_at)) {
164:                 return false;
165:             }
166:             if (! app(CustomerMessageBudget::class)->claim('reset:customer:'.$customer->id, sms: ! $email)) {
167:                 return false;
168:             }
169:             DB::table('password_reset_tokens')->updateOrInsert(
170:                 ['email' => $key], ['token' => hash('sha256', $plainToken), 'created_at' => now()],
171:             );
172: 
173:             return true;
174:         });
175:         if (! $stored) {
176:             return;
177:         }
178: 
179:         try {
180:             $customer->notify(new CustomerPasswordReset($plainToken, $email ? 'mail' : CustomerSmsChannel::class));
181:         } catch (\Throwable $exception) {
182:             report($exception);
183:         }
184:     }
