186:     /**
187:      * Validate reset token and update customer password.
188:      * Revokes all active sessions upon successful reset.
189:      *
190:      * @throws BusinessException If token is invalid or expired
191:      */
192:     public function resetPassword(array $data): void
193:     {
194:         $dummyHash = self::dummyHash();
195:         DB::transaction(function () use ($data, $dummyHash): void {
196:             $customer = Customer::query()
197:                 ->when(! empty($data['email']), fn ($q) => $q->whereNotNull('email_verified_at')->whereRaw('LOWER(email) = ?', [mb_strtolower(trim($data['email']))]),
198:                     fn ($q) => $q->where('phone', $data['phone']))
199:                 ->lockForUpdate()->first();
200:             $key = $customer?->getEmailForPasswordReset();
201:             $row = DB::table('password_reset_tokens')->where('email', $key)->lockForUpdate()->first();
202:             $storedToken = $row?->token ?? '';
203:             $validToken = strlen($storedToken) === 64 ? hash_equals($storedToken, hash('sha256', $data['token']))
204:                 : Hash::check($data['token'], $storedToken ?: $dummyHash);
205:             if ($customer === null || $customer->status === CustomerStatus::Suspended || $row === null
206:                 || $row->created_at === null || now()->subMinutes(60)->gte($row->created_at)
207:                 || now()->lt($row->created_at) || ! $validToken) {
208:                 throw new BusinessException('رمز الاستعادة غير صالح أو انتهت صلاحيته.');
209:             }
210:             $customer->forceFill(['password' => $data['password'], 'remember_token' => Str::random(60)])->save();
211:             $customer->tokens()->delete();
212:             DB::table('password_reset_tokens')->where('email', $key)->delete();
213:             CustomerAuditLog::record($customer, 'password_reset', null);
214:         });
215:     }
