217:     /**
218:      * Issue a channel-scoped Sanctum access token (e.g. store-token, wholesale-token).
219:      * Prunes expired tokens and limits maximum active concurrent sessions.
220:      *
221:      * @throws BusinessException If account is suspended
222:      */
223:     public function issueToken(Customer $customer, string $name): string
224:     {
225:         return DB::transaction(function () use ($customer, $name): string {
226:             $customer = Customer::query()->lockForUpdate()->findOrFail($customer->id);
227:             if ($customer->status === CustomerStatus::Suspended) {
228:                 throw new BusinessException('هذا الحساب موقوف.', [], 403);
229:             }
230: 
231:             $expiry = config('sanctum.expiration');
232:             $customer->tokens()->where(fn ($q) => $q->where('expires_at', '<=', now())
233:                 ->when($expiry, fn ($q) => $q->orWhere('created_at', '<=', now()->subMinutes((int) $expiry))))->delete();
234:             $limit = max(1, (int) config('auth.customer_max_tokens', 10));
235:             $old = $customer->tokens()->orderByDesc('id')->skip($limit - 1)->pluck('id');
236:             if ($old->isNotEmpty()) {
237:                 $customer->tokens()->whereIn('id', $old)->delete();
238:             }
239: 
240:             $token = $customer->createToken($name, ['*'], now()->addMinutes(max(1, (int) config('auth.customer_token_minutes', 1440))));
241:             CustomerAuditLog::record($customer, 'token_issued', null, ['token_id' => $token->accessToken->id, 'channel' => $name]);
242: 
243:             return $token->plainTextToken;
244:         });
245:     }
