  5: async function revokePreviousSession(nextToken?: string | null) {
  6:   const previous = useAuthStore.getState().token;
  7:   if (!previous || previous === nextToken) return;
  8:   try {
  9:     await createApiClient({ getToken: () => previous, onUnauthorized: () => {} })
 10:       .post('/api/v1/auth/logout', {}, { timeout: 10000 });
 11:   } catch { /* The previous session may already have expired. */ }
 12: }
