 14: export async function loginUnified(login: string, password: string, redirect?: string | null) {
 15:   const guestSession = getCartSession();
 16:   const res = await authEndpoints.login({ login, password, redirect: redirect ?? undefined }, guestSession);
 17:   await revokePreviousSession(res.token);
 18: 
 19:   if (res.redirect.app === 'backoffice') {
 20:     // M9: جلسة عميل/مورد قائمة توكنها يبقى صالحًا 24 ساعة بعد clear المحلي —
 21:     // أبطلها في الخادم أولًا (best-effort) قبل مسح الجلسة المحلية.
 22:     useAuthStore.getState().clear();
 23:     // M7: الكود في الـ fragment لا في الـ query — الـ fragment لا يُرسل
 24:     // للخادم ولا يظهر في الـ Referer أو سجلات nginx.
 25:     const url = `${resolveServiceUrl(process.env.NEXT_PUBLIC_BACKOFFICE_URL ?? 'http://localhost:5173')}/auth/callback#code=${encodeURIComponent(res.handoff_code!)}`;
 26:     window.location.assign(url);
 27:     return null;
 28:   }
 29: 
 30:   useAuthStore.getState().setSession({
 31:     token: res.token!, actorType: res.actor.type as 'customer' | 'supplier',
 32:     destination: res.actor.subtype, home: res.redirect.path, user: res.data,
 33:   });
 34:   // M10: الدمج قد يفشل في الخادم (cart_merged=false) — أبقِ cart_session
 35:   // ليُعاد دمجه لاحقًا بدل حذفه مع توكن يتيم جديد.
 36:   if (res.actor.type === 'customer') {
 37:     if (res.cart_merged === false && guestSession) restoreGuestCartSession(guestSession);
 38:     else clearGuestCartSession();
 39:   }
 40:   return res.redirect.path;
 41: }
