 43: export async function logoutWeb(next = '/auth/login') {
 44:   try { await authEndpoints.logout(); } catch { /* Clear local credentials even when the server is unreachable. */ }
 45:   finally { useAuthStore.getState().clear(); window.location.href = next; }
 46: }
