 48: export interface RegistrationInput {
 49:   name: string;
 50:   phone: string;
 51:   email?: string;
 52:   password: string;
 53:   phone_verification_token?: string;
 54:   company_name?: string;
 55:   tax_number?: string;
 56:   commercial_register?: string;
 57: }
 58: 
 59: interface RegistrationResponse {
 60:   token: string;
 61:   data: Record<string, unknown>;
 62: }
 63: 
 64: export async function registerWeb(input: RegistrationInput, wholesale: boolean, documents: File[] = []) {
 65:   let body: RegistrationInput | FormData = input;
 66:   if (wholesale) {
 67:     body = new FormData();
 68:     Object.entries(input).forEach(([key, value]) => {
 69:       if (value !== undefined && value !== '') (body as FormData).append(key, value);
 70:     });
 71:     documents.forEach((file) => (body as FormData).append('documents[]', file));
 72:   }
 73:   const session = getCartSession();
 74:   const response = await defaultApiClient.post<RegistrationResponse>(
 75:     wholesale ? '/api/v1/wholesale/auth/register' : '/api/v1/store/auth/register', body,
 76:     { headers: {
 77:       ...(wholesale ? { 'Content-Type': 'multipart/form-data' } : {}),
 78:       ...(!wholesale && session ? { 'X-Cart-Session': session } : {}),
 79:     } },
 80:   );
 81:   const home = wholesale ? '/wholesale/application-status' : '/shop';
 82:   await revokePreviousSession(response.data.token);
 83:   useAuthStore.getState().setSession({
 84:     token: response.data.token, actorType: 'customer',
 85:     destination: wholesale ? 'wholesale_pending' : 'retail', home, user: response.data.data,
 86:   });
 87:   if (!wholesale) clearGuestCartSession();
 88:   return home;
 89: }
