 19: /**
 20:  * سلة المتجر — تعمل للزائر (هيدر X-Cart-Session) وللعميل المسجل (Bearer)
 21:  * بنفس النقاط؛ الهوية تُحسم داخل CartService.
 22:  */
 23: class CartController extends Controller
 24: {
 25:     public function __construct(
 26:         private readonly CartService $carts,
 27:         private readonly CouponService $coupons,
 28:     ) {}
 29: 
 30:     public function index(Request $request): JsonResponse
 31:     {
 32:         // قراءة فقط: لا يُحفظ صف سلة لمجرد العرض (M3)
 33:         [$customer, $cart] = $this->currentCart($request, create: false);
 34: 
 35:         return response()->json(['data' => $this->carts->present($cart, $customer)]);
 36:     }
 37: 
 38:     public function store(AddCartItemRequest $request): JsonResponse
 39:     {
 40:         [$customer, $cart] = $this->currentCart($request, create: false);
 41:         $cart = $this->carts->addItem($cart, $customer, (int) $request->validated()['product_variant_id'], (float) $request->validated()['qty']);
 42: 
 43:         return response()->json(['data' => $this->carts->present($cart, $customer)]);
 44:     }
 45: 
 46:     public function update(UpdateCartItemRequest $request, int $item): JsonResponse
 47:     {
 48:         [$customer, $cart] = $this->currentCart($request);
 49:         $cartItem = $cart->items()->findOrFail($item);
 50:         $cart = $this->carts->updateItemQty($cart, $customer, (int) $cartItem->product_variant_id, (float) $request->validated()['qty'], $cartItem->id);
 51: 
 52:         return response()->json(['data' => $this->carts->present($cart, $customer)]);
 53:     }
 54: 
 55:     public function destroy(Request $request, int $item): JsonResponse
 56:     {
 57:         // L10: cart deletes are idempotent — a missing cart or line is already
 58:         // the desired end state.
 59:         try {
 60:             [$customer, $cart] = $this->currentCart($request);
 61:         } catch (NotFoundHttpException) {
 62:             return response()->json(null, 204);
 63:         }
 64:         $cartItem = $cart->items()->find($item);
 65:         if ($cartItem === null) {
 66:             return response()->json(null, 204);
 67:         }
 68:         $cart = $this->carts->removeItem($cart, (int) $cartItem->product_variant_id);
 69: 
 70:         return response()->json(['data' => $this->carts->present($cart, $customer)]);
 71:     }
 72: 
 73:     public function removeCoupon(Request $request): JsonResponse
 74:     {
 75:         [$customer, $cart] = $this->currentCart($request);
 76:         $cart->update(['coupon_id' => null]);
 77: 
 78:         return response()->json(['data' => $this->carts->present($cart->refresh(), $customer)]);
 79:     }
 80: 
 81:     public function clear(Request $request): JsonResponse
 82:     {
 83:         // L10: clearing a missing cart is already the desired end state.
 84:         try {
 85:             [$customer, $cart] = $this->currentCart($request);
 86:         } catch (NotFoundHttpException) {
 87:             return response()->json(null, 204);
 88:         }
 89:         if (! $cart->exists) {
 90:             return response()->json(null, 204);
 91:         }
 92:         $cart = $this->carts->clearItems($cart);
 93: 
 94:         return response()->json(['data' => $this->carts->present($cart, $customer)]);
 95:     }
 96: 
 97:     public function applyCoupon(ApplyCouponRequest $request): JsonResponse
 98:     {
 99:         [$customer, $cart] = $this->currentCart($request);
100:         $totals = $this->carts->totals($cart, $customer);
101:         $discount = $this->coupons->validateAndApply($cart, (string) $request->validated()['code'], $totals['items_total'], $customer);
102: 
103:         return response()->json(['data' => [
104:             'cart' => $this->carts->present($cart->fresh(), $customer),
105:             'coupon_discount' => $discount,
106:         ]]);
107:     }
108: 
109:     /** @return array{0: ?Customer, 1: Cart} */
110:     private function currentCart(Request $request, bool $create = false): array
111:     {
112:         $user = auth('sanctum')->user();
113:         // عميل موقوف/مرفوض بتوكن صالح يُعامل كزائر (F-20): لا تُربط سلاته
