115:         $customer = $user instanceof Customer && $user->canShop() ? $user : null;
116:         $cart = $this->carts->resolveCart($customer, $request->header('X-Cart-Session'), $create);
117:         if (! $cart->exists && ! $request->isMethod('GET') && $request->route()?->getActionMethod() !== 'store') {
118:             abort(404);
119:         }
120: 
121:         return [$customer, $cart];
122:     }
