166: function categoryFormData(p: CategoryPayload, spoofPut = false): FormData {
167:   const fd = new FormData();
168:   if (spoofPut) fd.append('_method', 'PUT');
169:   const put = (key: string, v: unknown) => {
170:     if (v === undefined) return;                       // مش هيتبعت
171:     if (v === null) return fd.append(key, '');         // Laravel يحوّلها null
172:     if (typeof v === 'boolean') return fd.append(key, v ? '1' : '0'); // مهم: مش "true"
173:     if (v instanceof Blob) return fd.append(key, v);
174:     fd.append(key, String(v));
175:   };
176:   put('parent_id', p.parent_id);
177:   put('name_ar', p.name_ar);
178:   put('name_en', p.name_en);
179:   put('slug', p.slug);
180:   put('description_ar', p.description_ar);
181:   put('description_en', p.description_en);
182:   put('sort_order', p.sort_order);
183:   put('is_active', p.is_active);
184:   if (p.image) put('image', p.image);
185:   if (p.remove_image) put('remove_image', true);
186:   return fd;
187: }
