 20: /**
 21:  * Manages customer and guest shopping carts and real-time line item pricing.
 22:  *
 23:  * Guests are identified by cart_token (transmitted via X-Cart-Session header).
 24:  * Authenticated users link carts by customer_id, merging any guest carts on login.
 25:  * Prices and availability are resolved in real-time without caching stale amounts.
 26:  */
 27: class CartService
 28: {
 29:     public const MAX_REQUEST_QTY = 10000;
 30: 
 31:     public function __construct(
 32:         protected PricingService $pricing,
 33:         protected StoreCatalogService $catalog,
 34:         protected CouponService $coupons,
 35:     ) {}
 36: 
 37:     /**
 38:      * Resolves the active cart for an authenticated customer or guest session token.
 39:      *
 40:      * In read-only mode ($create=false), returns an unpersisted Cart instance to prevent database bloat from web crawlers.
 41:      */
 42:     public function resolveCart(?Customer $customer, ?string $guestToken, bool $create = true): Cart
 43:     {
 44:         $guestToken = $guestToken !== null && Str::isUuid($guestToken) ? $guestToken : null;
 45: 
 46:         if ($customer !== null) {
 47:             $cart = $create
 48:                 ? $this->accountCart($customer)
 49:                 : (Cart::query()->where('customer_id', $customer->id)->first() ?? new Cart(['customer_id' => $customer->id]));
 50:             if ($create && $guestToken !== null && $guestToken !== $cart->cart_token) {
 51:                 $this->mergeGuestCart($customer, $guestToken);
 52:                 $cart = $cart->fresh();
 53:             }
 54: 
 55:             return $cart->loadMissing('items');
 56:         }
 57: 
 58:         $cart = $guestToken !== null
 59:             ? Cart::query()->where('cart_token', $guestToken)->whereNull('customer_id')->first()
 60:             : null;
 61:         if ($cart !== null) {
 62:             return $cart->loadMissing('items');
 63:         }
 64: 
 65:         return ($create ? Cart::create([]) : new Cart)->loadMissing('items');
 66:     }
