 68:     /**
 69:      * Retrieves or creates the unique persistent cart instance for an authenticated customer.
 70:      */
 71:     private function accountCart(Customer $customer): Cart
 72:     {
 73:         // createOrFirst wraps insertion inside a transaction savepoint to prevent 25P02 transaction aborts.
 74:         return Cart::query()->where('customer_id', $customer->id)->first()
 75:             ?? Cart::query()->createOrFirst(['customer_id' => $customer->id]);
 76:     }
