 78:     /**
 79:      * Merges items and coupon from a guest cart into an authenticated customer cart on login.
 80:      */
 81:     public function mergeGuestCart(Customer $customer, ?string $guestToken): void
 82:     {
 83:         $guestToken = $guestToken !== null && Str::isUuid($guestToken) ? $guestToken : null;
 84:         if ($guestToken === null) {
 85:             return;
 86:         }
 87: 
 88:         // Lock guest cart under transaction to serialize concurrent post-login requests.
 89:         DB::transaction(function () use ($customer, $guestToken): void {
 90:             $guest = Cart::query()->where('cart_token', $guestToken)->whereNull('customer_id')
 91:                 ->lockForUpdate()->first();
 92:             if ($guest === null) {
 93:                 return;
 94:             }
 95:             if (! $guest->items()->exists()) {
 96:                 $guest->delete();
 97: 
 98:                 return;
 99:             }
100: 
101:             $account = Cart::query()->lockForUpdate()->findOrFail($this->accountCart($customer)->id);
102:             // Enforce cart line and item quantity caps during guest cart merger.
103:             $maxLines = (int) config('store.max_cart_lines', 50);
104:             $lineCap = $this->lineQtyCap($customer);
105:             $accountQty = $account->items()->pluck('qty', 'product_variant_id')
106:                 ->map(fn ($qty): float => (float) $qty)->all();
107:             $accountLines = count($accountQty);
108: 
109:             foreach ($guest->items as $item) {
110:                 $variantId = (int) $item->product_variant_id;
111:                 $existingQty = $accountQty[$variantId] ?? null;
112:                 $isNew = $existingQty === null;
113: 
114:                 // Skip new items exceeding max cart lines to avoid blocking user login.
115:                 if ($isNew && $maxLines > 0 && $accountLines >= $maxLines) {
116:                     continue;
117:                 }
118: 
119:                 $qty = (float) $item->qty;
120:                 if ($lineCap > 0) {
121:                     $allowed = $lineCap - (float) ($existingQty ?? 0);
122:                     if ($allowed <= 0) {
123:                         continue;
124:                     }
125:                     $qty = min($qty, $allowed);
126:                 }
127: 
128:                 // Upsert combines quantities atomically to avoid unique constraint collisions.
129:                 CartItem::query()->upsert(
130:                     [[
131:                         'cart_id' => $account->id,
132:                         'product_variant_id' => $variantId,
133:                         'qty' => $qty,
134:                         'created_at' => now(),
135:                         'updated_at' => now(),
136:                     ]],
137:                     ['cart_id', 'product_variant_id'],
138:                     ['qty' => DB::raw('cart_items.qty + EXCLUDED.qty'), 'updated_at' => now()],
139:                 );
140: 
141:                 $accountQty[$variantId] = (float) ($existingQty ?? 0) + $qty;
142:                 if ($isNew) {
143:                     $accountLines++;
144:                 }
145:             }
146:             if ($account->coupon_id === null && $guest->coupon_id !== null) {
147:                 $account->update(['coupon_id' => $guest->coupon_id]);
148:             }
149:             $guest->items()->delete();
150:             $guest->delete();
151:         });
152:     }
