154:     /**
155:      * Adds an item quantity to the cart under a pessimistic row lock.
156:      */
157:     public function addItem(Cart $cart, ?Customer $customer, int $variantId, float $qty): Cart
158:     {
159:         $this->assertWholeQuantity($qty);
160: 
161:         return DB::transaction(function () use ($cart, $customer, $variantId, $qty): Cart {
162:             // Lock cart row to serialize concurrent item additions and enforce line limits.
163:             if (! $cart->exists) {
164:                 $cart = $customer !== null ? $this->accountCart($customer) : Cart::create([]);
165:             }
166:             $cart = Cart::query()->lockForUpdate()->findOrFail($cart->id);
167: 
168:             $variant = $this->purchasableVariant($variantId);
169:             $existing = $cart->items()->where('product_variant_id', $variantId)->first();
170: 
171:             // Reject adding new lines when the maximum allowed cart line limit is reached.
172:             if ($existing === null) {
173:                 $maxLines = (int) config('store.max_cart_lines', 50);
174:                 if ($maxLines > 0 && $cart->items()->count() >= $maxLines) {
175:                     throw new BusinessException("بلغت سلة التسوق سقف الأصناف ({$maxLines})؛ احذف صنفًا قبل الإضافة.");
176:                 }
177:             }
178: 
179:             $targetQty = ($existing !== null ? (float) $existing->qty : 0) + $qty;
180:             $this->assertLineQty($customer, $targetQty);
181:             $this->assertAvailable($variantId, $targetQty);
182:             $this->assertPriced($variant, $customer, $targetQty);
183: 
184:             // Upsert increments item quantity atomically to prevent unique key race conditions.
185:             CartItem::query()->upsert(
186:                 [[
187:                     'cart_id' => $cart->id,
188:                     'product_variant_id' => $variantId,
189:                     'qty' => $qty,
190:                     'created_at' => now(),
191:                     'updated_at' => now(),
192:                 ]],
193:                 ['cart_id', 'product_variant_id'],
194:                 ['qty' => DB::raw('cart_items.qty + EXCLUDED.qty'), 'updated_at' => now()],
195:             );
196: 
197:             return $cart->fresh('items');
198:         });
199:     }
