201:     /**
202:      * Updates the quantity of a specific item in the cart.
203:      */
204:     public function updateItemQty(Cart $cart, ?Customer $customer, int $variantId, float $qty, ?int $itemId = null): Cart
205:     {
206:         $this->assertWholeQuantity($qty, allowZero: true);
207:         if ($qty <= 0) {
208:             return $this->removeItem($cart, $variantId);
209:         }
210: 
211:         return DB::transaction(function () use ($cart, $customer, $variantId, $qty, $itemId): Cart {
212:             $cart = Cart::query()->lockForUpdate()->findOrFail($cart->id);
213:             $variant = $this->purchasableVariant($variantId);
214:             $this->assertLineQty($customer, $qty);
215:             $this->assertAvailable($variantId, $qty);
216:             $this->assertPriced($variant, $customer, $qty);
217: 
218:             $item = $cart->items()->where('product_variant_id', $variantId)
219:                 ->when($itemId !== null, fn ($query) => $query->whereKey($itemId))->firstOrFail();
220:             $item->update(['qty' => $qty]);
221: 
222:             return $cart->fresh('items');
223:         });
224:     }
