252:     /**
253:      * Calculates real-time prices, discounts, and line totals for all cart items.
254:      *
255:      * @return array<int, array{item_id: int, variant: ProductVariant, qty: float, unit_price: float|null, base_price: float|null, line_discount: float, line_total: float}>
256:      */
257:     public function pricedLines(Cart $cart, ?Customer $customer): array
258:     {
259:         $cart->loadMissing('items.variant.product');
260:         $purchasableIds = $this->retailVariants()->whereIn('id', $cart->items->pluck('product_variant_id'))->pluck('id')->all();
261:         $context = $this->pricing->contextFor($customer, $cart->items->pluck('product_variant_id')->all());
262:         $lines = [];
263:         foreach ($cart->items as $item) {
264:             $variant = $item->variant;
265:             if ($variant === null) {
266:                 continue;
267:             }
268:             // L1: soft-deleted or deactivated variants stay in the response as
269:             // unavailable lines so the shopper can remove them.
270:             if (! in_array($variant->id, $purchasableIds, true)) {
271:                 $lines[] = [
272:                     'item_id' => $item->id,
273:                     'variant' => $variant,
274:                     'qty' => (float) $item->qty,
275:                     'unit_price' => null,
276:                     'base_price' => null,
277:                     'line_discount' => 0.0,
278:                     'line_total' => 0.0,
279:                 ];
280: 
281:                 continue;
282:             }
283:             $qty = (float) $item->qty;
284:             try {
285:                 $resolved = $this->pricing->resolve($variant, $customer, $qty, ctx: $context);
286:                 $unit = (float) $resolved['unit_price'];
287:                 $base = (float) $resolved['base_price'];
288:                 $lines[] = [
289:                     'item_id' => $item->id,
290:                     'variant' => $variant,
291:                     'qty' => $qty,
292:                     'unit_price' => $unit,
293:                     'base_price' => $base,
294:                     // Customer-specific pricing higher than base price does not produce negative discounts.
295:                     'line_discount' => max(0.0, BigDecimal::of((string) $base)->minus((string) $unit)->multipliedBy((string) $qty)->toScale(2, RoundingMode::HalfUp)->toFloat()),
296:                     'line_total' => BigDecimal::of((string) $unit)->multipliedBy((string) $qty)->toScale(2, RoundingMode::HalfUp)->toFloat(),
297:                 ];
298:             } catch (BusinessException) {
299:                 $lines[] = [
300:                     'item_id' => $item->id,
301:                     'variant' => $variant,
302:                     'qty' => $qty,
303:                     'unit_price' => null,
304:                     'base_price' => null,
305:                     'line_discount' => 0.0,
306:                     'line_total' => 0.0,
307:                 ];
308:             }
309:         }
310: 
311:         return $lines;
312:     }
313: 
314:     /**
315:      * Calculates financial summary totals for the cart with real-time pricing and applied coupons.
316:      *
317:      * @param  array<int, array<string, mixed>>|null  $lines  Pre-computed priced lines to avoid redundant pricing calls.
318:      * @return array{subtotal: float, pricing_discount: float, items_total: float, coupon_discount: float, total: float, coupon_code: string|null}
319:      */
320:     public function totals(Cart $cart, ?Customer $customer, ?array $lines = null): array
321:     {
322:         $lines ??= $this->pricedLines($cart, $customer);
323:         $subtotalDecimal = BigDecimal::zero();
324:         $itemsDecimal = BigDecimal::zero();
325:         foreach ($lines as $line) {
326:             if ($line['unit_price'] === null) {
327:                 continue;
328:             }
329:             // Each line subtotal is rounded first, then aggregated to preserve exact currency arithmetic.
330:             $lineSubtotal = BigDecimal::of((string) $line['base_price'])->multipliedBy((string) $line['qty'])->toScale(2, RoundingMode::HalfUp);
331:             $subtotalDecimal = $subtotalDecimal->plus($lineSubtotal->isLessThan((string) $line['line_total']) ? (string) $line['line_total'] : $lineSubtotal);
332:             $itemsDecimal = $itemsDecimal->plus((string) $line['line_total']);
333:         }
334:         $subtotal = $subtotalDecimal->toFloat();
335:         $itemsTotal = $itemsDecimal->toFloat();
336: 
337:         // Pricing discount is the difference between rounded totals to prevent fractional cent rounding discrepancies.
338:         // Higher custom prices raise the base threshold to avoid negative discounts inflating the bill.
339:         if ($subtotal < $itemsTotal) {
340:             $subtotal = $itemsTotal;
341:             $pricingDiscount = 0.0;
342:         } else {
343:             $pricingDiscount = $subtotalDecimal->minus($itemsDecimal)->toScale(2, RoundingMode::HalfUp)->toFloat();
344:         }
345: 
346:         $couponDiscount = 0.0;
347:         $couponCode = null;
348:         if ($cart->coupon_id !== null && $itemsTotal > 0) {
349:             try {
350:                 $coupon = $this->coupons->redeemableById((int) $cart->coupon_id, $itemsTotal, $customer);
351:                 $couponDiscount = $this->coupons->discountFor($coupon, $itemsTotal);
352:                 $couponCode = $coupon->code;
353:             } catch (BusinessException) {
354:                 // Silently omit invalidated coupons from cart totals; checkout will re-verify strictly.
355:             }
356:         }
357: 
358:         return [
359:             'subtotal' => round($subtotal, 2),
360:             'pricing_discount' => round($pricingDiscount, 2),
361:             'items_total' => round($itemsTotal, 2),
362:             'coupon_discount' => $couponDiscount,
363:             'total' => $itemsDecimal->minus((string) $couponDiscount)->toScale(2, RoundingMode::HalfUp)->toFloat(),
364:             'coupon_code' => $couponCode,
365:         ];
366:     }
