368:     /**
369:      * Verifies that all cart line variants remain published and active for purchase.
370:      *
371:      * @param  array<int, array{variant: ProductVariant, qty: float}>  $lines
372:      */
373:     public function assertLinesPurchasable(array $lines): void
374:     {
375:         foreach ($lines as $line) {
376:             $this->assertWholeQuantity((float) $line['qty']);
377:         }
378:         $ids = array_map(fn (array $line): int => (int) $line['variant']->id, $lines);
379:         // H1: one batched refresh; the purchasability rule is the storefront
380:         // published rule (retail channel + active category path), not just
381:         // is_active/Published/trashed.
382:         $variants = $this->retailVariants()->whereIn('id', $ids)->pluck('id')->all();
383:         foreach ($lines as $line) {
384:             $variant = $line['variant'];
385:             if (! in_array($variant->id, $variants, true)) {
386:                 throw new BusinessException("الصنف ({$variant->sku}) لم يعد متاحًا للبيع؛ أزله من السلة وأعد المحاولة.");
387:             }
388:         }
389:     }
