391:     /**
392:      * Verifies that requested quantities for all lines are available in branch stock.
393:      *
394:      * @param  array<int, array{variant: ProductVariant, qty: float}>  $lines
395:      */
396:     public function assertLinesAvailable(array $lines): void
397:     {
398:         $ids = array_map(fn (array $line): int => (int) $line['variant']->id, $lines);
399:         $map = $this->catalog->availabilityMap($ids);
400:         foreach ($lines as $line) {
401:             if (($map[$line['variant']->id] ?? 0) < $line['qty']) {
402:                 throw new BusinessException("الكمية المتاحة من الصنف ({$line['variant']->sku}) لم تعد كافية لإتمام الطلب.");
403:             }
404:         }
405:     }
