407:     /**
408:      * Formats cart data, media urls, real-time availability, and totals for storefront presentation.
409:      *
410:      * @return array<string, mixed>
411:      */
412:     public function present(Cart $cart, ?Customer $customer): array
413:     {
414:         // Eager-load display relations up front: product + variant media for the
415:         // card image (same `images` collection as StoreProductCardResource via
416:         // Product::catalogImages — there is no `catalog` collection). Constant
417:         // cost regardless of line count (no N+1).
418:         $cart->loadMissing([
419:             'items.variant.product.media',
420:             'items.variant.product.variants.media',
421:         ]);
422:         $lines = $this->pricedLines($cart, $customer);
423:         $ids = array_map(fn (array $line): int => (int) $line['variant']->id, $lines);
424:         $availability = $this->catalog->availabilityMap($ids);
425: 
426:         $items = [];
427:         foreach ($lines as $line) {
428:             $variant = $line['variant'];
429:             $exact = (float) ($availability[$variant->id] ?? 0);
430:             // L2: never expose the exact branch-wide balance; shoppers only
431:             // need the purchasable ceiling. Unpriced lines report zero.
432:             $maxQty = $line['unit_price'] === null ? 0.0 : $this->maxPurchasableQty($exact, $customer);
433:             // Same image rule as StoreProductCardResource::toArray: first of
434:             // Product::catalogImages() (product `images`, then active variants'
435:             // `images`), thumb conversion when generated, original as fallback.
436:             $images = $variant->product !== null ? $variant->product->catalogImages() : collect();
437:             $first = $images->first();
438:             $items[] = [
439:                 'id' => $line['item_id'],
440:                 'product_variant_id' => $variant->id,
441:                 'product_id' => $variant->product_id,
442:                 'product_name' => $variant->product?->name_ar,
443:                 'product_slug' => $variant->product?->slug,
444:                 'product_name_en' => $variant->product?->name_en,
445:                 'image' => $first && $first->hasGeneratedConversion('thumb') ? $first->getUrl('thumb') : ($first?->getUrl() ?: null),
446:                 'color' => $variant->color_name_en ?? $variant->color_name_ar,
447:                 'size' => $variant->size ?? $variant->capacity,
448:                 'sku' => $variant->sku,
449:                 'qty' => $line['qty'],
450:                 'unit_price' => $line['unit_price'],
451:                 'base_price' => $line['base_price'],
452:                 'line_discount' => $line['line_discount'],
453:                 'line_total' => $line['line_total'],
454:                 'available' => $maxQty,
455:                 'max_qty' => $maxQty,
456:                 'priced' => $line['unit_price'] !== null,
457:             ];
458:         }
459: 
460:         return [
461:             'id' => $cart->id,
462:             'cart_token' => $cart->cart_token,
463:             'customer_id' => $cart->customer_id,
464:             'items' => $items,
465:             'totals' => $this->totals($cart, $customer, $lines),
466:         ];
467:     }
