492:     /**
493:      * Enforces maximum allowed purchase quantity per cart line for guests and retail users.
494:      */
495:     private function assertLineQty(?Customer $customer, float $qty): void
496:     {
497:         $cap = $this->lineQtyCap($customer);
498:         if ($cap > 0 && $qty > $cap) {
499:             throw new BusinessException($customer === null
500:                 ? "سقف كمية البند الواحد للزوار ({$cap}) — سجّل الدخول للكميات الأكبر."
501:                 : "سقف كمية البند الواحد ({$cap}) — للكميات الأكبر تواصل مع مسار الجملة.");
502:         }
503:     }
