505:     /**
506:      * Returns the effective quantity cap per cart line based on customer type (0 = uncapped for wholesale).
507:      */
508:     public function lineQtyCap(?Customer $customer): float
509:     {
510:         if ($customer === null) {
511:             return (float) config('store.guest_max_line_qty', 10);
512:         }
513:         if ($customer->status === CustomerStatus::Approved
514:             && in_array($customer->type, [CustomerType::Wholesale, CustomerType::Distributor], true)) {
515:             return 0.0;
516:         }
517: 
518:         return (float) config('store.retail_max_line_qty', 50);
519:     }
