521:     /**
522:      * Computes the maximum purchasable quantity considering branch availability and request caps.
523:      */
524:     public function maxPurchasableQty(float $available, ?Customer $customer): float
525:     {
526:         $cap = $this->lineQtyCap($customer);
527: 
528:         return max(0.0, min($available, self::MAX_REQUEST_QTY, $cap > 0 ? $cap : self::MAX_REQUEST_QTY));
529:     }
