364:     /**
365:      * Executes an order status transition and triggers corresponding inventory and payment side-effects.
366:      *
367:      * @param  array<int, OrderStatus>|null  $expectedFrom  Expected previous statuses to prevent race conditions.
368:      * @param  bool  $returnEffects  Whether to generate automatic stock and refund side effects for returns.
369:      * @param  bool  $allowNoticesLoss  Allows cancelling credit orders with approved wholesale payment notices.
370:      */
371:     public function changeStatus(Order $order, OrderStatus|string $toStatus, ?Model $actor = null, ?string $notes = null, ?array $expectedFrom = null, bool $returnEffects = true, bool $allowNoticesLoss = false): Order
372:     {
373:         $to = $toStatus instanceof OrderStatus ? $toStatus : OrderStatus::from($toStatus);
374: 
375:         return DB::transaction(function () use ($order, $to, $actor, $notes, $expectedFrom, $returnEffects, $allowNoticesLoss): Order {
