377:             $order = Order::query()->lockForUpdate()->findOrFail($order->id);
378:             $from = $order->status;
379: 
380:             if ($expectedFrom !== null && ! in_array($from, $expectedFrom, true)) {
381:                 throw new BusinessException("تغيّرت حالة الطلب أثناء العملية (أصبحت {$from->value})؛ أعد المحاولة.");
382:             }
383: 
384:             if ($from === $to) {
385:                 return $order;
386:             }
387: 
388:             if (! in_array($to->value, self::TRANSITIONS[$from->value] ?? [], true)) {
389:                 throw new BusinessException("انتقال حالة غير مسموح: من ({$from->value}) إلى ({$to->value}).");
390:             }
391: 
392:             $actorId = $this->inventoryActorId($actor);
393: 
394:             if ($to === OrderStatus::Returned && $returnEffects && $order->channel === 'pos') {
395:                 throw new BusinessException('استخدم مرتجع POS لتسوية المخزون والنقدية معًا.');
396:             }
397: 
398:             if ($to === OrderStatus::Returned && $returnEffects
399:                 && ReturnRequest::query()->where('order_id', $order->id)->whereNotIn('status', [
400:                     ReturnStatus::Rejected->value, ReturnStatus::Cancelled->value,
401:                 ])->exists()) {
402:                 throw new BusinessException('للطلب مرتجعات قائمة؛ أكمل الاستلام والاسترداد من إدارة المرتجعات لمنع تكرار المخزون.');
403:             }
404: 
405:             // Prevent silent cancellation of credit orders that hold approved wholesale treasury notices.
406:             if ($to === OrderStatus::Cancelled && ! $allowNoticesLoss
407:                 && $order->payment_method === 'credit'
408:                 && \App\Models\WholesalePaymentNotice::query()->where('order_id', $order->id)
409:                     ->where('status', \App\Enums\WholesalePaymentNoticeStatus::Approved->value)->exists()) {
410:                 throw new BusinessException('للطلب الآجل إشعارات سداد معتمدة مقيدة في الخزينة؛ سوِّها أولًا (رد أو تحويلها لائتمان حر) قبل الإلغاء.');
411:             }
412: 
413:             $extraNote = null;
414:             if ($to === OrderStatus::Shipped) {
415:                 $this->shipOrder($order, $actorId);
416:             } elseif ($to === OrderStatus::Cancelled
417:                 && in_array($from, [OrderStatus::Pending, OrderStatus::Confirmed, OrderStatus::Processing], true)) {
418:                 // Stock is reserved from creation time, so release reservations on cancellation.
419:                 $this->releaseReservations($order, $actorId, 'إلغاء الطلب');
420:             } elseif ($to === OrderStatus::Returned
421:                 && in_array($from, [OrderStatus::Shipped, OrderStatus::Delivered], true)
422:                 && $returnEffects) {
423:                 // Reverse sales in stock ledger unless handled by the warehouse RMA intake process.
424:                 if (! $this->returnSalesToStock($order, $actorId)) {
425:                     $extraNote = 'لا توجد حركات بيع مسجلة؛ يتطلب المرتجع استلامًا يدويًا في المستودع.';
426:                 }
427:             }
428: 
429:             if ($to === OrderStatus::Cancelled) {
430:                 // Restore coupon usage quota upon order cancellation.
431:                 $this->reverseCouponUsage($order);
432:                 if ($order->payment_status === 'paid') {
433:                     $order->update(['requires_refund' => true]);
434:                 }
435:             }
436: 
437:             // Flag paid returned order for refund processing.
438:             if ($to === OrderStatus::Returned && $order->payment_status === 'paid' && $returnEffects) {
439:                 $order->update(['requires_refund' => true]);
440:             }
441: 
442:             if ($order->payment_method === 'wallet' && $order->payment_status === 'paid'
443:                 && ($to === OrderStatus::Cancelled || ($to === OrderStatus::Returned && $returnEffects))) {
444:                 $payment = CustomerWalletTransaction::query()->where('reference_type', 'order')->where('reference_id', $order->id)
445:                     ->where('type', 'checkout_payment')->first();
446:                 if ($payment !== null) {
447:                     app(WalletService::class)->record($payment->customer_id, -(float) $payment->amount,
448:                         'order_reversal', 'order', $order->id, $actorId);
449:                     $order->update(['payment_status' => 'refunded', 'requires_refund' => false]);
450:                 }
451:             }
452: 
453:             $order->update(['status' => $to]);
454: 
455:             // Auto-settle COD payment status upon delivery.
456:             if ($to === OrderStatus::Delivered
457:                 && $order->payment_method === 'cod'
458:                 && $order->payment_status !== 'paid') {
459:                 $order->update(['payment_status' => 'paid']);
460:             }
461: 
462:             // Truncate notes to fit the varchar(500) database column limit.
463:             $historyNotes = trim(($notes ?? '').($extraNote !== null ? ' — '.$extraNote : '')) ?: $notes;
464: 
465:             $order->statusHistories()->create([
466:                 'from_status' => $from,
467:                 'to_status' => $to,
468:                 'changed_by_type' => $actor?->getMorphClass(),
469:                 'changed_by_id' => $actor?->getKey(),
470:                 'notes' => $historyNotes !== null ? mb_substr($historyNotes, 0, 500) : null,
471:             ]);
472: 
473:             // Trigger item allocation if the order transitioned to confirmed without full allocation.
474:             if ($to === OrderStatus::Confirmed && ! $this->isAllocated($order)) {
475:                 $this->allocationService->allocate($order, performedBy: $actorId);
476:             }
477: 
478:             return $order->fresh(['items', 'statusHistories']);
479:         });
480:     }
481: 
482:     /**
483:      * Checks whether all order items have been allocated to fulfillment branches.
484:      */
485:     private function isAllocated(Order $order): bool
486:     {
487:         if ($order->allocated_branch_id !== null) {
488:             return true;
489:         }
490: 
491:         $distribution = $order->items()
492:             ->selectRaw('COUNT(*) AS total, COUNT(allocated_branch_id) AS allocated')
493:             ->first();
494: 
495:         if ($distribution === null || (int) $distribution->total === 0) {
496:             return false;
497:         }
498: 
499:         return (int) $distribution->total === (int) $distribution->allocated;
500:     }
501: 
502:     /**
503:      * Checks if customer has approved wholesale/distributor status exempt from retail limits.
504:      */
505:     private function isWholesaleApproved(?Customer $customer): bool
506:     {
507:         return $customer !== null
508:             && $customer->status === CustomerStatus::Approved
509:             && in_array($customer->type, [CustomerType::Wholesale, CustomerType::Distributor], true);
510:     }
511: 
512:     /**
513:      * Distributes a total currency amount across weights using Hare-Niemeyer (largest remainder) algorithm.
514:      *
515:      * @param  array<int, float>  $weights
516:      * @return array<int, float>
517:      */
518:     private function distributeLargestRemainder(float $total, array $weights): array
519:     {
520:         $count = count($weights);
521:         if ($count === 0) {
522:             return [];
523:         }
524:         $totalCents = (int) round($total * 100);
525:         $weightSum = array_sum($weights);
526:         if ($totalCents <= 0 || $weightSum <= 0) {
527:             return array_fill(0, $count, 0.0);
528:         }
529: 
530:         $floorCents = [];
531:         $remainders = [];
532:         $assigned = 0;
533:         foreach ($weights as $i => $weight) {
534:             $exact = $totalCents * ((float) $weight / $weightSum);
535:             $floor = (int) floor($exact);
536:             $floorCents[$i] = $floor;
537:             $remainders[$i] = $exact - $floor;
538:             $assigned += $floor;
539:         }
540: 
541:         $left = $totalCents - $assigned;
542:         arsort($remainders);
543:         foreach (array_keys($remainders) as $i) {
544:             if ($left <= 0) {
545:                 break;
546:             }
547:             $floorCents[$i]++;
548:             $left--;
549:         }
550: 
551:         ksort($floorCents);
552: 
553:         return array_map(fn (int $cents): float => $cents / 100, $floorCents);
554:     }
555: 
556:     /**
557:      * Releases reservations and records sale stock movements for all items in the order.
558:      */
559:     private function shipOrder(Order $order, ?int $actorId): void
560:     {
561:         $net = $this->netReservations($order);
562:         if ($net->isEmpty()) {
563:             throw new BusinessException('لا توجد حجوزات مخزون لهذا الطلب؛ لا يمكن الشحن قبل التأكيد والتوزيع.');
564:         }
565: 
566:         $levels = $this->inventoryService->lockLevels($net->map(fn (array $row): array => [
567:             'product_variant_id' => $row['product_variant_id'],
568:             'branch_id' => $row['branch_id'],
569:             'location_id' => $row['location_id'],
570:         ])->all());
571: 
572:         $costs = ProductVariant::withTrashed()->whereIn('id', $net->pluck('product_variant_id'))->pluck('cost_price', 'id');
573:         foreach ($net as $row) {
574:             $base = [
575:                 'product_variant_id' => $row['product_variant_id'],
576:                 'branch_id' => $row['branch_id'],
577:                 'location_id' => $row['location_id'],
578:                 'reference_type' => Order::class,
579:                 'reference_id' => $order->id,
580:                 'created_by' => $actorId,
581:             ];
582:             $level = $levels->get($this->inventoryService->levelKey($row));
583:             $this->inventoryService->recordMovement([...$base,
584:                 'type' => StockMovementType::ReleaseReserve,
585:                 'affected_bucket' => StockBucket::Reserved,
586:                 'quantity' => -1 * (float) $row['net_qty'],
587:                 'notes' => "فك حجز عند شحن الطلب {$order->order_number}",
588:             ], $level);
589:             $this->inventoryService->recordMovement([...$base,
590:                 'type' => StockMovementType::Sale,
591:                 'unit_cost' => $costs[$row['product_variant_id']] ?? null,
592:                 'affected_bucket' => StockBucket::OnHand,
593:                 'quantity' => -1 * (float) $row['net_qty'],
594:                 'notes' => "بيع عند شحن الطلب {$order->order_number}",
595:             ], $level);
596:         }
597: 
598:         foreach ($order->items as $item) {
599:             $item->variant?->product?->increment('sales_count', (int) round((float) $item->qty));
600:         }
601:     }
602: 
603:     /**
604:      * Releases active stock reservations for cancelled orders back into available inventory.
605:      */
606:     private function releaseReservations(Order $order, ?int $actorId, string $reason): void
607:     {
608:         $net = $this->netReservations($order);
609:         if ($net->isEmpty()) {
610:             return;
611:         }
612: 
613:         $levels = $this->inventoryService->lockLevels($net->map(fn (array $row): array => [
614:             'product_variant_id' => $row['product_variant_id'],
615:             'branch_id' => $row['branch_id'],
616:             'location_id' => $row['location_id'],
617:         ])->all());
618: 
619:         foreach ($net as $row) {
620:             $this->inventoryService->recordMovement([
621:                 'product_variant_id' => $row['product_variant_id'],
622:                 'branch_id' => $row['branch_id'],
623:                 'location_id' => $row['location_id'],
624:                 'type' => StockMovementType::ReleaseReserve,
625:                 'affected_bucket' => StockBucket::Reserved,
626:                 'quantity' => -1 * (float) $row['net_qty'],
627:                 'reference_type' => Order::class,
628:                 'reference_id' => $order->id,
629:                 'created_by' => $actorId,
630:                 'notes' => "{$reason} {$order->order_number}",
631:             ], $levels->get($this->inventoryService->levelKey($row)));
632:         }
633:     }
634: 
635:     /**
636:      * Restores delivered/shipped goods to on-hand inventory via SaleReturn stock movements.
637:      */
638:     private function returnSalesToStock(Order $order, ?int $actorId): bool
639:     {
640:         $net = StockMovement::query()
641:             ->whereIn('reference_type', array_unique([$order->getMorphClass(), Order::class]))
642:             ->where('reference_id', $order->id)
643:             ->whereIn('type', [StockMovementType::Sale->value, StockMovementType::SaleReturn->value])
644:             ->groupBy('product_variant_id', 'branch_id', 'location_id')
645:             ->selectRaw('product_variant_id, branch_id, location_id, SUM(quantity) AS net_qty, MAX(unit_cost) FILTER (WHERE type = \'sale\') AS sale_unit_cost')
646:             ->get()
647:             // Negative net represents un-returned sales (Sale is negative, SaleReturn is positive).
648:             ->map(fn ($row): array => [
649:                 'product_variant_id' => (int) $row->product_variant_id,
650:                 'branch_id' => (int) $row->branch_id,
651:                 'location_id' => $row->location_id === null ? null : (int) $row->location_id,
652:                 'net_qty' => (float) $row->net_qty,
653:                 'sale_unit_cost' => $row->sale_unit_cost,
654:             ])
655:             ->filter(fn (array $row): bool => $row['net_qty'] < -1e-9)
656:             ->sortBy(fn (array $row): string => $row['branch_id'].':'.$row['location_id'].':'.$row['product_variant_id'])
657:             ->values();
658: 
659:         if ($net->isEmpty()) {
660:             return false;
661:         }
662: 
663:         $levels = $this->inventoryService->lockLevels($net->map(fn (array $row): array => [
664:             'product_variant_id' => $row['product_variant_id'],
665:             'branch_id' => $row['branch_id'],
666:             'location_id' => $row['location_id'],
667:         ])->all());
668: 
669:         foreach ($net as $row) {
670:             $this->inventoryService->recordMovement([
671:                 'product_variant_id' => $row['product_variant_id'],
672:                 'branch_id' => $row['branch_id'],
673:                 'location_id' => $row['location_id'],
674:                 'type' => StockMovementType::SaleReturn,
675:                 'affected_bucket' => StockBucket::OnHand,
676:                 'quantity' => -1 * (float) $row['net_qty'],
677:                 'unit_cost' => $row['sale_unit_cost'],
678:                 'reference_type' => Order::class,
679:                 'reference_id' => $order->id,
680:                 'created_by' => $actorId,
681:                 'notes' => "مرتجع مبيعات للطلب {$order->order_number}",
682:             ], $levels->get($this->inventoryService->levelKey($row)));
683:         }
684: 
685:         foreach ($order->items as $item) {
686:             if ($item->variant?->product_id) {
687:                 Product::query()->whereKey($item->variant->product_id)
688:                     ->update(['sales_count' => DB::raw('GREATEST(sales_count - '.(int) round((float) $item->qty).', 0)')]);
689:             }
690:         }
691: 
692:         return true;
693:     }
694: 
695:     /**
696:      * Computes net active stock reservations per variant/location for an order.
697:      *
698:      * @return Collection<int, array{product_variant_id: int, branch_id: int, location_id: int|null, net_qty: float}>
699:      */
700:     private function netReservations(Order $order): Collection
701:     {
702:         return StockMovement::query()
703:             ->whereIn('reference_type', array_unique([$order->getMorphClass(), Order::class]))
704:             ->where('reference_id', $order->id)
705:             ->whereIn('type', [StockMovementType::Reserve->value, StockMovementType::ReleaseReserve->value])
706:             ->groupBy('product_variant_id', 'branch_id', 'location_id')
707:             ->selectRaw('product_variant_id, branch_id, location_id, SUM(quantity) AS net_qty')
708:             ->get()
709:             ->map(fn ($row): array => [
710:                 'product_variant_id' => (int) $row->product_variant_id,
711:                 'branch_id' => (int) $row->branch_id,
712:                 'location_id' => $row->location_id === null ? null : (int) $row->location_id,
713:                 'net_qty' => (float) $row->net_qty,
714:             ])
715:             ->filter(fn (array $row): bool => $row['net_qty'] > 1e-9)
716:             ->sortBy(fn (array $row): string => $row['branch_id'].':'.$row['location_id'].':'.$row['product_variant_id'])
717:             ->values();
718:     }
719: 
720:     /**
721:      * Reverses recorded coupon usage and decrements used_count on order cancellation.
722:      */
723:     private function reverseCouponUsage(Order $order): void
724:     {
725:         foreach (CouponUsage::query()->where('order_id', $order->id)->get() as $usage) {
726:             Coupon::query()->whereKey($usage->coupon_id)->where('used_count', '>', 0)->decrement('used_count');
727:             $usage->delete();
728:         }
729:     }
730: 
731:     /**
732:      * Retrieves original stock reserve movements associated with an order.
733:      */
734:     private function reserveMovements(Order $order): Collection
735:     {
736:         return StockMovement::query()
737:             ->whereIn('reference_type', array_unique([$order->getMorphClass(), Order::class]))
738:             ->where('reference_id', $order->id)
739:             ->where('type', StockMovementType::Reserve)
740:             ->orderBy('id')
741:             ->get();
742:     }
