744:     // Instance-level cache avoids cross-test/Octane bleed of static properties.
745:     private ?int $systemActorId = null;
746: 
747:     private bool $systemActorResolved = false;
748: 
749:     /**
750:      * Resolves the user identity responsible for stock ledger entries.
751:      *
752:      * Falls back to dedicated system user for automated actions (webhooks, guest checkout).
753:      */
754:     private function inventoryActorId(?Model $actor): ?int
755:     {
756:         if ($actor instanceof User) {
757:             return (int) $actor->getKey();
758:         }
759: 
760:         if (! $this->systemActorResolved) {
761:             $this->systemActorResolved = true;
762:             $systemId = User::query()
763:                 ->where('is_system', true)
764:                 ->value('id');
765:             $this->systemActorId = $systemId !== null ? (int) $systemId : null;
766:         }
767:         if ($this->systemActorId !== null) {
768:             return $this->systemActorId;
769:         }
770: 
771:         throw new \LogicException('The System audit identity is missing; run the system-user migration before processing automated order effects.');
772:     }
773: }
